struct VariableControlCompositeTrackWorldImage {
    DirectCompositeTrackWorldImage schedule;
    std::array<harken::PlayablePropertyProgramViewV1, 4> properties{};
    std::array<harken::PlayableOccurrencePropertyViewV1, 4> occurrences{};
    std::array<harken::ContainerChildProgramViewV2, 2> children{};
    harken::GridAxisV1 axis{0, 0, harkentest::ObjectId(41)};
    std::array<harken::DiscreteGridCellV1, 2> cells{};
    std::array<harken::DiscreteGridRowViewV1, 2> rows{};
    std::array<harken::CurveV1, 2> transitionCurves{};
    harken::TransitionRuleViewV1 transitionRule{};
    harken::TransitionProgramViewV1 transition{};
    harken::ContainerProgramViewV3 container{};
    harken::PlayableWorldViewV1 world{};

    VariableControlCompositeTrackWorldImage(
        std::uint64_t firstRevision, std::uint64_t secondRevision,
        harken::WorldGeneration generation)
        : schedule(firstRevision, secondRevision) {
        std::copy(schedule.properties.begin(), schedule.properties.end(),
                  properties.begin());
        schedule.placements[1].authoredStart = 0;
        schedule.track.scheduleSemanticFingerprint =
            harken::ComputeTrackScheduleFingerprintV1(schedule.track);
        properties[3].contentPropertyKind =
            harken::playableproperties::ContentPropertyKindV1::Container;
        properties[3].stableId = harkentest::ObjectId(kContainer);
        properties[3].authoredStableOrder = 3;
        properties[3].contentRevision = kContainerRevision;
        properties[3].routeStableId = VN_BUS_MASTER;
        properties[3].compatibilityFingerprint = 4;
        properties[3].payload = ResolvedPayload();
        properties[3].programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(properties[3]);

        children[0].stableChildOrdinal = 7;
        children[0].playable = schedule.placements[0].content;
        children[1].stableChildOrdinal = 9;
        children[1].authoredStableOrder = 1;
        children[1].playable = schedule.track.rootDefinition;
        for (std::uint32_t index = 0; index < children.size(); ++index) {
            occurrences[index].parentKind =
                harken::playableproperties::ContentPropertyKindV1::Container;
            occurrences[index].parentStableId = harkentest::ObjectId(kContainer);
            occurrences[index].parentProgramSemanticFingerprint =
                properties[3].programSemanticFingerprint;
            occurrences[index].stableOccurrenceOrdinal =
                children[index].stableChildOrdinal;
            occurrences[index].childPlayable = children[index].playable;
            occurrences[index].payload = CanonicalPayload();
            occurrences[index].occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(
                    occurrences[index]);
            cells[index].kind = harken::DiscreteCellKindV1::Exact;
            cells[index].exactValue = index == 0 ? 3 : 7;
            rows[index].stableRowOrdinal = index + 1u;
            rows[index].authoredStableOrder = index;
            rows[index].childStableOrdinal =
                children[index].stableChildOrdinal;
            rows[index].cellCount = 1;
            rows[index].cells = &cells[index];
            occurrences[index + 2u] = schedule.occurrences[index];
        }
        container.containerStableId = harkentest::ObjectId(kContainer);
        container.programSemanticFingerprint =
            properties[3].programSemanticFingerprint;
        container.mode = harken::ContainerModeV1::VariableControl;
        container.childCount = children.size();
        container.children = children.data();
        container.discreteTiming = 1;
        container.discreteAxisCount = 1;
        container.discreteAxes = &axis;
        container.discreteRowCount = rows.size();
        container.discreteRows = rows.data();
        container.evaluationPeriodFrames = 64;
        container.maxActiveRows = 0;
        container.maxLiveRows = 0;
        container.transitionProgramIndex = 0;
        transitionCurves = {
            TransitionFadeCurve(1), TransitionFadeCurve(2)};
        container.curveCount = transitionCurves.size();
        container.curves = transitionCurves.data();
        transitionRule.stableRuleOrdinal = 1;
        transitionRule.sourceAny = 1;
        transitionRule.targetAny = 1;
        transition.ownerContainerStableId = harkentest::ObjectId(kContainer);
        transition.ruleCount = 1;
        transition.defaultRuleIndex = 0;
        transition.rules = &transitionRule;

        world.generation = generation;
        world.identity.capabilityMask =
            harken::kWorldCapabilityVariableDefinitions |
            harken::kWorldCapabilityPlayableProperties |
            harken::kWorldCapabilityVariableControl |
            harken::kWorldCapabilityTransition;
        world.identity.runtimeSemanticFingerprint =
            UINT64_C(0x56434D554C544954);
        world.properties = properties.data();
        world.propertyCount = properties.size();
        world.occurrences = occurrences.data();
        world.occurrenceCount = occurrences.size();
        world.trackSchedules = &schedule.track;
        world.trackScheduleCount = 1;
        world.containers = &container;
        world.containerCount = 1;
        world.transitions = &transition;
        world.transitionCount = 1;
    }

    void SetImmediateFades(std::uint32_t sourceFrames,
                           std::uint32_t targetFrames) {
        transitionRule.sourceExit =
            harken::TransitionSourceExitV1::Immediate;
        transitionRule.sourceFade.active = sourceFrames != 0;
        transitionRule.sourceFade.durationFrames = sourceFrames;
        transitionRule.sourceFade.curveLocalId =
            sourceFrames != 0 ? transitionCurves[0].curveLocalId
                              : UINT32_MAX;
        transitionRule.targetFade.active = targetFrames != 0;
        transitionRule.targetFade.durationFrames = targetFrames;
        transitionRule.targetFade.curveLocalId =
            targetFrames != 0 ? transitionCurves[1].curveLocalId
                              : UINT32_MAX;
    }

    void SetNaturalEndFades(std::uint32_t sourceFrames,
                            std::uint32_t targetFrames) {
        SetImmediateFades(sourceFrames, targetFrames);
        transitionRule.sourceExit =
            harken::TransitionSourceExitV1::NaturalEnd;
    }

    harken::PlayableRefV1 Root() const {
        harken::PlayableRefV1 root{};
        root.kind = harken::PlayableKindV1::Container;
        root.stableId = harkentest::ObjectId(kContainer);
        root.expectedProgramSemanticFingerprint =
            properties[3].programSemanticFingerprint;
        root.contentRevision = properties[3].contentRevision;
        root.routeStableId = VN_BUS_MASTER;
        root.compatibilityFingerprint = 4;
        return root;
    }
};

struct VariableControlLogicalTracksWorldImage {
    std::array<harken::PlayablePropertyProgramViewV1, 5> properties{};
    std::array<harken::PlayableOccurrencePropertyViewV1, 4> occurrences{};
    std::array<harken::ScheduleClipPlacementV1, 2> placements{};
    std::array<harken::TrackScheduleProgramViewV1, 2> tracks{};
    std::array<harken::ContainerChildProgramViewV2, 2> children{};
    harken::GridAxisV1 axis{0, 0, harkentest::ObjectId(41)};
    std::array<harken::ContinuousGridCellV1, 2> cells{};
    std::array<harken::ContinuousGridRowViewV1, 2> rows{};
    harken::ContainerProgramViewV3 container{};
    harken::PlayableWorldViewV1 world{};

    VariableControlLogicalTracksWorldImage(
        std::uint64_t firstRevision, std::uint64_t secondRevision,
        harken::WorldGeneration generation) {
        const std::array<VnObjectId, 2> soundIds = {kSound, kSecondSound};
        const std::array<std::uint64_t, 2> revisions = {
            firstRevision, secondRevision};
        for (std::uint32_t index = 0; index < 2; ++index) {
            properties[index].contentPropertyKind =
                harken::playableproperties::ContentPropertyKindV1::Sound;
            properties[index].stableId = harkentest::ObjectId(soundIds[index]);
            properties[index].authoredStableOrder = index;
            properties[index].contentRevision = revisions[index];
            properties[index].routeStableId = VN_BUS_MASTER;
            properties[index].compatibilityFingerprint = index + 1u;
            properties[index].payload = ResolvedPayload();
            properties[index].programSemanticFingerprint =
                harken::ComputePlayablePropertyFingerprintV1(properties[index]);

            auto& trackProperty = properties[2 + index];
            trackProperty.contentPropertyKind =
                harken::playableproperties::ContentPropertyKindV1::Track;
            trackProperty.stableId = harkentest::ObjectId(3001u + index);
            trackProperty.authoredStableOrder = 2u + index;
            trackProperty.contentRevision = 4001u + index;
            trackProperty.routeStableId = VN_BUS_MASTER;
            trackProperty.compatibilityFingerprint = 3u + index;
            trackProperty.payload = ResolvedPayload();
            trackProperty.programSemanticFingerprint =
                harken::ComputePlayablePropertyFingerprintV1(trackProperty);

            placements[index].stablePlacementOrdinal = 0;
            placements[index].stableOccurrenceOrdinal = 20u + index;
            placements[index].content.kind = harken::PlayableKindV1::Sound;
            placements[index].content.stableId =
                harkentest::ObjectId(soundIds[index]);
            placements[index].content.expectedProgramSemanticFingerprint =
                properties[index].programSemanticFingerprint;
            placements[index].content.contentRevision = revisions[index];
            placements[index].content.routeStableId = VN_BUS_MASTER;
            placements[index].content.compatibilityFingerprint = index + 1u;
            placements[index].authoredStart =
                index == 0 ? INT64_C(1000000000) : INT64_C(2000000000);
            placements[index].authoredDuration = 1;
            placements[index].clipId = harkentest::ObjectId(5001u + index);
            placements[index].clipGuidHigh = 6001u + index;
            placements[index].clipGuidLow = 7001u + index;

            tracks[index].rootDefinition.kind = harken::PlayableKindV1::Track;
            tracks[index].rootDefinition.stableId = trackProperty.stableId;
            tracks[index].rootDefinition.expectedProgramSemanticFingerprint =
                trackProperty.programSemanticFingerprint;
            tracks[index].rootDefinition.contentRevision =
                trackProperty.contentRevision;
            tracks[index].rootDefinition.routeStableId = VN_BUS_MASTER;
            tracks[index].rootDefinition.compatibilityFingerprint =
                trackProperty.compatibilityFingerprint;
            tracks[index].placementCount = 1;
            tracks[index].placements = &placements[index];
            tracks[index].scheduleSemanticFingerprint =
                harken::ComputeTrackScheduleFingerprintV1(tracks[index]);

            children[index].stableChildOrdinal = 7u + 2u * index;
            children[index].authoredStableOrder = index;
            children[index].playable = tracks[index].rootDefinition;
            children[index].timingHint = harken::MakeScheduleReferenceTimingHint(
                harken::PlayableKindV1::Track,
                tracks[index].rootDefinition.stableId,
                tracks[index].scheduleSemanticFingerprint);

            occurrences[index].parentKind =
                harken::playableproperties::ContentPropertyKindV1::Container;
            occurrences[index].parentStableId = harkentest::ObjectId(kContainer);
            occurrences[index].parentProgramSemanticFingerprint =
                properties[4].programSemanticFingerprint;
            occurrences[index].stableOccurrenceOrdinal =
                children[index].stableChildOrdinal;
            occurrences[index].childPlayable = children[index].playable;
            occurrences[index].payload = CanonicalPayload();
            occurrences[index].occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(
                    occurrences[index]);

            occurrences[2 + index].parentKind =
                harken::playableproperties::ContentPropertyKindV1::Track;
            occurrences[2 + index].parentStableId =
                tracks[index].rootDefinition.stableId;
            occurrences[2 + index].parentProgramSemanticFingerprint =
                tracks[index].rootDefinition.expectedProgramSemanticFingerprint;
            occurrences[2 + index].stableOccurrenceOrdinal =
                placements[index].stableOccurrenceOrdinal;
            occurrences[2 + index].childPlayable = placements[index].content;
            occurrences[2 + index].payload = CanonicalPayload();
            occurrences[2 + index].occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(
                    occurrences[2 + index]);

            cells[index].kind = harken::ContinuousCellKindV1::Interval;
            cells[index].lower = 0.0f;
            cells[index].upper = index == 0 ? 4.0f : 8.0f;
            cells[index].lowerInclusive = 1;
            cells[index].upperInclusive = 1;
            rows[index].stableRowOrdinal = index + 1u;
            rows[index].authoredStableOrder = index;
            rows[index].childStableOrdinal = children[index].stableChildOrdinal;
            rows[index].cellCount = 1;
            rows[index].cells = &cells[index];
        }

        properties[4].contentPropertyKind =
            harken::playableproperties::ContentPropertyKindV1::Container;
        properties[4].stableId = harkentest::ObjectId(kContainer);
        properties[4].authoredStableOrder = 4;
        properties[4].contentRevision = kContainerRevision;
        properties[4].routeStableId = VN_BUS_MASTER;
        properties[4].compatibilityFingerprint = 5;
        properties[4].payload = ResolvedPayload();
        properties[4].programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(properties[4]);
        for (std::uint32_t index = 0; index < 2; ++index) {
            occurrences[index].parentProgramSemanticFingerprint =
                properties[4].programSemanticFingerprint;
            occurrences[index].occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(
                    occurrences[index]);
        }

        container.containerStableId = harkentest::ObjectId(kContainer);
        container.programSemanticFingerprint =
            properties[4].programSemanticFingerprint;
        container.mode = harken::ContainerModeV1::VariableControl;
        container.childCount = children.size();
        container.children = children.data();
        container.continuousAxisCount = 1;
        container.continuousAxes = &axis;
        container.continuousRowCount = rows.size();
        container.continuousRows = rows.data();
        container.evaluationPeriodFrames = 64;
        container.envelopeFrames = 2;
        container.maxActiveRows = 2;
        container.maxLiveRows = 2;

        world.generation = generation;
        world.identity.capabilityMask =
            harken::kWorldCapabilityVariableDefinitions |
            harken::kWorldCapabilityPlayableProperties |
            harken::kWorldCapabilityVariableControl;
        world.identity.runtimeSemanticFingerprint =
            UINT64_C(0x56434C4F47494341);
        world.properties = properties.data();
        world.propertyCount = properties.size();
        world.occurrences = occurrences.data();
        world.occurrenceCount = occurrences.size();
        world.trackSchedules = tracks.data();
        world.trackScheduleCount = tracks.size();
        world.containers = &container;
        world.containerCount = 1;
    }

    void MakeFirstTrackPhysical() {
        placements[0].authoredStart = 0;
        placements[0].authoredDuration = 0;
        tracks[0].scheduleSemanticFingerprint =
            harken::ComputeTrackScheduleFingerprintV1(tracks[0]);
        children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track,
            tracks[0].rootDefinition.stableId,
            tracks[0].scheduleSemanticFingerprint);
    }

    harken::PlayableRefV1 Root() const {
        harken::PlayableRefV1 root{};
        root.kind = harken::PlayableKindV1::Container;
        root.stableId = properties[4].stableId;
        root.expectedProgramSemanticFingerprint =
            properties[4].programSemanticFingerprint;
        root.contentRevision = properties[4].contentRevision;
        root.routeStableId = properties[4].routeStableId;
        root.compatibilityFingerprint =
            properties[4].compatibilityFingerprint;
        return root;
    }
};

struct VariableControlCompositeCapacityWorldImage
    : VariableControlCompositeTrackWorldImage {
    static constexpr std::uint32_t kContinuousRows = 16;
    std::array<harken::ContainerChildProgramViewV2,
               kContinuousRows + 2u> expandedChildren{};
    std::array<harken::PlayableOccurrencePropertyViewV1,
               kContinuousRows + 4u> expandedOccurrences{};
    harken::GridAxisV1 continuousAxis{0, 0, harkentest::ObjectId(42)};
    std::array<harken::ContinuousGridCellV1, kContinuousRows>
        continuousCells{};
    std::array<harken::ContinuousGridRowViewV1, kContinuousRows>
        continuousRows{};

    VariableControlCompositeCapacityWorldImage(
        std::uint64_t firstRevision, std::uint64_t secondRevision,
        harken::WorldGeneration generation)
        : VariableControlCompositeTrackWorldImage(
              firstRevision, secondRevision, generation) {
        expandedChildren[0] = children[0];
        expandedChildren[1] = children[1];
        expandedOccurrences[0] = occurrences[0];
        expandedOccurrences[1] = occurrences[1];
        for (std::uint32_t index = 0; index < kContinuousRows; ++index) {
            harken::ContainerChildProgramViewV2& child =
                expandedChildren[index + 2u];
            child = children[0];
            child.stableChildOrdinal = 11u + index;
            child.authoredStableOrder = index + 2u;

            harken::PlayableOccurrencePropertyViewV1& occurrence =
                expandedOccurrences[index + 2u];
            occurrence = occurrences[0];
            occurrence.stableOccurrenceOrdinal =
                child.stableChildOrdinal;
            occurrence.childPlayable = child.playable;
            occurrence.occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(occurrence);

            harken::ContinuousGridCellV1& cell = continuousCells[index];
            cell.kind = harken::ContinuousCellKindV1::Interval;
            cell.lower = 0.0f;
            cell.upper = 4.0f;
            cell.lowerInclusive = 1;
            cell.upperInclusive = 1;

            harken::ContinuousGridRowViewV1& row = continuousRows[index];
            row.stableRowOrdinal = index + 3u;
            row.authoredStableOrder = index;
            row.childStableOrdinal = child.stableChildOrdinal;
            row.cellCount = 1;
            row.cells = &cell;
        }
        expandedOccurrences[kContinuousRows + 2u] = occurrences[2];
        expandedOccurrences[kContinuousRows + 3u] = occurrences[3];
        container.childCount = expandedChildren.size();
        container.children = expandedChildren.data();
        container.continuousAxisCount = 1;
        container.continuousAxes = &continuousAxis;
        container.continuousRowCount = continuousRows.size();
        container.continuousRows = continuousRows.data();
        container.maxActiveRows = kContinuousRows;
        container.maxLiveRows = kContinuousRows;
        world.occurrences = expandedOccurrences.data();
        world.occurrenceCount = expandedOccurrences.size();
        world.identity.runtimeSemanticFingerprint =
            UINT64_C(0x5643434F4D504341);
    }
};

