std::uint64_t KnownFiniteQueuePublishableStart(const harken::Engine& engine) {
    const std::uint32_t blockFrames = engine.config.blockFrames;
    const std::uint64_t cutoff = engine.timelinePool.PublishCutoffFrame();
    if (blockFrames == 0) {
        return cutoff;
    }
    const std::uint64_t leadQuanta = std::max<std::uint64_t>(
        1u, engine.timelinePool.PublishLeadQuanta());
    const std::uint32_t periodFrames =
        engine.config.mixRate.SampleRate() / 50u;
    const std::uint32_t periodQuanta =
        periodFrames == 0
            ? 0u
            : (periodFrames + blockFrames - 1u) / blockFrames;
    const std::uint64_t mixAheadQuanta = std::max<std::uint64_t>(
        leadQuanta, static_cast<std::uint64_t>(periodQuanta) + 1u);
    const std::uint64_t publishableQuantum =
        engine.mixer.BlocksRendered() + mixAheadQuanta + 2u;
    return std::max(cutoff, publishableQuantum * blockFrames);
}

bool PumpUntilAudible(harken::Engine& engine) {
    std::uint64_t startFrame = 0;
    for (const auto& row : engine.playableServices) {
        if (row.phase != harken::EnginePlayableStartPhase::Free) {
            startFrame = std::max(startFrame, row.startFrame);
        }
    }
    if (startFrame == 0) {
        startFrame = KnownFiniteQueuePublishableStart(engine);
    }
    const std::uint32_t blockFrames = engine.config.blockFrames;
    const std::uint64_t now = engine.mixer.BlocksRendered();
    const std::uint64_t startQuantum =
        blockFrames == 0 ? now : startFrame / blockFrames;
    const std::uint64_t target =
        std::max(now + 16u, startQuantum + 8u);
    while (engine.mixer.BlocksRendered() <= target) {
        if (Vn_Update() != VN_OK) return false;
        engine.nullBackend.Pump(1);
        const float* output = engine.nullBackend.LastBlock();
        if (std::any_of(output, output + 2u * engine.config.blockFrames,
                        [](float sample) { return sample != 0.0f; })) {
            return true;
        }
    }
    return false;
}

enum class HandoffKind : std::uint8_t {
    RandomQueue,
    SequenceQueue,
    Sequence,
    Random,
    RandomRotation,
    VariableControl,
};

const char* HandoffKindName(HandoffKind kind) {
    switch (kind) {
        case HandoffKind::RandomQueue:
            return "RandomQueue";
        case HandoffKind::SequenceQueue:
            return "SequenceQueue";
        case HandoffKind::Sequence:
            return "Sequence";
        case HandoffKind::Random:
            return "Random";
        case HandoffKind::RandomRotation:
            return "RandomRotation";
        case HandoffKind::VariableControl:
            return "VariableControl";
    }
    return "?";
}

harken::ContainerWorldInstallViewV1 PlayableWorldInstall(
    const harken::PlayableWorldViewV1& world) {
    harken::ContainerWorldInstallViewV1 install{};
    install.identity = world.identity;
    install.playableProperties = world.properties;
    install.playablePropertyCount = world.propertyCount;
    install.playableOccurrences = world.occurrences;
    install.playableOccurrenceCount = world.occurrenceCount;
    install.containers = world.containers;
    install.containerCount = world.containerCount;
    install.transitions = world.transitions;
    install.transitionCount = world.transitionCount;
    install.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(install);
    return install;
}

void ApplyQueueLoop(harken::ContainerProgramViewV3& container,
                    std::uint32_t loopCount) {
    if (loopCount == 1) {
        container.queueCycle = harken::QueueCycleV1::Once;
        container.queueCycleCount = 0;
    } else {
        container.queueCycle = harken::QueueCycleV1::Loop;
        container.queueCycleCount = loopCount;
    }
}

bool PlayableRowsFree(const harken::Engine& engine) {
    return std::none_of(
        engine.playableServices.begin(), engine.playableServices.end(),
        [](const harken::EnginePlayableServiceRow& row) {
            return row.phase != harken::EnginePlayableStartPhase::Free;
        });
}

std::size_t CurrentMemberSlot(const harken::Engine& engine, std::size_t logicalSlot) {
    std::size_t physicalSlot = logicalSlot;
    EXPECT_TRUE(engine.ResolvePlayableMemberSlot(logicalSlot, &physicalSlot));
    return physicalSlot;
}

std::string OccupancyDump(const harken::Engine& engine) {
    std::array<harken::Plan03PageGroupView, 32> groups{};
    const std::size_t livePageGroupCount =
        engine.timelinePool.CaptureLivePlan03Groups(groups.data(),
                                                    groups.size());
    const std::uint64_t probe =
        engine.timelinePool.WindowEndFrame() > 0
            ? engine.timelinePool.WindowEndFrame() - 1u
            : 0;
    std::ostringstream out;
    out << " win=[" << engine.timelinePool.WindowStartFrame() << ","
        << engine.timelinePool.WindowEndFrame() << ") cutoff="
        << engine.timelinePool.PublishCutoffFrame() << " blocks="
        << engine.mixer.BlocksRendered() << " pageGroup=" << livePageGroupCount
        << " queueLive=" << engine.queueInstances.LiveCount()
        << " preflight="
        << static_cast<int>(engine.timelinePool.PreflightSingleEvent(
               probe, engine.timelinePool.PublishCutoffFrame()));
    for (const auto& row : engine.playableServices) {
        if (row.phase == harken::EnginePlayableStartPhase::Free) continue;
        const auto owner = engine.playableInstances.Classify(row.rootInstance);
        harken::TimelineArmObservation currentArm{};
        const bool currentObserved = engine.timelineArms.Observe(row.arm, &currentArm);
        out << " [service=" << row.identity.slot << ":" << row.identity.generation
            << " phase=" << static_cast<unsigned>(row.phase)
            << " root=" << row.rootInstance << " live=" << owner.live
            << " child=" << engine.playableInstances.FirstChild(row.rootInstance)
            << " partitionRetiring=" << row.partitionRetiring
            << " queueEnd=" << row.queueNaturalEnd
            << " finalTombstone=" << row.queueFinalSourceTombstoned
            << " arrival=" << row.queueArrivalDecision.Valid()
            << " retiredOccurrence=" << row.queueRetiringOccurrence.generation
            << " armObserved=" << currentObserved << " armState=" << static_cast<unsigned>(currentArm.state)
            << " logical=" << currentArm.logicalCompletionSequence
            << " tombstone=" << currentArm.tombstoneAudioSequence
            << " leaf=" << harken::ObjectIdString(row.leaf.stableId) << " render=" << row.renderHandle << "]";
        for (std::size_t index = 0; index < engine.playableStorage.memberStride; ++index) {
            const auto slot = engine.playableStorage.MemberBase(row.partition.slot) + index;
            const auto& member = engine.ReadPlayableMember(slot).completion;
            if (member.leafInstance == 0) continue;
            const auto leaf = engine.playableInstances.Classify(member.leafInstance);
            const auto* source = engine.sourceTerminals.Resolve(member.source);
            harken::TimelineArmObservation arm{};
            const bool observed = engine.timelineArms.Observe(engine.ReadPlayableMember(slot).arm, &arm);
            out << " [member=" << index << " leaf=" << member.leafInstance
                << " live=" << leaf.live << " lifecycle=" << static_cast<unsigned>(leaf.lifecycle)
                << " source=" << (source != nullptr) << " retired=" << member.resourcesRetired
                << " armObserved=" << observed << " armState=" << static_cast<unsigned>(arm.state);
            if (source != nullptr) out << " completed=" << source->completedSequence.load()
                << " released=" << engine.voices.ReleaseObserved(source->release)
                << " seen=" << source->releaseSeen << " seenAt=" << source->releaseSeenAt;
            out << "]";
        }
    }
    return out.str();
}

const harken::EnginePlayableServiceRow* FindPlayableRow(
    const harken::Engine& engine, harken::PlayableInstanceHandle instance) {
    for (const harken::EnginePlayableServiceRow& row : engine.playableServices) {
        if (row.rootInstance == instance &&
            row.phase != harken::EnginePlayableStartPhase::Free) {
            return &row;
        }
    }
    return nullptr;
}

std::string HeardSigns(const std::vector<int>& heard) {
    std::string signs;
    signs.reserve(heard.size());
    for (int sign : heard) {
        signs.push_back(sign > 0 ? '+' : '-');
    }
    return signs;
}

std::string HeardMarks(const std::vector<int>& heard) {
    std::ostringstream out;
    out << '[';
    for (std::size_t i = 0; i < heard.size(); ++i) {
        if (i != 0) {
            out << ' ';
        }
        out << heard[i];
    }
    out << ']';
    return out.str();
}

std::vector<float> MakeOnsetPcm(float amplitude) {
    std::vector<float> samples(512 + 256, 0.0f);
    std::fill(samples.begin(), samples.begin() + 512, amplitude);
    return samples;
}

int MarkForStableChildOrdinal(std::uint32_t ordinal) {
    if (ordinal == 7) {
        return 1;
    }
    if (ordinal == 8) {
        return -1;
    }
    if (ordinal == 9) {
        return 2;
    }
    return 0;
}

int LastBlockChildMark(const harken::Engine& engine) {
    const float* output = engine.nullBackend.LastBlock();
    int mark = 0;
    for (std::uint32_t frame = 0; frame < engine.config.blockFrames; ++frame) {
        const float value = output[2u * frame];
        if (value > 0.6f) {
            mark = 2;
        } else if (value > 0.1f) {
            mark = 1;
        } else if (value < -0.1f) {
            mark = -1;
        }
    }
    return mark;
}

void PushHeardOnset(std::vector<int>& heard, bool& previousAudible, int mark) {
    const bool audible = mark != 0;
    if (audible && !previousAudible) {
        heard.push_back(mark);
    }
    previousAudible = audible;
}

const char* InferredQueuePrepareStatus(
    const harken::EnginePlayableServiceRow& row) {
    if (row.controlLifecycle ==
            harken::PlayableControlLifecycle::FailingSourceActive ||
        row.controlLifecycle ==
            harken::PlayableControlLifecycle::FailingAudibleRetiring) {
        return "Failed";
    }
    if (row.queueSignalOnlyNoOverlap) {
        return "Deferred";
    }
    if (row.queueNaturalEnd) {
        return "NaturalEnd";
    }
    if (row.queueContinuationPrepared) {
        return "Prepared";
    }
    return "None";
}

std::string WrapProbeDump(
    harken::Engine& engine,
    harken::PlayableInstanceHandle instance,
    const harken::ContainerProgramViewV3& program,
    const std::vector<int>& heard) {
    std::ostringstream out;
    out << OccupancyDump(engine) << " heard=" << HeardSigns(heard);
    const harken::EnginePlayableServiceRow* row =
        FindPlayableRow(engine, instance);
    if (row == nullptr) {
        out << " row=null";
        return out.str();
    }
    out << " phase=" << static_cast<int>(row->phase)
        << " life=" << static_cast<int>(row->controlLifecycle)
        << " reason=" << static_cast<int>(row->controlReason)
        << " infer=" << InferredQueuePrepareStatus(*row)
        << " natural=" << row->queueNaturalEnd
        << " prepared=" << row->queueContinuationPrepared
        << " deferred=" << row->queueSignalOnlyNoOverlap
        << " sameKey=" << row->queueSameProgramKey
        << " complete=" << row->queueCompletionFrame
        << " winEnd=" << engine.timelinePool.WindowEndFrame()
        << " completePastWin="
        << (row->queueCompletionFrame >=
            engine.timelinePool.WindowEndFrame())
        << " seedPost=" << row->queueRandomSeed.acceptedPostOrdinal;
    const harken::Plan03GroupReserveStatus pageGroupStatus =
        engine.timelinePool.PreflightPlan03GroupSlices(
            row->queueCompletionFrame, 1);
    const harken::ReserveRefusal eventPreflight =
        engine.timelinePool.PreflightSingleEvent(
            row->queueCompletionFrame,
            engine.timelinePool.PublishCutoffFrame());
    out << " pageGroupPreflight=" << static_cast<int>(pageGroupStatus)
        << " eventPre=" << static_cast<int>(eventPreflight);
    harken::EffectiveQueueState current{};
    harken::EffectiveQueueState peekedNext{};
    bool resetNext = false;
    const bool resolved =
        engine.queueInstances.ResolveEffective(row->queueInstance, &current);
    const bool peeked = resolved &&
        engine.queueInstances.ResolveNextSelection(
            row->queueInstance, &current, &peekedNext, &resetNext);
    out << " resolved=" << resolved << " peeked=" << peeked
        << " resetNext=" << resetNext;
    if (resolved) {
        out << " cur{ver=" << current.version << " cur=" << current.cursor
            << " child=" << current.currentChildOrdinal
            << " cycle=" << current.cycleOrdinal
            << " sel=" << current.selectionOrdinal
            << " recent=" << current.randomInitialRecentCount << "}";
    }
    out << " rowNext{ver=" << row->queueNextState.version
        << " cur=" << row->queueNextState.cursor
        << " child=" << row->queueNextState.currentChildOrdinal
        << " cycle=" << row->queueNextState.cycleOrdinal << "}";
    if (!resolved || !row->queueRandomSeedValid ||
        engine.queueSelectionChildScratch.size() < program.childCount ||
        engine.queueRemainingScratch.size() < program.childCount ||
        engine.queuePermutationScratch.size() < program.childCount) {
        out << " step=skip";
        return out.str();
    }
    harken::EffectiveQueueState stepNext{};
    const harken::QueueSequenceStepStatus step =
        harken::ResolveRandomQueueStep(
            program, row->queueRandomSeed, current,
            engine.queueSelectionChildScratch.data(),
            engine.queueRemainingScratch.data(),
            engine.queuePermutationScratch.data(),
            static_cast<std::uint32_t>(engine.queuePermutationScratch.size()),
            &stepNext);
    out << " step=" << static_cast<int>(step)
        << " next{cur=" << stepNext.cursor
        << " child=" << stepNext.currentChildOrdinal
        << " cycle=" << stepNext.cycleOrdinal
        << " sel=" << stepNext.selectionOrdinal << "}"
        << " wrapSameChild="
        << (step == harken::QueueSequenceStepStatus::Successor &&
            current.cursor + 1u >= program.childCount &&
            current.currentChildOrdinal == stepNext.currentChildOrdinal);
    if (peeked && resetNext) {
        out << " peekChild=" << peekedNext.currentChildOrdinal;
    }
    harken::QueueInstanceSnapshot snapshot{};
    if (engine.queueInstances.Capture(row->queueInstance, &snapshot)) {
        out << " failPhase=" << static_cast<int>(snapshot.failurePhase)
            << " failReason=" << static_cast<int>(snapshot.failureReason);
    }
    return out.str();
}

int LastBlockSign(const harken::Engine& engine) {
    const int mark = LastBlockChildMark(engine);
    if (mark > 0) {
        return 1;
    }
    if (mark < 0) {
        return -1;
    }
    return 0;
}

bool BlockIsAudible(const harken::Engine& engine) {
    return LastBlockChildMark(engine) != 0;
}

void PushHeardSign(std::vector<int>& heard, int sign) {
    if (sign != 0 && (heard.empty() || heard.back() != sign)) {
        heard.push_back(sign);
    }
}

bool WaitUntilReclaimed(harken::Engine& engine,
                    harken::PlayableInstanceHandle instance) {
    harken::PlayableControlState state{};
    harken::PlayableControlStatus query =
        harken::QueryPlayable(engine, instance, &state);
    for (std::uint32_t block = 0; block < 64; ++block) {
        if ((query == harken::PlayableControlStatus::StaleHandle ||
             query == harken::PlayableControlStatus::InvalidHandle) &&
            FindPlayableRow(engine, instance) == nullptr) {
            return true;
        }
        if (Vn_Update() != VN_OK) {
            return false;
        }
        engine.nullBackend.Pump(1);
        query = harken::QueryPlayable(engine, instance, &state);
    }
    return (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) &&
           FindPlayableRow(engine, instance) == nullptr;
}

void DrainSilentBlocks(harken::Engine& engine, std::uint32_t maxBlocks) {
    for (std::uint32_t block = 0; block < maxBlocks; ++block) {
        if (Vn_Update() != VN_OK) {
            return;
        }
        engine.nullBackend.Pump(1);
        if (!BlockIsAudible(engine)) {
            return;
        }
    }
}

std::vector<int> RosterHeard(const std::vector<int>& heard, int residueSign) {
    if (residueSign != 0 && heard.size() > 4 && heard.front() == residueSign) {
        return std::vector<int>(heard.begin() + 1, heard.end());
    }
    return heard;
}

bool RandomQueueWrapsSameChild(
    harken::Engine& engine, harken::PlayableInstanceHandle instance,
    const harken::ContainerProgramViewV3& program) {
    const harken::EnginePlayableServiceRow* row =
        FindPlayableRow(engine, instance);
    if (row == nullptr || !row->queueRandomSeedValid ||
        engine.queueSelectionChildScratch.size() < program.childCount ||
        engine.queueRemainingScratch.size() < program.childCount ||
        engine.queuePermutationScratch.size() < program.childCount) {
        return false;
    }
    harken::EffectiveQueueState current{};
    if (!engine.queueInstances.ResolveEffective(row->queueInstance,
                                                &current)) {
        return false;
    }
    harken::EffectiveQueueState stepNext{};
    const harken::QueueSequenceStepStatus step =
        harken::ResolveRandomQueueStep(
            program, row->queueRandomSeed, current,
            engine.queueSelectionChildScratch.data(),
            engine.queueRemainingScratch.data(),
            engine.queuePermutationScratch.data(),
            static_cast<std::uint32_t>(engine.queuePermutationScratch.size()),
            &stepNext);
    return step == harken::QueueSequenceStepStatus::Successor &&
           current.cursor + 1u >= program.childCount &&
           current.currentChildOrdinal == stepNext.currentChildOrdinal;
}

struct QueueOnsetPlayback {
    std::vector<int> heard;
    std::vector<int> expected;
    bool wrapSameChild = false;
    bool inCycleSameKey = false;
    std::string atStart;
    std::string atWrap;
    std::string atEnd;
};

bool FillRandomQueueExpectedRoster(
    harken::Engine& engine, harken::PlayableInstanceHandle instance,
    const harken::ContainerProgramViewV3& program, std::uint32_t cycleCount,
    std::vector<int>* outExpected, bool* outWrapSameChild) {
    if (outExpected == nullptr || outWrapSameChild == nullptr ||
        program.childCount == 0 || cycleCount == 0) {
        return false;
    }
    outExpected->clear();
    *outWrapSameChild = false;
    const harken::EnginePlayableServiceRow* row = FindPlayableRow(engine, instance);
    if (row == nullptr || !row->queueRandomSeedValid) {
        return false;
    }
    std::vector<harken::SelectionChildV1> childScratch(program.childCount);
    std::vector<std::uint32_t> remainingScratch(program.childCount);
    std::vector<std::uint32_t> permutation(program.childCount);
    harken::EffectiveQueueState current{};
    if (!engine.queueInstances.ResolveEffective(row->queueInstance, &current)) {
        return false;
    }
    std::uint32_t previousCycleLastChild = UINT32_MAX;
    for (std::uint32_t cycle = 0; cycle < cycleCount; ++cycle) {
        if (harken::BuildRandomQueuePermutationV1(
                program, row->queueRandomSeed, current, childScratch.data(),
                remainingScratch.data(), permutation.data(),
                program.childCount) != harken::SelectionStatusV1::Ok) {
            return false;
        }
        if (cycle > 0 && permutation[0] == previousCycleLastChild) {
            *outWrapSameChild = true;
        }
        for (std::uint32_t cursor = 0; cursor < program.childCount; ++cursor) {
            const int mark = MarkForStableChildOrdinal(permutation[cursor]);
            if (mark == 0) {
                return false;
            }
            outExpected->push_back(mark);
            previousCycleLastChild = permutation[cursor];
        }
        if (cycle + 1u == cycleCount) {
            break;
        }
        for (std::uint32_t cursor = 0; cursor < program.childCount; ++cursor) {
            harken::EffectiveQueueState next{};
            if (harken::ResolveRandomQueueStep(
                    program, row->queueRandomSeed, current, childScratch.data(),
                    remainingScratch.data(), permutation.data(),
                    program.childCount, &next) !=
                harken::QueueSequenceStepStatus::Successor) {
                return false;
            }
            current = next;
        }
        if (current.cursor != 0) {
            return false;
        }
    }
    return true;
}

bool FillSequenceQueueExpectedRoster(
    const harken::ContainerProgramViewV3& program, std::uint32_t cycleCount,
    std::vector<int>* outExpected) {
    if (outExpected == nullptr || program.childCount == 0 ||
        program.children == nullptr) {
        return false;
    }
    outExpected->clear();
    for (std::uint32_t cycle = 0; cycle < cycleCount; ++cycle) {
        for (std::uint32_t cursor = 0; cursor < program.childCount; ++cursor) {
            const int mark = MarkForStableChildOrdinal(
                program.children[cursor].stableChildOrdinal);
            if (mark == 0) {
                return false;
            }
            outExpected->push_back(mark);
        }
    }
    return true;
}

QueueOnsetPlayback PlayQueueUntilStale(
    harken::Engine& engine, harken::PlayableInstanceHandle instance,
    const harken::ContainerProgramViewV3* program, std::uint32_t minHeard,
    bool captureInCycleSameKey) {
    QueueOnsetPlayback result;
    bool previousAudible = false;
    if (program != nullptr) {
        bool expectedReady = false;
        if (program->mode == harken::ContainerModeV1::RandomQueue) {
            const std::uint32_t cycleCount =
                program->childCount == 0
                    ? 0u
                    : minHeard / program->childCount;
            expectedReady = FillRandomQueueExpectedRoster(
                engine, instance, *program, cycleCount, &result.expected,
                &result.wrapSameChild);
        } else if (program->mode == harken::ContainerModeV1::SequenceQueue) {
            const std::uint32_t cycleCount =
                program->childCount == 0
                    ? 0u
                    : minHeard / program->childCount;
            expectedReady = FillSequenceQueueExpectedRoster(
                *program, cycleCount, &result.expected);
        }
        EXPECT_TRUE(expectedReady);
        result.atStart = WrapProbeDump(engine, instance, *program, result.heard);
    }
    for (std::uint32_t block = 0; block < 512; ++block) {
        EXPECT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        PushHeardOnset(
            result.heard, previousAudible, LastBlockChildMark(engine));
        if (captureInCycleSameKey && result.heard.size() == 1 &&
            !result.inCycleSameKey) {
            const harken::EnginePlayableServiceRow* row =
                FindPlayableRow(engine, instance);
            result.inCycleSameKey =
                row != nullptr && row->queueSameProgramKey;
        }
        if (program != nullptr && !result.wrapSameChild &&
            result.heard.size() + 1u == program->childCount) {
            result.wrapSameChild = RandomQueueWrapsSameChild(
                engine, instance, *program);
            if (result.wrapSameChild && result.atWrap.empty()) {
                result.atWrap = WrapProbeDump(
                    engine, instance, *program, result.heard);
            }
        }
        harken::PlayableControlState state{};
        const harken::PlayableControlStatus query =
            harken::QueryPlayable(engine, instance, &state);
        if ((query == harken::PlayableControlStatus::StaleHandle ||
             query == harken::PlayableControlStatus::InvalidHandle) &&
            result.heard.size() >= minHeard) {
            break;
        }
    }
    result.atEnd =
        program == nullptr
            ? OccupancyDump(engine)
            : WrapProbeDump(engine, instance, *program, result.heard);
    return result;
}

bool PumpBlocks(harken::Engine& engine, std::uint32_t n) {
    for (std::uint32_t i = 0; i < n; ++i) {
        if (Vn_Update() != VN_OK) {
            return false;
        }
        engine.nullBackend.Pump(1);
    }
    return true;
}

constexpr std::uint32_t kWorldReplacementRetryLimit = 256;

bool InstallCurrentWorldUntilOk(
    harken::Engine& engine, const harken::ContainerWorldInstallViewV1& install) {
    std::uint32_t pumped = 0;
    harken::WorldInstallResult result =
        harken::InstallContainerWorldV1(engine, install);
    while (result.status == harken::WorldInstallStatus::Backpressure &&
           pumped < kWorldReplacementRetryLimit) {
        if (Vn_Update() != VN_OK) {
            break;
        }
        engine.nullBackend.Pump(1);
        ++pumped;
        result = harken::InstallContainerWorldV1(engine, install);
    }
    if (result.status != harken::WorldInstallStatus::Ok) {
        ADD_FAILURE() << "world install retry_blocks=" << pumped
                      << " limit=" << kWorldReplacementRetryLimit
                      << " status=" << static_cast<int>(result.status);
        return false;
    }
    return true;
}

bool StopUntilStale(harken::Engine& engine,
                    harken::PlayableInstanceHandle instance,
                    bool waitForPartitions = false) {
    harken::PlayableControlState state{};
    harken::PlayableControlStatus query =
        harken::QueryPlayable(engine, instance, &state);
    harken::PlayableControlStatus stop = harken::PlayableControlStatus::Ok;
    if (query == harken::PlayableControlStatus::Ok) {
        stop = harken::StopPlayable(engine, instance, 0);
    }
    for (std::uint32_t block = 0; block < 256; ++block) {
        if (stop == harken::PlayableControlStatus::Backpressure) {
            stop = harken::StopPlayable(engine, instance, 0);
        }
        query = harken::QueryPlayable(engine, instance, &state);
        if (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) {
            if (!waitForPartitions || engine.playablePartitions.OccupiedCount() == 0)
                return true;
        }
        if (Vn_Update() != VN_OK) {
            return false;
        }
        engine.nullBackend.Pump(1);
    }
    return (query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle) &&
        (!waitForPartitions || engine.playablePartitions.OccupiedCount() == 0);
}

bool InstallHandoffWorld(harken::Engine& engine,
                         const std::array<std::uint64_t, 3>& revisions,
                         HandoffKind kind,
                         std::uint32_t loopCount,
                         harken::PlayableRefV1* root) {
    switch (kind) {
        case HandoffKind::RandomQueue: {
            RandomQueueWorldImage image(revisions);
            ApplyQueueLoop(image.container, loopCount);
            const auto install = PlayableWorldInstall(image.world);
            *root = image.Root();
            return InstallCurrentWorldUntilOk(engine, install);
        }
        case HandoffKind::SequenceQueue: {
            SequenceQueueWorldImage image(revisions[0], revisions[1]);
            ApplyQueueLoop(image.container, loopCount);
            const auto install = PlayableWorldInstall(image.world);
            *root = image.Root();
            return InstallCurrentWorldUntilOk(engine, install);
        }
        case HandoffKind::Sequence:
        case HandoffKind::Random:
        case HandoffKind::RandomRotation: {
            TwoChildPlayableWorldImage image(
                revisions[0], revisions[1],
                kind == HandoffKind::Sequence
                    ? harken::ContainerModeV1::Sequence
                    : harken::ContainerModeV1::Random,
                kind == HandoffKind::RandomRotation
                    ? harken::RandomDisciplineV1::Rotation
                    : harken::RandomDisciplineV1::Draw);
            image.container.memoryScope = harken::MemoryScopeV1::Emitter;
            image.SetContainerLoopCount(loopCount);
            *root = image.Root();
            return InstallCurrentWorldUntilOk(engine, image.world);
        }
        case HandoffKind::VariableControl: {
            const harken::VariableDefinitionV1 variable = {
                harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
            VariableControlWorldImage image(
                revisions[0], engine.variables.CurrentWorldGeneration());
            auto install = PlayableWorldInstall(image.world);
            install.variables = &variable;
            install.variableCount = 1;
            install.identity.capabilityMask |=
                harken::kWorldCapabilityVariableDefinitions;
            install.identity.runtimeSemanticFingerprint =
                harken::ComputeCurrentWorldFingerprintV4(install);
            *root = image.Root();
            return InstallCurrentWorldUntilOk(engine, install);
        }
    }
    return false;
}

bool StartHandoffAccepted(harken::Engine& engine,
                          const harken::PlayableRefV1& root,
                          VnEmitterHandle emitter) {
    harken::PlayableStartRequest request{};
    request.root = root;
    request.emitter = emitter;
    request.callerSeed = 77;
    const harken::PlayableStartResult started =
        harken::StartPlayable(engine, request);
    return started.status == harken::PlayableStartStatus::Accepted &&
           started.instance != 0 && !engine.runtimeRecreateRequired;
}

void ExpectContainerStartsThroughM2(
    harken::ContainerModeV1 mode,
    harken::RandomDisciplineV1 discipline =
        harken::RandomDisciplineV1::Draw) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());

    PlayableWorldImage image(media.contentRevision, mode, discipline);
    image.properties[0].payload.values[9].bits =
        std::bit_cast<std::uint32_t>(50.0f);
    image.properties[0].programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(image.properties[0]);
    image.child.playable = image.SoundRoot();
    image.occurrence.childPlayable = image.child.playable;
    image.occurrence.occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);
    const std::uint32_t freeDeltas =
        engine->selectionMemory.FreeDeltaCount();
    const std::uint32_t freeInstances = engine->playableInstances.FreeCount();
    const std::uint64_t issued = engine->logicCommits.Current();
    const std::uint64_t commandHead = engine->commands.PublishedHead();
    const std::uint64_t initialSourceHead = engine->commands.InitialSourcePublishedHead();
    const std::uint32_t activeVoices = engine->voices.ActiveCount();
    const std::uint32_t liveArms = engine->timelineArms.LiveCount();
    const std::uint32_t liveTransactions =
        engine->timelinePool.LiveTransactionCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.callerSeed = 77;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(started.status, harken::PlayableStartStatus::Accepted);
    ASSERT_NE(started.instance, 0u);
    EXPECT_EQ(started.ticket, issued + 1u);
    EXPECT_EQ(engine->selectionMemory.FreeDeltaCount(), freeDeltas - 1u);
    EXPECT_EQ(engine->playableInstances.FreeCount(), freeInstances - 2u);
    EXPECT_EQ(engine->commands.PublishedHead(), commandHead);
    EXPECT_EQ(engine->commands.InitialSourcePublishedHead(), initialSourceHead + 1u);
    EXPECT_EQ(engine->voices.ActiveCount(), activeVoices + 1u);
    EXPECT_EQ(engine->timelineArms.LiveCount(), liveArms + 1u);
    EXPECT_EQ(engine->timelinePool.LiveTransactionCount(),
              liveTransactions + 1u);
    const auto admittedRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(admittedRow, engine->playableServices.end());
    EXPECT_EQ(admittedRow->phase,
              harken::EnginePlayableStartPhase::AwaitingArmAck);
    EXPECT_NE(admittedRow->renderHandle, 0u);

    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_EQ(Vn_Update(), VN_OK);
    EXPECT_EQ(engine->selectionMemory.FreeDeltaCount(), freeDeltas);
    const harken::PlayableInstanceView root =
        engine->playableInstances.Classify(started.instance);
    EXPECT_TRUE(root.live);
    EXPECT_TRUE(root.lifecycle == harken::PlayableLifecycle::Active ||
                root.lifecycle == harken::PlayableLifecycle::LogicalComplete ||
                root.lifecycle == harken::PlayableLifecycle::AudibleRetiring);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(row, engine->playableServices.end());
    const harken::VoiceLedger::RenderOwner child =
        engine->ledger.OwnerForRender(row->renderHandle);
    ASSERT_TRUE(child.live);
    EXPECT_EQ(child.visibility,
              harken::VoiceLedger::PublicVisibility::PlayableOwnedInternal);
    EXPECT_EQ(child.parent.internalToken, started.instance);
    const harken::VoiceRenderContext* rendered =
        engine->voices.Resolve(row->renderHandle);
    ASSERT_NE(nullptr, rendered);
    EXPECT_FLOAT_EQ(0.5f, rendered->width);
    VnSnapshot snapshot{};
    snapshot.structSize = sizeof(snapshot);
    ASSERT_EQ(Vn_CaptureSnapshot(&snapshot), VN_OK);
    EXPECT_TRUE(std::all_of(
        std::begin(snapshot.voicePublicHandles),
        std::end(snapshot.voicePublicHandles),
        [](std::uint64_t handle) { return handle == 0; }));
    const std::uint32_t childSlot =
        static_cast<std::uint32_t>(row->renderHandle);
    ASSERT_LT(childSlot, VN_SNAPSHOT_MAX_VOICES);
    EXPECT_EQ(snapshot.voices[childSlot].state, VN_VOICE_STATE_INACTIVE);
    EXPECT_GT(engine->timelinePool.ConsumerFrontier().load(), 0u);
}

TEST(PlayableStartContract, RandomContainerSelectsAndStartsSoundThroughM2) {
    ExpectContainerStartsThroughM2(harken::ContainerModeV1::Random);
}

TEST(PlayableStart, TimelineVoiceFollowsEmitterForSpatialAttenuation) {
    for (bool spatialized : {true, false}) {
        for (bool attachEmitter : {true, false}) {
            SCOPED_TRACE(testing::Message() << "spatialized=" << spatialized
                                           << " emitter=" << attachEmitter);
            harkentest::EngineSession session(harkentest::MakeNullConfig(2, 256, 48000));
            ASSERT_EQ(VN_OK, session.InitResult());
            auto& engine = *session.Engine();
            const auto samples = harkentest::MakeDC(48000, 0.25f);
            const auto pcm = harkentest::MonoDesc(samples, 48000);
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
            const auto attenuation = harkentest::MakeAttenuationDesc(1.0f, 10.0f, VN_ROLLOFF_LINEAR);
            ASSERT_EQ(VN_OK, Vn_RegisterAttenuation(harkentest::ObjectId(77), &attenuation));
            PlayableWorldImage image(engine.registry.Lookup(kSound).contentRevision,
                                     harken::ContainerModeV1::Random);
            auto& payload = image.properties[0].payload;
            const auto set = [&](harken::playableproperties::PlayablePropertyIdV1 id, std::uint64_t bits) {
                const auto slot = static_cast<std::size_t>(id) - 1;
                payload.presentMask |= UINT64_C(1) << slot;
                payload.values[slot].bits = bits;
            };
            set(harken::playableproperties::PlayablePropertyIdV1::SpatialIs3DEnabled, spatialized ? 1 : 0);
            set(harken::playableproperties::PlayablePropertyIdV1::SpatialAttenuationDistanceScaling,
                std::bit_cast<std::uint32_t>(1.0f));
            payload.values[13].objectId = harkentest::ObjectId(77);
            for (auto& property : image.properties)
                property.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(property);
            image.child.playable = image.SoundRoot();
            image.occurrence.childPlayable = image.child.playable;
            image.occurrence.parentProgramSemanticFingerprint = image.properties[1].programSemanticFingerprint;
            image.occurrence.occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
            image.container.programSemanticFingerprint = image.properties[1].programSemanticFingerprint;
            image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
            ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
            VnEmitterHandle emitter = 0;
            ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
            harken::PlayableStartRequest request{};
            request.root = image.SoundRoot();
            request.emitter = attachEmitter ? emitter : 0;
            const auto started = harken::StartPlayable(engine, request);
            ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
            const auto pump = [&] {
                EXPECT_EQ(VN_OK, Vn_Update());
                engine.nullBackend.Pump(1);
                EXPECT_EQ(VN_OK, Vn_Update());
            };
            for (int i = 0; i < 16; ++i) { pump(); }
            const auto service = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
                [&](const auto& row) { return row.rootInstance == started.instance && row.InvocationValid(); });
            ASSERT_NE(engine.playableServices.end(), service);
            const auto render = service->renderHandle;
            ASSERT_NE(nullptr, engine.voices.Resolve(render));
            harken::EngineTimelineVoiceInstallIdentity identity{};
            ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(render, &identity));
            ASSERT_EQ(started.instance, identity.rootInstance);
            ASSERT_EQ(2u, engine.nullBackend.Channels());
            const auto offset = engine.nullBackend.BlockFrames() / 2 * engine.nullBackend.Channels();
            const float originLeft = engine.nullBackend.LastBlock()[offset];
            const float originRight = engine.nullBackend.LastBlock()[offset + 1];
            ASSERT_GT(std::abs(originLeft), harkentest::kSilenceFloor);
            ASSERT_GT(std::abs(originRight), harkentest::kSilenceFloor);
            for (float z : {0.0f, -5.0f, -7.0f}) {
                ASSERT_EQ(VN_OK, Vn_SetEmitterPosition(emitter, {0.0f, 0.0f, z}));
                for (int i = 0; i < 8; ++i) { pump(); }
                ASSERT_TRUE(engine.playableInstances.Classify(started.instance).live);
                ASSERT_NE(nullptr, engine.voices.Resolve(render));
                harken::Spatializer::SpatialVoiceState voice{};
                ASSERT_TRUE(engine.spatial.CaptureVoice(render, &voice));
                EXPECT_EQ(spatialized, voice.spatialized);
                EXPECT_EQ(harkentest::ObjectId(77u), voice.attenuationId);
                EXPECT_EQ(request.emitter, voice.emitterHandle);
                EXPECT_FLOAT_EQ(0.0f, voice.posX);
                EXPECT_FLOAT_EQ(0.0f, voice.posY);
                EXPECT_FLOAT_EQ(attachEmitter ? z : 0.0f, voice.posZ);
                EXPECT_FLOAT_EQ(1.0f, voice.distanceScale);
                const float gain = spatialized && attachEmitter
                    ? std::min(1.0f, (10.0f - std::abs(z)) / 9.0f) : 1.0f;
                EXPECT_NEAR(originLeft * gain, engine.nullBackend.LastBlock()[offset], 1e-4f);
                EXPECT_NEAR(originRight * gain, engine.nullBackend.LastBlock()[offset + 1], 1e-4f);
            }
            ASSERT_TRUE(StopUntilStale(engine, started.instance, true));
            EXPECT_EQ(nullptr, engine.voices.Resolve(render));
        }
    }
}

TEST(PlayableStart, AuthoredSpatializationMixStartsUpdatesAndReplays) {
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto samples = harkentest::MakeDC(48000, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));

    PlayableWorldImage image(
        engine.registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    auto& sound = image.properties[0];
    sound.payload.values[10].bits = 1;
    sound.payload.presentMask |= UINT64_C(1) << 16;
    sound.payload.values[16].bits = std::bit_cast<std::uint32_t>(0.25f);
    sound.programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(sound);
    image.child.playable = image.SoundRoot();
    image.occurrence.childPlayable = image.child.playable;
    image.occurrence.occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    ASSERT_EQ(VN_OK,
              Vn_SetEmitterPosition(emitter, {10.0f, 0.0f, 0.0f}));

    const auto start = [&] {
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        request.emitter = emitter;
        const auto started = harken::StartPlayable(engine, request);
        EXPECT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        EXPECT_TRUE(PumpUntilAudible(engine));
        const auto service = std::find_if(
            engine.playableServices.begin(), engine.playableServices.end(),
            [&](const auto& row) {
                return row.rootInstance == started.instance;
            });
        EXPECT_NE(engine.playableServices.end(), service);
        return std::pair{started,
                         service == engine.playableServices.end()
                             ? VnVoiceHandle{0}
                             : service->renderHandle};
    };
    const auto captureMix = [&](VnVoiceHandle render) {
        harken::Spatializer::SpatialVoiceState spatial{};
        EXPECT_TRUE(engine.spatial.CaptureVoice(render, &spatial));
        return spatial.spatializationMix;
    };
    const auto expectRenderedMix = [&](float mix, bool spatialized) {
        ASSERT_EQ(2u, engine.nullBackend.Channels());
        const std::uint32_t frame = engine.nullBackend.BlockFrames() - 1u;
        const std::uint32_t offset = frame * engine.nullBackend.Channels();
        const float center = 0.25f;
        const float expectedLeft = spatialized ? center * (1.0f - mix) : center;
        const float expectedRight = spatialized ? center * (1.0f - mix) + 0.25f * std::sqrt(2.0f) * mix : center;
        EXPECT_NEAR(expectedLeft, engine.nullBackend.LastBlock()[offset],
                    1e-4f);
        EXPECT_NEAR(expectedRight, engine.nullBackend.LastBlock()[offset + 1u],
                    1e-4f);
    };
    const auto settle = [&] {
        ASSERT_EQ(VN_OK, Vn_Update());
        for (std::uint32_t block = 0; block < 16; ++block) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
    };

    const auto [first, firstRender] = start();
    ASSERT_NE(0u, firstRender);
    EXPECT_FLOAT_EQ(0.25f, captureMix(firstRender));
    expectRenderedMix(0.25f, true);
    EXPECT_EQ(VN_OK,
              harken::SetPreviewVoiceProperty(
                  firstRender,
                  harken::playableproperties::PlayablePropertyIdV1::SpatializationMix,
                  0.5f));
    settle();
    EXPECT_FLOAT_EQ(0.5f, captureMix(firstRender));
    expectRenderedMix(0.5f, true);
    EXPECT_EQ(VN_INVALID_ARG,
              harken::SetPreviewVoiceProperty(
                  firstRender,
                  harken::playableproperties::PlayablePropertyIdV1::SpatializationMix,
                  1.01f));
    EXPECT_FLOAT_EQ(0.5f, captureMix(firstRender));

    ASSERT_TRUE(StopUntilStale(engine, first.instance, true));
    EXPECT_EQ(VN_STALE_HANDLE,
              harken::SetPreviewVoiceProperty(
                  firstRender,
                  harken::playableproperties::PlayablePropertyIdV1::SpatializationMix,
                  0.0f));
    const auto [replayed, replayRender] = start();
    ASSERT_NE(0u, replayRender);
    EXPECT_NE(firstRender, replayRender);
    EXPECT_FLOAT_EQ(0.25f, captureMix(replayRender));
    expectRenderedMix(0.25f, true);
    EXPECT_TRUE(StopUntilStale(engine, replayed.instance, true));

    sound.payload.values[10].bits = 0;
    sound.programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(sound);
    image.child.playable = image.SoundRoot();
    image.occurrence.childPlayable = image.child.playable;
    image.occurrence.occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(engine, image.world).status);
    const auto [twoDimensional, twoDimensionalRender] = start();
    ASSERT_NE(0u, twoDimensionalRender);
    EXPECT_FLOAT_EQ(0.25f, captureMix(twoDimensionalRender));
    expectRenderedMix(0.25f, false);
    EXPECT_EQ(VN_OK,
              harken::SetPreviewVoiceProperty(
                  twoDimensionalRender,
                  harken::playableproperties::PlayablePropertyIdV1::SpatializationMix,
                  1.0f));
    settle();
    EXPECT_FLOAT_EQ(1.0f, captureMix(twoDimensionalRender));
    expectRenderedMix(1.0f, false);
    EXPECT_TRUE(StopUntilStale(engine, twoDimensional.instance, true));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PlayableStartContract, OutputVolumeReachesOnlyTheMainRouteFromResolvedCuts) {
    for (bool direct : {false, true}) {
        SCOPED_TRACE(direct);
        auto config = harkentest::MakeNullConfig(4, 64, 48000);
        harkentest::EngineSession session(config);
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        ASSERT_EQ(VN_OK, Vn_CreateBus(harkentest::ObjectId(2), VN_BUS_MASTER));
        ASSERT_EQ(VN_OK, Vn_CreateBus(harkentest::ObjectId(3), VN_BUS_MASTER));
        std::vector<float> samples(4096, 0.25f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
        const auto media = engine->registry.Lookup(kSound);
        PlayableWorldImage image(media.contentRevision, harken::ContainerModeV1::Random);
        auto& output = image.properties[0].payload;
        output.presentMask |= UINT64_C(1) << 5;
        output.values[5].bits = std::bit_cast<std::uint32_t>(-6.0206f);
        const harken::SendV1 send{0, 0, harkentest::ObjectId(3), 0.0f, 0};
        auto& sound = image.properties[0].payload;
        sound.presentMask |= (UINT64_C(1) << 6) | (UINT64_C(1) << 7);
        sound.values[6].objectId = harkentest::ObjectId(2);
        sound.sendCount = 1;
        sound.sends = &send;
        for (auto& property : image.properties)
            property.programSemanticFingerprint =
                harken::ComputePlayablePropertyFingerprintV1(property);
        image.child.playable = image.SoundRoot();
        image.occurrence.childPlayable = image.child.playable;
        image.occurrence.parentProgramSemanticFingerprint =
            image.properties[1].programSemanticFingerprint;
        image.occurrence.occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
        image.container.programSemanticFingerprint =
            image.properties[1].programSemanticFingerprint;
        image.world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(image.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);
        harken::PlayableStartRequest request{};
        request.root = direct ? image.SoundRoot() : image.Root();
        ASSERT_EQ(harken::PlayableStartStatus::Accepted,
                  harken::StartPlayable(*engine, request).status);
        ASSERT_TRUE(PumpUntilAudible(*engine));
        harkentest::Capture out;
        harkentest::PumpAndCapture(engine, 1, out);
        for (float sample : out.left) EXPECT_NEAR(0.375f, sample, 1e-5f);
        for (float sample : out.right) EXPECT_NEAR(0.375f, sample, 1e-5f);
    }
}

