TEST(PlayableStart,
     VariableControlNaturalEndTransitionUsesKnownCompletionBoundary) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(2048, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434E4154454E44)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.container.maxActiveRows = 0;
    image.container.maxLiveRows = 0;
    image.SetNaturalEndFades(256, 192);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    const std::uint64_t naturalEndFrame =
        engine->ReadPlayableMember(base).startFrame + samples.size();
    const VnVoiceHandle sourceVoice =
        engine->ReadPlayableMember(base).render;

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0;
         block < 32 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(naturalEndFrame - 256u,
              row->variableControlDiscreteRetargetFrame);
    EXPECT_EQ(naturalEndFrame + 192u,
              row->variableControlDiscreteRetargetEndFrame);

    const auto* exiting =
        row->variableControlDiscreteRetargetRuntimeProgram.payloads;
    ASSERT_EQ(1u,
              row->variableControlDiscreteRetargetRuntimeProgram.payloadCount);
    EXPECT_EQ(harken::TimelineEventKind::Envelope, exiting[0].kind);
    EXPECT_EQ(naturalEndFrame - 256u, exiting[0].envelopeStartFrame);
    EXPECT_EQ(naturalEndFrame, exiting[0].envelopeEndFrame);

    const auto* entering =
        row->variableControlDiscreteRetargetEnteringRuntimeProgram.payloads;
    ASSERT_EQ(2u,
              row->variableControlDiscreteRetargetEnteringRuntimeProgram.
                  payloadCount);
    EXPECT_EQ(harken::TimelineEventKind::Start, entering[0].kind);
    EXPECT_EQ(naturalEndFrame, entering[1].envelopeStartFrame);
    EXPECT_EQ(naturalEndFrame + 192u, entering[1].envelopeEndFrame);
    EXPECT_EQ(naturalEndFrame,
              row->variableControlDiscreteRetargetEnteringSchedule.
                  entryAnchorFrame);

    const VnVoiceHandle targetVoice =
        engine->ReadPlayableMember(
            base + row->variableControlDiscreteTransitionOffset).render;
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           naturalEndFrame - 256u) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const auto* sourceAtFade = engine->voices.Resolve(sourceVoice);
    const auto* targetBeforeEnd = engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, sourceAtFade);
    ASSERT_NE(nullptr, targetBeforeEnd);
    EXPECT_TRUE(sourceAtFade->timelineEnvelopes[1].active);
    EXPECT_TRUE(targetBeforeEnd->timelineGated);

    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           naturalEndFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoice));
    const auto* targetAfterEnd = engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, targetAfterEnd);
    EXPECT_FALSE(targetAfterEnd->timelineGated);
    EXPECT_TRUE(targetAfterEnd->timelineEnvelopes[0].active);
}

TEST(PlayableStart,
     VariableControlTimelyNaturalEndRetargetStaysActiveUntilStop) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(2048, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643474154454544)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.container.maxActiveRows = 0;
    image.container.maxLiveRows = 0;
    image.SetNaturalEndFades(256, 192);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    const std::uint64_t naturalEndFrame =
        engine->ReadPlayableMember(base).startFrame + samples.size();
    const VnVoiceHandle sourceVoice =
        engine->ReadPlayableMember(base).render;

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0;
         block < 32 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    ASSERT_TRUE(row->variableControlDiscreteRetargetEntering);
    ASSERT_FALSE(row->variableControlDiscreteRetargetSourceExited);
    EXPECT_EQ(naturalEndFrame + 192u,
              row->variableControlDiscreteRetargetEndFrame);

    const VnVoiceHandle targetVoice =
        engine->ReadPlayableMember(
            base + row->variableControlDiscreteTransitionOffset).render;
    ASSERT_NE(0u, targetVoice);
    const auto targetArm = engine->ReadPlayableMember(
        base + row->variableControlDiscreteTransitionOffset).arm;
    harken::TimelineArmObservation beforeOnset{};
    ASSERT_TRUE(engine->timelineArms.Observe(targetArm, &beforeOnset));
    ASSERT_EQ(0u, beforeOnset.startedBlockSequence);
    const auto onsetBaseline = engine->mixer.BlocksRendered();

    bool targetStarted = false;
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           row->variableControlDiscreteRetargetEndFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* target = engine->voices.Resolve(targetVoice);
        harken::TimelineArmObservation onset{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(targetArm, &onset) &&
             onset.startedBlockSequence > onsetBaseline && target != nullptr &&
             !target->timelineGated && target->cascade.runnable);
    }
    EXPECT_TRUE(targetStarted);
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->voices.ActiveCount() == 0) {
            break;
        }
    }
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoice));
    EXPECT_EQ(nullptr, engine->voices.Resolve(targetVoice));
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    EXPECT_FALSE(harken::HasCurrentWorldPublicationConsumers(*engine));

    const harken::PlayableStartResult next =
        harken::StartPlayable(*engine, image.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::Accepted, next.status);
    EXPECT_NE(started.instance, next.instance);
}

TEST(PlayableStart,
     VariableControlNaturalEndUnknownCompletionKeepsIncumbentWhole) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(2048, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434E554E4B4E57)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetNaturalEndFades(256, 192);
    image.SetSoundLoop(true);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto coordinator = row->frontierEntry.coordinator;
    ASSERT_TRUE(coordinator.Valid());
    const std::size_t base = row->scheduleStorageBase;
    const VnVoiceHandle incumbent =
        engine->ReadPlayableMember(base).render;

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
    }
    EXPECT_NE(nullptr, engine->voices.Resolve(incumbent));
    EXPECT_EQ(7u,
              engine->ReadPlayableMember(base).voice.Facts().target.occurrenceOrdinal);
    EXPECT_EQ(decisionBaseline + 1u, engine->decisions.LiveCount());
    EXPECT_TRUE(engine->decisions.Contains(coordinator));
    EXPECT_EQ(coordinator.slot, engine->decisionRetirements[coordinator.slot].decision.slot);
    EXPECT_EQ(coordinator.generation, engine->decisionRetirements[coordinator.slot].decision.generation);
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    bool restored = false;
    for (std::uint32_t block = 0; block < 128 && !restored; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        restored = engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline;
    }
    EXPECT_TRUE(restored);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlNaturalEndLatePreparationDoesNotStartTarget) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(512, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434E4C41544550)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetNaturalEndFades(256, 192);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto base = row->scheduleStorageBase;
    const auto incumbent = engine->ReadPlayableMember(base).render;

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool targetPrepared = false;
    bool targetStarted = false;
    const auto observeTargets = [&]() {
        for (std::uint32_t index = 0; index < engine->sourceTerminals.Capacity(); ++index) {
            const auto* source = engine->sourceTerminals.At(index);
            if (!source->occupied || source->controller != started.instance ||
                source->render == incumbent) continue;
            const auto* voice = engine->voices.Resolve(source->render);
            targetStarted = targetStarted || (voice != nullptr &&
                !voice->timelineGated && voice->cascade.runnable);
        }
    };
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        targetPrepared = targetPrepared ||
            row->variableControlDiscreteRetargetPrepared;
        observeTargets();
        const auto sequence = engine->mixer.BlocksRendered();
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(sequence, engine->mixer.BlocksRendered());
        engine->nullBackend.Pump(1);
        observeTargets();
    }
    EXPECT_FALSE(targetPrepared);
    EXPECT_FALSE(targetStarted);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    for (std::uint32_t block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    std::vector<VnVoiceHandle> targetOnsets;
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        for (std::uint32_t index = 0; index < engine->playableStorage.memberStride; ++index) {
            const auto slot = base + index;
            const auto render = engine->ReadPlayableMember(slot).render;
            const auto* voice = engine->voices.Resolve(render);
            if (engine->ReadPlayableMember(slot).voice.Facts().target.occurrenceOrdinal == 9 &&
                voice != nullptr && !voice->timelineGated && voice->cascade.runnable &&
                std::find(targetOnsets.begin(), targetOnsets.end(), render) == targetOnsets.end())
                targetOnsets.push_back(render);
        }
    }
    EXPECT_TRUE(targetOnsets.empty());
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST_P(NaturalEndVariableControlCancellationTest,
       PreparedHandoffCancelsWithoutStartingTargetOrLeaking) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const harken::WorldGeneration worldBefore =
        engine->variables.CurrentWorldGeneration();
    const harken::TransportEpoch transportBefore =
        engine->transportEpochOwner.Current();

    std::vector<float> samples(2048, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434E43414E434C)).status);
    const harken::WorldGeneration installedWorld =
        engine->variables.CurrentWorldGeneration();
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision, installedWorld);
    image.SetNaturalEndFades(256, 192);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 32 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot decision{};
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->variableControlDiscreteRetargetDecision, &decision) &&
            decision.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    const harken::TimelineArmToken entering =
        row->variableControlDiscreteRetargetEnteringArm;
    ASSERT_TRUE(entering.Valid());

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    switch (GetParam()) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, started.instance, 0));
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        row->variableControlWorldUsesCurrentAuthority = true;
        ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
                  harken::InstallContainerWorldV1(
                      *engine, replacement.world).status);
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
                  harken::BeginRuntimeTransportReset(*engine, 0));
        break;
    }

    bool targetStarted = false;
    bool stale = false;
    bool restored = false;
    bool operationComplete = false;
    ASSERT_FALSE(engine->runtimeRecreateRequired) << "after cancellation request";
    for (std::uint32_t block = 0;
         block < 256 && !(stale && restored && operationComplete); ++block) {
        harken::TimelineArmObservation observation{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(entering, &observation) &&
             observation.state == harken::ArmState::Started);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_FALSE(engine->runtimeRecreateRequired) << "after cancellation update block=" << block;
        stale = !engine->playableInstances.Classify(started.instance).live;
        restored = engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline;
        switch (GetParam()) {
        case StopAfterVariableControlSliceClaimContext::Intent::Stop:
            operationComplete = true;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            WorldReplacement:
            operationComplete =
                harken::InstallContainerWorldV1(
                    *engine, replacement.world).status ==
                harken::WorldInstallStatus::Ok;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            TransportReset:
            operationComplete =
                harken::BeginRuntimeTransportReset(*engine, 0) ==
                harken::RuntimeTransportResetStatus::Complete;
            ASSERT_FALSE(engine->runtimeRecreateRequired) << "after reset service block=" << block;
            break;
        }
    }
    EXPECT_FALSE(targetStarted);
    EXPECT_TRUE(stale);
    EXPECT_TRUE(restored);
    EXPECT_TRUE(operationComplete);
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement) {
        EXPECT_NE(installedWorld,
                  engine->variables.CurrentWorldGeneration());
    }
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset) {
        EXPECT_GT(engine->transportEpochOwner.Current(), transportBefore);
    }
    EXPECT_NE(worldBefore, installedWorld);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(
    StopWorldAndReset,
    NaturalEndVariableControlCancellationTest,
    testing::Values(
        StopAfterVariableControlSliceClaimContext::Intent::Stop,
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement,
        StopAfterVariableControlSliceClaimContext::Intent::TransportReset));

TEST(PlayableStart,
     VariableControlNewestDiscreteCutSupersedesPreparedOlderCut) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434E4557455354)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    ASSERT_EQ(7u,
              engine->ReadPlayableMember(base).voice.Facts().target.occurrenceOrdinal);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool prepared = false;
    for (std::uint32_t block = 0; block < 32 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        prepared = row->variableControlDiscreteRetargetPrepared;
        if (!prepared) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(prepared);
    const harken::DecisionToken olderDecision =
        row->variableControlDiscreteRetargetDecision;
    const harken::BankVersionToken olderBank =
        row->variableControlDiscreteRetargetBank;
    ASSERT_TRUE(olderDecision.Valid());
    ASSERT_TRUE(olderBank.Valid());

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    bool olderCommitted = false;
    bool olderBecameCurrent = false;
    bool latestApplied = false;
    for (std::uint32_t block = 0; block < 96 && !latestApplied; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot older{};
        olderCommitted = olderCommitted ||
            engine->decisions.CaptureCommitted(olderDecision, &older);
        olderBecameCurrent = olderBecameCurrent ||
            (row->variableControlDiscreteMemberCount == 1 &&
             engine->ReadPlayableMember(CurrentMemberSlot(*engine, base)).voice.Facts().target.occurrenceOrdinal ==
                 9u);
        engine->nullBackend.Pump(1);
        harken::VariableControlInstanceSnapshot side{};
        ASSERT_TRUE(engine->variableControlInstances.Capture(
            row->variableControlInstance, &side));
        latestApplied = !row->variableControlDiscreteRetargetPrepared &&
            side.discrete.lastApplied.generation > olderBank.generation &&
            row->variableControlDiscreteMemberCount == 1 &&
            engine->ReadPlayableMember(CurrentMemberSlot(*engine, base)).voice.Facts().target.occurrenceOrdinal ==
                7u;
    }
    EXPECT_FALSE(olderCommitted);
    EXPECT_FALSE(olderBecameCurrent);
    EXPECT_TRUE(latestApplied);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

