TEST(PlayableStart,
     VariableControlStopDuringWaitingContinuousRetargetRejectsLateAdmission) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434353544F5057)).status);
    VariableControlMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    harken::DecisionToken stoppedDecision{};
    bool waiting = false;
    for (std::uint32_t block = 0; block < 32 && !waiting; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (row->variableControlRetargetDecisionCommitted) {
            harken::DecisionCommittedSnapshot committed{};
            ASSERT_TRUE(engine->decisions.CaptureCommitted(
                row->variableControlRetargetDecision, &committed));
            if (committed.audioState == harken::AudioGroupState::Pending) {
                stoppedDecision = row->variableControlRetargetDecision;
                waiting = true;
                break;
            }
        }
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(waiting);
    ASSERT_TRUE(stoppedDecision.Valid());

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling, state.lifecycle);
    EXPECT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 99));

    bool stoppedDecisionAdmitted = false;
    bool stoppedSegmentApplied = false;
    bool stale = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot committed{};
        if (engine->decisions.CaptureCommitted(
                stoppedDecision, &committed)) {
            stoppedDecisionAdmitted = stoppedDecisionAdmitted ||
                committed.audioState == harken::AudioGroupState::Admitted;
        }
        stoppedSegmentApplied = stoppedSegmentApplied ||
            row->variableControlRetargetApplied;
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_FALSE(stoppedDecisionAdmitted);
    EXPECT_FALSE(stoppedSegmentApplied);
    EXPECT_TRUE(stale);
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlContinuousBankChangeRetargetsOnAbsoluteCadence) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(16384, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x564152434144454E)).status);
    VariableControlWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration(), true, true);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t slot =
        row->scheduleStorageBase + row->variableControlContinuousMemberOffset;
    ASSERT_LT(slot, engine->playableStorage.memberCount);
    const VnVoiceHandle render =
        engine->ReadPlayableMember(slot).render;
    const harken::VoiceRenderContext* voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    const auto* ownedWeight = FrontierOwnedVariableWeight(*voice, *row);
    ASSERT_NE(nullptr, ownedWeight);
    ASSERT_TRUE(ownedWeight->active);
    const harken::WeightSegmentV1 first = ownedWeight->segment;
    ASSERT_EQ(1u, first.segmentGeneration);
    EXPECT_FLOAT_EQ(0.0f, first.startWeight);
    EXPECT_NEAR(0.375f, first.endWeight, 1e-6f);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool retargeted = false;
    harken::WeightSegmentV1 second{};
    for (std::uint32_t block = 0; block < 32 && !retargeted; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        voice = engine->voices.Resolve(render);
        ASSERT_NE(nullptr, voice);
        if (ownedWeight->segment.segmentGeneration > 1u) {
            second = ownedWeight->segment;
            retargeted = true;
        }
    }
    ASSERT_TRUE(retargeted);
    EXPECT_EQ(2u, second.segmentGeneration);
    EXPECT_TRUE(first.decision.slot != second.decision.slot ||
                first.decision.generation != second.decision.generation);
    EXPECT_GT(second.bank.generation, first.bank.generation);
    EXPECT_EQ(0u, (second.startFrame - row->startFrame) %
                      image.container.evaluationPeriodFrames);
    float expectedStart = -1.0f;
    ASSERT_TRUE(harken::ResolveWeightSegment(
        first, second.startFrame, &expectedStart));
    EXPECT_FLOAT_EQ(expectedStart, second.startWeight);
    EXPECT_NEAR(0.875f, second.endWeight, 1e-6f);

    for (std::uint32_t block = 0;
         block < 16 && row->variableControlRetargetPrepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(row->variableControlRetargetPrepared);
    for (std::uint32_t block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    voice = engine->voices.Resolve(render);
    ASSERT_NE(nullptr, voice);
    EXPECT_EQ(2u, ownedWeight->segment.segmentGeneration);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 1.0f));
    bool retargetedAgain = false;
    harken::WeightSegmentV1 third{};
    for (std::uint32_t block = 0;
         block < 32 && !retargetedAgain; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        voice = engine->voices.Resolve(render);
        ASSERT_NE(nullptr, voice);
        if (ownedWeight->segment.segmentGeneration > 2u) {
            third = ownedWeight->segment;
            retargetedAgain = true;
        }
    }
    ASSERT_TRUE(retargetedAgain);
    EXPECT_EQ(3u, third.segmentGeneration);
    EXPECT_GT(third.bank.generation, second.bank.generation);
    EXPECT_EQ(0u, (third.startFrame - row->startFrame) %
                      image.container.evaluationPeriodFrames);
    ASSERT_TRUE(harken::ResolveWeightSegment(
        second, third.startFrame, &expectedStart));
    EXPECT_FLOAT_EQ(expectedStart, third.startWeight);
    EXPECT_NEAR(0.125f, third.endWeight, 1e-6f);
}

TEST(PlayableStart,
     BlendInitiallySilentMembersFinishBeforeAnotherTrigger) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(16384, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643414C4C5A4552)).status);
    VariableControlMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.cells[0].lower = 4.0f;
    image.cells[0].upper = 5.0f;
    image.cells[1].lower = 6.0f;
    image.cells[1].upper = 8.0f;

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    for (unsigned block = 0; block < 384; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        EXPECT_FLOAT_EQ(0.0f, harkentest::Peak(engine->nullBackend.LastBlock(), 128));
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    }
    const auto retriggered = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, retriggered.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_TRUE(StopUntilStale(*engine, retriggered.instance));
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}


TEST(PlayableStart,
     BlendWeightChangesKeepInitialOnsetsAndReleaseObservers) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();

    std::vector<float> samples(16384, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434D454D42414E)).status);
    VariableControlMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    ASSERT_EQ(2u, row->variableControlContinuousMemberCount);
    std::array<harken::EngineTimelineVoiceInstallIdentity, 2> initial{};
    for (unsigned index = 0; index < initial.size(); ++index) {
        const auto render = engine->ReadPlayableMember(CurrentMemberSlot(*engine, base + index)).render;
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(render, &initial[index]));
        EXPECT_FALSE(engine->voices.ReleaseObserved(initial[index].releaseObserver));
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool changed = false;
    for (unsigned block = 0; block < 64 && !changed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* voice = engine->voices.Resolve(initial[1].renderHandle);
        ASSERT_NE(nullptr, voice);
        const auto* weight = FrontierOwnedVariableWeight(*voice, *row);
        ASSERT_NE(nullptr, weight);
        changed = !row->variableControlRetargetPrepared && weight->segment.endWeight == 1.0f &&
            engine->mixer.BlocksRendered() * 64 >= weight->segment.endFrame;
        EXPECT_EQ(2u, row->variableControlContinuousMemberCount);
        EXPECT_EQ(2u, engine->voices.ActiveCount());
    }
    ASSERT_TRUE(changed);
    for (unsigned index = 0; index < initial.size(); ++index) {
        harken::EngineTimelineVoiceInstallIdentity current{};
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(initial[index].renderHandle, &current));
        EXPECT_EQ(initial[index].onsetFrame, current.onsetFrame);
        EXPECT_EQ(initial[index].releaseObserver.targetSequence, current.releaseObserver.targetSequence);
        const auto* voice = engine->voices.Resolve(initial[index].renderHandle);
        ASSERT_NE(nullptr, voice);
        EXPECT_FLOAT_EQ(index == 0 ? 0.0f : 1.0f,
            FrontierOwnedVariableWeight(*voice, *row)->segment.endWeight);
    }
    for (unsigned block = 0; block < 384; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (const auto& identity : initial) {
        EXPECT_EQ(nullptr, engine->voices.Resolve(identity.renderHandle));
        EXPECT_TRUE(engine->voices.ReleaseObserved(identity.releaseObserver));
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
}


