TEST(PlayableStart,
     VariableControlSameCadenceDiscreteAndContinuousRetargetDoNotCollide) {
    VnConfig config = harkentest::MakeNullConfig(64, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();

    std::vector<float> samples(65536, 0.125f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const std::array<harken::VariableDefinitionV1, 2> variables{{
        {harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f},
        {harkentest::ObjectId(42), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f},
    }};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, variables.data(), variables.size(),
                  UINT64_C(0x5643434153444352)).status);
    VariableControlCapacityWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t currentBase = row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    const std::size_t discreteTransitionSlot =
        row->scheduleStorageBase +
        row->variableControlDiscreteTransitionOffset;
    ASSERT_GE(discreteTransitionSlot,
              currentBase +
                  engine->config.maxVariableControlLiveRows);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(42), 7.0f));
    bool simultaneous = false;
    bool changed = false;
    for (std::uint32_t block = 0; block < 192 && !changed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (row->variableControlDiscreteRetargetPrepared &&
            row->variableControlRetargetPrepared) {
            simultaneous = true;
            EXPECT_EQ(2u,
                      engine->ReadPlayableMember(
                          discreteTransitionSlot).voice.Facts().target.
                          occurrenceOrdinal);
            for (std::uint32_t index = 0; index < 16; ++index) {
                ASSERT_LT(index, row->variableControlRetargetMembers.size());
                harken::EnginePlayableServiceRow* owner = nullptr;
                std::size_t memberSlot = 0;
                ASSERT_TRUE(engine->ResolvePlayableMember(row->variableControlRetargetMembers[index].reference,
                    &owner, &memberSlot));
                EXPECT_EQ(index + 2u,
                          engine->ReadPlayableMember(
                              memberSlot).voice.Facts().target.
                              occurrenceOrdinal);
            }
        }
        changed = !row->variableControlDiscreteRetargetPrepared &&
            !row->variableControlRetargetPrepared &&
            row->variableControlDiscreteMemberCount == 1u &&
            row->variableControlContinuousMemberCount == 16u &&
            engine->ReadPlayableMember(
                CurrentMemberSlot(*engine, row->scheduleStorageBase)).voice.Facts().target.occurrenceOrdinal == 2u &&
            engine->ReadPlayableMember(CurrentMemberSlot(*engine, currentBase)).voice.Facts().target.
                    occurrenceOrdinal == 2u;
    }
    EXPECT_TRUE(simultaneous);
    EXPECT_TRUE(changed);
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, started.instance, 0));
    harken::PlayableControlState state{};
    bool stale = false;
    for (std::uint32_t block = 0; block < 192 && !stale; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        stale = harken::QueryPlayable(
                    *engine, started.instance, &state) ==
            harken::PlayableControlStatus::StaleHandle;
    }
    EXPECT_TRUE(stale);
    ASSERT_NO_FATAL_FAILURE(ExpectTransferredDecisionsReclaimed(*engine, decisionBaseline));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(groupBaseline, engine->armGroups.LiveCount());
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

