TEST(PlayableStart, SubFrameAuthoredClipPublishesZeroWorkLogicalCompletion) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.placement.authoredStart = INT64_C(10000000);
    image.placement.authoredDuration = 10417;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    const std::uint64_t ticket = engine->logicCommits.Current();
    const std::uint32_t instances = engine->playableInstances.FreeCount();
    const std::uint32_t voices = engine->voices.ActiveCount();
    const std::uint32_t arms = engine->timelineArms.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    EXPECT_NE(0u, started.instance);
    EXPECT_EQ(ticket + 1u, started.ticket);
    EXPECT_EQ(ticket + 1u, engine->logicCommits.Current());
    EXPECT_EQ(instances - 1u, engine->playableInstances.FreeCount());
    EXPECT_EQ(voices, engine->voices.ActiveCount());
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::uint64_t expectedOffset = 480u;
    EXPECT_EQ(expectedOffset,
              row->startFrame -
                  std::max<std::uint64_t>(
                      engine->timelinePool.PublishCutoffFrame(),
                      std::max<std::uint64_t>(
                          1u, engine->timelinePool.PublishLeadQuanta()) *
                          engine->config.blockFrames));

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::Preparing, state.lifecycle);
    EXPECT_EQ(0u, state.lastAppliedBlockSequence);
    EXPECT_EQ(1u, state.pendingFutureCount);

    bool completed = false;
    for (std::uint32_t block = 0; block < 32 && !completed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (harken::QueryPlayable(*engine, started.instance, &state) ==
                harken::PlayableControlStatus::Ok) {
            completed =
                state.lifecycle ==
                harken::PlayableControlLifecycle::LogicalComplete;
        }
    }
    ASSERT_TRUE(completed);
    EXPECT_EQ(harken::PlayableControlReason::Natural, state.reason);
    EXPECT_NE(0u, state.lastAppliedBlockSequence);
    EXPECT_EQ(0u, state.pendingFutureCount);
    EXPECT_EQ(voices, engine->voices.ActiveCount());
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());

    bool retired = false;
    for (std::uint32_t block = 0; block < 32 && !retired; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        retired = !engine->playableInstances.Classify(started.instance).live;
    }
    EXPECT_TRUE(retired);
    EXPECT_EQ(instances, engine->playableInstances.FreeCount());
}

TEST(PlayableStart, ActionSubFrameTrackPublishesZeroWorkLogicalCompletion) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.placement.authoredStart = INT64_C(10000000);
    image.placement.authoredDuration = 1;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);

    harken::ActionStepProgramViewV1 step{};
    step.target = {harken::ActionTargetKindV1::Track, 0,
                   image.Root().stableId,
                   image.Root().expectedProgramSemanticFingerprint};
    step.delay = {harken::AuthoredTimeDomainV1::AbsoluteNanoseconds, 0, 1};
    step.fade = step.delay;
    step.cooldown = step.delay;
    harken::ActionProgramViewV1 action{};
    action.actionStableId = harkentest::ObjectId(10004);
    action.steps = &step;
    action.stepCount = 1;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(action);
    harken::ContainerWorldInstallViewV1 install{};
    install.identity = image.world.identity;
    install.identity.capabilityMask |=
        harken::kWorldCapabilityActionDefinitions;
    install.playableProperties = image.world.properties;
    install.playablePropertyCount = image.world.propertyCount;
    install.playableOccurrences = image.world.occurrences;
    install.playableOccurrenceCount = image.world.occurrenceCount;
    install.trackSchedules = image.world.trackSchedules;
    install.trackScheduleCount = image.world.trackScheduleCount;
    install.actions = &action;
    install.actionCount = 1;
    install.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(install);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, install).status);
    const std::uint32_t voices = engine->voices.ActiveCount();
    const std::uint32_t arms = engine->timelineArms.LiveCount();

    VnPostActionDesc desc{};
    desc.structSize = sizeof(desc);
    desc.actionId = action.actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult result{};
    result.structSize = sizeof(result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
    ASSERT_NE(0u, result.producedPlayableInstance);
    const auto* row = FindPlayableRow(
        *engine, result.producedPlayableInstance);
    ASSERT_NE(nullptr, row);
    EXPECT_TRUE(row->zeroWorkMarker);
    EXPECT_EQ(0u, row->scheduleLeafCount);
    EXPECT_EQ(voices, engine->voices.ActiveCount());
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());

    harken::PlayableControlState state{};
    bool completed = false;
    for (std::uint32_t block = 0; block < 32 && !completed; ++block) {
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        if (harken::QueryPlayable(
                *engine, result.producedPlayableInstance, &state) ==
            harken::PlayableControlStatus::Ok) {
            completed = state.lifecycle ==
                harken::PlayableControlLifecycle::LogicalComplete;
        }
    }
    ASSERT_TRUE(completed);
    EXPECT_EQ(harken::PlayableControlReason::Natural, state.reason);
    EXPECT_EQ(voices, engine->voices.ActiveCount());
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

