TEST(PlayableStart, NestedZeroWorkPieceCompletesAtInheritedClipBoundary) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(96000, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    NestedPieceWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.placements[1].authoredDuration = INT64_C(10000000);
    image.tracks[1].scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.tracks[1]);
    image.trackRefs[1].trackScheduleSemanticFingerprint =
        image.tracks[1].scheduleSemanticFingerprint;
    image.pieces[1].scheduleSemanticFingerprint =
        harken::ComputePieceScheduleFingerprintV1(image.pieces[1]);
    const std::uint64_t expectedBase = std::max<std::uint64_t>(
        engine->timelinePool.PublishCutoffFrame(),
        std::max<std::uint64_t>(
            1u, engine->timelinePool.PublishLeadQuanta()) *
            engine->config.blockFrames);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::uint64_t expectedBoundaryOffset = 2880u;
    const std::uint64_t expectedBoundary = row->startFrame;
    EXPECT_EQ(expectedBase + expectedBoundaryOffset, expectedBoundary);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());

    harken::PlayableControlState state{};
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           expectedBoundary) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::QueryPlayable(*engine, started.instance, &state));
        EXPECT_EQ(harken::PlayableControlLifecycle::Preparing,
                  state.lifecycle);
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::LogicalComplete,
              state.lifecycle);
    EXPECT_EQ(harken::PlayableControlReason::Natural, state.reason);
}

TEST(PlayableStart, StaggeredZeroWorkSiblingsCompleteAtLatestBoundary) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.placements[0].authoredStart = INT64_C(10000000);
    image.placements[0].authoredDuration = 1;
    image.placements[1].authoredStart = INT64_C(20000000);
    image.placements[1].authoredDuration = 1;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    const std::uint64_t expectedBase = std::max<std::uint64_t>(
        engine->timelinePool.PublishCutoffFrame(),
        std::max<std::uint64_t>(
            1u, engine->timelinePool.PublishLeadQuanta()) *
            engine->config.blockFrames);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::uint64_t expectedBoundary = expectedBase + 960u;
    EXPECT_EQ(expectedBoundary, row->startFrame);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());

    harken::PlayableControlState state{};
    while ((engine->mixer.BlocksRendered() + 1u) *
               engine->config.blockFrames < expectedBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::QueryPlayable(*engine, started.instance, &state));
        EXPECT_NE(harken::PlayableControlLifecycle::LogicalComplete,
                  state.lifecycle);
    }
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           expectedBoundary) {
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::LogicalComplete,
              state.lifecycle);
    EXPECT_EQ(harken::PlayableControlReason::Natural, state.reason);
}

