TEST(PlayableStart, ActionMixedZeroWorkSiblingExtendsAggregateCompletion) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(4800, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.placements[1].authoredStart = INT64_C(1000000000);
    image.placements[1].authoredDuration = 1;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);

    harken::ActionStepProgramViewV1 step{};
    step.target = {harken::ActionTargetKindV1::Track, 0,
                   image.Root().stableId,
                   image.Root().expectedProgramSemanticFingerprint};
    step.delay = {harken::AuthoredTimeDomainV1::AbsoluteNanoseconds, 0, 1};
    step.fade = step.delay;
    step.cooldown = step.delay;
    harken::ActionProgramViewV1 action{};
    action.actionStableId = harkentest::ObjectId(10001);
    action.steps = &step;
    action.stepCount = 1;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(action);
    harken::ContainerWorldInstallViewV1 install{};
    install.identity = image.world.identity;
    install.identity.capabilityMask |=
        harken::kWorldCapabilityActionDefinitions;
    install.playableProperties = image.world.properties;
    install.playablePropertyCount = image.world.propertyCount;
    install.playableOccurrences = image.world.occurrences;
    install.playableOccurrenceCount = image.world.occurrenceCount;
    install.trackSchedules = image.world.trackSchedules;
    install.trackScheduleCount = image.world.trackScheduleCount;
    install.actions = &action;
    install.actionCount = 1;
    install.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(install);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, install).status);

    VnPostActionDesc desc{};
    desc.structSize = sizeof(desc);
    desc.actionId = action.actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult result{};
    result.structSize = sizeof(result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
    ASSERT_NE(0u, result.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == result.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::uint64_t expectedBoundary = row->startFrame + 48000u;

    harken::PlayableControlState state{};
    while ((engine->mixer.BlocksRendered() + 1u) *
               engine->config.blockFrames < expectedBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::QueryPlayable(
                      *engine, result.producedPlayableInstance, &state));
        EXPECT_NE(harken::PlayableControlLifecycle::LogicalComplete,
                  state.lifecycle);
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_TRUE(engine->playableInstances.Classify(
        result.producedPlayableInstance).live);
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           expectedBoundary) {
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(
                  *engine, result.producedPlayableInstance, &state));
    EXPECT_EQ(harken::PlayableControlLifecycle::LogicalComplete,
              state.lifecycle);
    EXPECT_EQ(harken::PlayableControlReason::Natural, state.reason);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

