TEST(PlayableStart,
     VariableControlContinuousLogicalChildrenCompleteAtTheirOwnBoundaries) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C31)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(0u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousLogicalCount);
    EXPECT_EQ(7u, row->variableControlContinuousLogicalOrdinals[0]);
    EXPECT_EQ(9u, row->variableControlContinuousLogicalOrdinals[1]);
    const std::uint64_t firstBoundary = row->startFrame + 48000u;
    const std::uint64_t secondBoundary = row->startFrame + 96000u;
    EXPECT_EQ(firstBoundary,
              row->variableControlContinuousLogicalCompletionFrames[0]);
    EXPECT_EQ(secondBoundary,
              row->variableControlContinuousLogicalCompletionFrames[1]);
    EXPECT_EQ(secondBoundary, row->zeroWorkCompletionFrame);

    while (engine->mixer.BlocksRendered() * config.blockFrames <
           firstBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(row->variableControlContinuousLogicalCompleted[0]);
    EXPECT_FALSE(row->variableControlContinuousLogicalCompleted[1]);
    EXPECT_TRUE(row->hasZeroWorkCompletion);
    EXPECT_EQ(secondBoundary, row->zeroWorkCompletionFrame);

    while (engine->mixer.BlocksRendered() * config.blockFrames <
           secondBoundary) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(row->variableControlContinuousLogicalCompleted[0]);
    EXPECT_TRUE(row->variableControlContinuousLogicalCompleted[1]);
    EXPECT_FALSE(row->hasZeroWorkCompletion);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturallyCompleted(*engine, started.instance));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 4.0f));
    for (std::uint32_t block = 0; block < 12; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart,
     BlendVariableChangesPreserveEveryLogicalTrackDeadline) {
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth,
        0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5234434F4E544C33)).status);
    VariableControlLogicalTracksWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.cells[1].lower = 4.0f;
    image.cells[1].lowerInclusive = 0;

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(0u, row->variableControlContinuousMemberCount);
    ASSERT_EQ(2u, row->variableControlContinuousLogicalCount);
    ASSERT_EQ(2u, row->variableControlChildCount);
    const auto originalChildren = row->variableControlChildInstances;
    const auto originalBoundaries = row->variableControlContinuousLogicalCompletionFrames;
    const auto finalBoundary = row->zeroWorkCompletionFrame;
    ASSERT_EQ(row->startFrame + 96000u, finalBoundary);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    for (unsigned block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(originalChildren, row->variableControlChildInstances);
    EXPECT_EQ(originalBoundaries, row->variableControlContinuousLogicalCompletionFrames);
    EXPECT_FALSE(row->variableControlRetargetPrepared);
    for (unsigned block = 0; block < 2048; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->mixer.BlocksRendered() * config.blockFrames < finalBoundary)
            EXPECT_TRUE(engine->playableInstances.Classify(started.instance).live);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
}


