TEST(PlayableStart, StopThenRestartBuildsAFreshAbsoluteClipDeadline) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(96000, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.placement.authoredDuration = INT64_C(1000000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    harken::PlayableStartRequest request{};
    request.root = image.Root();

    const auto captureDeadline = [&](harken::PlayableInstanceHandle instance,
                                     std::uint64_t* start,
                                     std::uint64_t* deadline) {
        for (std::uint32_t block = 0; block < 32; ++block) {
            if (Vn_Update() != VN_OK) {
                ADD_FAILURE() << "Vn_Update failed while waiting for voice";
                return false;
            }
            engine->nullBackend.Pump(1);
            const auto row = std::find_if(
                engine->playableServices.begin(),
                engine->playableServices.end(),
                [&](const harken::EnginePlayableServiceRow& candidate) {
                    return candidate.rootInstance == instance;
                });
            if (row == engine->playableServices.end()) {
                continue;
            }
            const VnVoiceHandle render = row->renderHandle;
            const harken::VoiceRenderContext* voice =
                engine->voices.Resolve(render);
            if (voice == nullptr) continue;
            *start = row->startFrame;
            *deadline = voice->authoredSourceDeadlineFrame;
            return true;
        }
        return false;
    };

    const harken::PlayableStartResult first =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, first.status);
    std::uint64_t firstStart = 0;
    std::uint64_t firstDeadline = 0;
    ASSERT_TRUE(captureDeadline(first.instance, &firstStart, &firstDeadline));
    EXPECT_EQ(firstStart + 48000u, firstDeadline);
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, first.instance, 0));
    for (std::uint32_t block = 0;
         block < 64 &&
         engine->playableInstances.Classify(first.instance).live;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(engine->playableInstances.Classify(first.instance).live);

    const harken::PlayableStartResult second =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, second.status);
    std::uint64_t secondStart = 0;
    std::uint64_t secondDeadline = 0;
    ASSERT_TRUE(captureDeadline(second.instance, &secondStart,
                                &secondDeadline));
    EXPECT_GT(secondStart, firstStart);
    EXPECT_EQ(secondStart + 48000u, secondDeadline);
    EXPECT_NE(firstDeadline, secondDeadline);
}

TEST(PlayableStart, AbsoluteClipDeadlineOverflowRefusesAtomically) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision);
    image.placement.authoredDuration = INT64_C(1000000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    const std::uint64_t nearMax =
        ((UINT64_MAX - engine->config.scheduleHorizonFrames) /
         engine->config.blockFrames) * engine->config.blockFrames;
    ASSERT_TRUE(engine->timelinePool.ResetForEpoch(
        nearMax, engine->transportEpochOwner.Current()));
    const std::uint64_t ticket = engine->logicCommits.Current();
    const std::uint32_t instances = engine->playableInstances.FreeCount();
    const std::uint32_t voices = engine->voices.ActiveCount();
    const std::uint32_t arms = engine->timelineArms.LiveCount();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult refused =
        harken::StartPlayable(*engine, image.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::CapabilityUnavailable,
              refused.status);
    EXPECT_EQ(0u, refused.instance);
    EXPECT_EQ(0u, refused.ticket);
    EXPECT_EQ(ticket, engine->logicCommits.Current());
    EXPECT_EQ(instances, engine->playableInstances.FreeCount());
    EXPECT_EQ(voices, engine->voices.ActiveCount());
    EXPECT_EQ(arms, engine->timelineArms.LiveCount());
}

TEST(PlayableStart, DirectMusicalPieceSubtractsStartMarkerBeforeScheduling) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    DirectPieceWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ScheduleTimeKindV1::MusicalTicks, 960, 480);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const std::uint64_t expectedOffset = 12000;
    const std::uint64_t expectedBase = std::max<std::uint64_t>(
        engine->timelinePool.PublishCutoffFrame(),
        std::max<std::uint64_t>(
            1u, engine->timelinePool.PublishLeadQuanta()) *
            engine->config.blockFrames);
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(expectedOffset, row->startFrame - expectedBase);
    EXPECT_EQ(harken::PlayableKind::Piece,
              engine->playableInstances.Classify(started.instance).kind);
    bool audible = false;
    for (std::uint32_t block = 0; block < 220; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        audible = audible || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample != 0.0f; });
        if (audible) break;
    }
    EXPECT_TRUE(audible);
}

