TEST(PlayableStart, DirectTrackIndependentStartsCanExceedOneTransactionSpan) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.placements[1].authoredStart = INT64_C(240000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    ASSERT_GT(11520u, engine->timelinePool.MaxTransactionSpanFrames());
    ASSERT_LT(11520u + engine->timelinePool.PublishLeadQuanta() * config.blockFrames,
              engine->timelinePool.WindowEndFrame());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    std::uint64_t firstStart = UINT64_MAX;
    std::uint64_t secondStart = UINT64_MAX;
    for (std::uint32_t block = 0; block < 240; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < config.blockFrames; ++frame) {
            const float value = output[frame * 2u];
            const std::uint64_t at = block * config.blockFrames + frame;
            if (value > 0.00001f && firstStart == UINT64_MAX) firstStart = at;
            if (value < -0.00001f && secondStart == UINT64_MAX) secondStart = at;
        }
    }
    ASSERT_NE(UINT64_MAX, firstStart);
    ASSERT_NE(UINT64_MAX, secondStart);
    EXPECT_EQ(11520u, secondStart - firstStart);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
}

TEST(PlayableStart, DirectTrackDefersFutureLeafAtItsAuthoredFrame) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    const std::uint64_t futureOffsetFrames =
        engine->timelinePool.WindowEndFrame() + config.blockFrames;
    image.placements[0].authoredDuration = INT64_C(4000000);
    image.placements[1].authoredStart = static_cast<std::int64_t>(
        (futureOffsetFrames * UINT64_C(1000000000) + 47999u) / 48000u);
    image.placements[1].authoredDuration = INT64_C(8000000);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_EQ(1u, engine->timelineDeferred.Count());
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    const std::size_t base = row->scheduleStorageBase;
    const std::uint64_t firstStart =
        engine->ReadPlayableMember(base).startFrame;
    const std::uint64_t secondStart =
        engine->ReadPlayableMember(base + 1u).startFrame;
    EXPECT_EQ(futureOffsetFrames, secondStart - firstStart);
    const auto* firstVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base).render);
    const auto* secondVoice = engine->voices.Resolve(
        engine->ReadPlayableMember(base + 1u).render);
    ASSERT_NE(nullptr, firstVoice);
    ASSERT_NE(nullptr, secondVoice);
    EXPECT_EQ(firstStart + 192u, firstVoice->authoredSourceDeadlineFrame);
    EXPECT_EQ(secondStart + 384u, secondVoice->authoredSourceDeadlineFrame);
    std::uint64_t firstHeard = UINT64_MAX;
    std::uint64_t secondHeard = UINT64_MAX;
    const auto executorBefore = engine->timelineExecutor.Stats();
    bool secondStarted = false;
    std::uint64_t secondStartedBlock = 0;
    std::uint64_t maxSecondCursor = 0;
    const std::uint64_t blockBudget =
        secondStart / config.blockFrames + 16u;
    bool checkedBeforeFuture = false;
    for (std::uint64_t block = 0; block < blockBudget; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (!checkedBeforeFuture &&
            engine->mixer.BlocksRendered() * config.blockFrames +
                    config.blockFrames >=
                secondStart) {
            checkedBeforeFuture = true;
            EXPECT_TRUE(
                engine->playableInstances.Classify(started.instance).live);
            EXPECT_NE(nullptr, engine->voices.Resolve(
                                   engine->ReadPlayableMember(
                                       base + 1u).render));
        }
        harken::TimelineArmObservation secondObservation{};
        if (engine->timelineArms.Observe(
                engine->ReadPlayableMember(base + 1u).arm,
                &secondObservation)) {
            secondStarted = secondStarted ||
                secondObservation.startedBlockSequence != 0;
            secondStartedBlock = std::max(
                secondStartedBlock,
                secondObservation.startedBlockSequence);
        }
        if (const auto* currentSecond = engine->voices.Resolve(
                engine->ReadPlayableMember(base + 1u).render)) {
            maxSecondCursor = std::max(maxSecondCursor,
                                       currentSecond->srcCursor);
        }
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < config.blockFrames; ++frame) {
            const std::uint64_t at = block * config.blockFrames + frame;
            for (std::uint32_t channel = 0; channel < 2u; ++channel) {
                const float value = output[frame * 2u + channel];
                if (value > 0.00001f && firstHeard == UINT64_MAX) {
                    firstHeard = at;
                }
                if (value < -0.00001f && secondHeard == UINT64_MAX) {
                    secondHeard = at;
                }
            }
        }
        if (secondHeard != UINT64_MAX && engine->voices.ActiveCount() == 0) break;
    }
    EXPECT_TRUE(checkedBeforeFuture);
    EXPECT_TRUE(secondStarted);
    EXPECT_EQ(secondStart / config.blockFrames + 1u,
              secondStartedBlock);
    EXPECT_GT(maxSecondCursor, 0u);
    const auto executorAfter = engine->timelineExecutor.Stats();
    EXPECT_EQ(executorBefore.staleSkippedTransactions,
              executorAfter.staleSkippedTransactions);
    EXPECT_EQ(executorBefore.armPendingSkipped,
              executorAfter.armPendingSkipped);
    EXPECT_EQ(executorBefore.armFailedTransactions,
              executorAfter.armFailedTransactions);
    EXPECT_EQ(executorBefore.protocolViolation,
              executorAfter.protocolViolation);
    EXPECT_EQ(executorBefore.lateConsumedEvents,
              executorAfter.lateConsumedEvents);
    ASSERT_NE(UINT64_MAX, firstHeard);
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->timelineDeferred.PreparedCount());
    EXPECT_EQ(0u, engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(0u, engine->timelinePlanner.MaterializationReserveFailures());
    ASSERT_NE(UINT64_MAX, secondHeard);
    EXPECT_EQ(futureOffsetFrames, secondHeard - firstHeard);
    for (std::uint32_t block = 0;
         block < 256u &&
         engine->playableInstances.Classify(started.instance).live;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
}

TEST(PlayableStart,
     DirectTrackFutureLeafRefusesAtomicallyWhenDeferredPoolIsFull) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &pcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    const std::uint64_t futureOffsetFrames =
        engine->timelinePool.WindowEndFrame() + config.blockFrames;
    image.placements[1].authoredStart = static_cast<std::int64_t>(
        (futureOffsetFrames * UINT64_C(1000000000) + 47999u) / 48000u);
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);

    std::vector<harken::DeferredIntentToken> fillers;
    fillers.reserve(engine->timelineDeferred.Capacity());
    for (std::uint32_t index = 0;
         index < engine->timelineDeferred.Capacity(); ++index) {
        harken::DeferredIntent intent{};
        intent.ownerDomain = harken::DeferredIntentOwnerDomain::Action;
        intent.ownerHandle = 0x5000u + index;
        intent.ownerEpoch = 1u;
        intent.dueFrame = UINT64_MAX - index;
        const auto added = engine->timelineDeferred.AddClaimable(intent);
        ASSERT_EQ(harken::DeferredIntentRefusal::None, added.status);
        fillers.push_back(added.token);
    }
    const auto sequenceBefore = engine->logicCommits.Current();
    const auto instancesBefore = engine->playableInstances.FreeCount();
    const auto voicesBefore = engine->voices.AvailableSlotCount();
    const auto ledgerBefore = engine->ledger.AvailableEntryCount();
    const auto armsBefore = engine->timelineArms.LiveCount();
    const auto transactionsBefore =
        engine->timelinePool.LiveTransactionCount();
    const auto commandsBefore = engine->commands.PublishedHead();

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto refused = harken::StartPlayable(*engine, image.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::Backpressure, refused.status);
    EXPECT_EQ(0u, refused.instance);
    EXPECT_EQ(0u, refused.ticket);
    EXPECT_EQ(sequenceBefore, engine->logicCommits.Current());
    EXPECT_EQ(instancesBefore, engine->playableInstances.FreeCount());
    EXPECT_EQ(voicesBefore, engine->voices.AvailableSlotCount());
    EXPECT_EQ(ledgerBefore, engine->ledger.AvailableEntryCount());
    EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
    EXPECT_EQ(transactionsBefore,
              engine->timelinePool.LiveTransactionCount());
    EXPECT_EQ(commandsBefore, engine->commands.PublishedHead());
    EXPECT_EQ(0u, engine->timelineDeferred.PreparedCount());
    EXPECT_EQ(engine->timelineDeferred.Capacity(),
              engine->timelineDeferred.Count());

    for (const auto token : fillers) {
        ASSERT_TRUE(engine->timelineDeferred.Cancel(token));
    }
}

TEST(PlayableStart, DirectTrackStartsEverySimultaneousLeaf) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.placements[1].authoredStart = 0;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    harken::PlayableRootMetadata metadata{};
    ASSERT_TRUE(engine->playableInstances.CaptureRootMetadata(
        started.instance, &metadata));
    EXPECT_EQ(harken::PlayableKind::Track, metadata.definitionKind);
    EXPECT_EQ(image.Root().stableId, metadata.definitionStableId);
    EXPECT_EQ(image.Root().expectedProgramSemanticFingerprint,
              metadata.programSemanticFingerprint);
    const auto rootView = engine->playableInstances.Classify(started.instance);
    ASSERT_TRUE(rootView.live);
    std::uint32_t childCount = 0;
    for (auto child = rootView.firstChild; child != 0;) {
        const auto childView = engine->playableInstances.Classify(child);
        ASSERT_TRUE(childView.live);
        EXPECT_EQ(harken::PlayableKind::Sound, childView.kind);
        EXPECT_EQ(started.instance, childView.parent);
        child = childView.nextSibling;
        ++childCount;
    }
    EXPECT_EQ(2u, childCount);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    std::array<bool, 2> startedLeaves{};
    std::array<bool, 2> advancedLeaves{};
    for (std::uint32_t block = 0;
         block < 16 &&
         !(startedLeaves[0] && startedLeaves[1] &&
           advancedLeaves[0] && advancedLeaves[1]);
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        for (std::uint32_t index = 0; index < 2; ++index) {
            const std::size_t slot = row->scheduleStorageBase + index;
            const harken::VoiceRenderContext* source = engine->voices.Resolve(
                engine->ReadPlayableMember(slot).render);
            if (source == nullptr) continue;
            harken::TimelineArmObservation arm{};
            ASSERT_TRUE(engine->timelineArms.Observe(
                engine->ReadPlayableMember(slot).arm, &arm));
            startedLeaves[index] = startedLeaves[index] ||
                (arm.startedBlockSequence != 0 && !source->timelineGated);
            advancedLeaves[index] =
                advancedLeaves[index] || source->srcCursor > 0.0;
        }
    }
    EXPECT_TRUE(startedLeaves[0]);
    EXPECT_TRUE(startedLeaves[1]);
    EXPECT_TRUE(advancedLeaves[0]);
    EXPECT_TRUE(advancedLeaves[1]);
    bool retired = false;
    for (std::uint32_t block = 0; block < 256 && !retired; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        retired = !engine->playableInstances.Classify(started.instance).live;
    }
    EXPECT_TRUE(retired);
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
}

TEST(PlayableStart, PieceTracksSharingOrdinalZeroInstallEachLeafGroupSnapshot) {
    auto config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    for (const VnBusId id : {harkentest::ObjectId(2), harkentest::ObjectId(3), harkentest::ObjectId(4)})
        ASSERT_EQ(VN_OK, Vn_CreateBus(id, VN_BUS_MASTER));
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    DirectCompositePieceWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    std::array<harken::PlayablePropertyProgramViewV1, 5> properties{};
    std::copy_n(image.properties.begin(), 3, properties.begin());
    properties[3] = properties[2];
    properties[3].stableId = harkentest::ObjectId(3002);
    properties[3].authoredStableOrder = 3;
    properties[4] = image.properties[3];
    properties[4].authoredStableOrder = 4;
    const std::array<harken::SendV1, 2> sends{{
        {0, 0, harkentest::ObjectId(3), -6.0f, 0}, {0, 0, harkentest::ObjectId(4), -12.0f, 0}}};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& payload = properties[index].payload;
        payload.values[6].objectId = index == 0 ? VN_BUS_MASTER : harkentest::ObjectId(index + 1);
        payload.values[5].bits = std::bit_cast<std::uint32_t>(index == 0 ? -3.0f : -9.0f);
        payload.values[8].bits = std::bit_cast<std::uint32_t>(index == 0 ? -0.4f : 0.4f);
        payload.values[9].bits = std::bit_cast<std::uint32_t>(index == 0 ? 20.0f : 40.0f);
        payload.values[11].bits = std::bit_cast<std::uint32_t>(index == 0 ? 2.0f : 4.0f);
        payload.sendCount = 1;
        payload.sends = &sends[index];
    }
    for (auto& property : properties)
        property.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(property);
    auto tracks = std::array{image.schedule.track, image.schedule.track};
    auto trackRefs = std::array{image.trackRef, image.trackRef};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& placement = image.schedule.placements[index];
        placement.stablePlacementOrdinal = 0;
        placement.stableOccurrenceOrdinal = 0;
        placement.content.expectedProgramSemanticFingerprint = properties[index].programSemanticFingerprint;
        tracks[index].rootDefinition.stableId = properties[index + 2].stableId;
        tracks[index].rootDefinition.expectedProgramSemanticFingerprint =
            properties[index + 2].programSemanticFingerprint;
        tracks[index].placementCount = 1;
        tracks[index].placements = &placement;
        tracks[index].scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(tracks[index]);
        auto& occurrence = image.schedule.occurrences[index];
        occurrence.parentStableId = tracks[index].rootDefinition.stableId;
        occurrence.parentProgramSemanticFingerprint = tracks[index].rootDefinition.expectedProgramSemanticFingerprint;
        occurrence.stableOccurrenceOrdinal = 0;
        occurrence.childPlayable = placement.content;
        occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        trackRefs[index].trackDefinition = tracks[index].rootDefinition;
        trackRefs[index].trackScheduleSemanticFingerprint = tracks[index].scheduleSemanticFingerprint;
        trackRefs[index].stableTrackOrdinal = index;
    }
    image.piece.rootDefinition.expectedProgramSemanticFingerprint = properties[4].programSemanticFingerprint;
    image.piece.trackRefCount = 2;
    image.piece.trackRefs = trackRefs.data();
    image.piece.scheduleSemanticFingerprint = harken::ComputePieceScheduleFingerprintV1(image.piece);
    image.world.properties = properties.data();
    image.world.propertyCount = properties.size();
    image.world.trackSchedules = tracks.data();
    image.world.trackScheduleCount = tracks.size();
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    for (std::uint32_t index = 0; index < 2; ++index) {
        const auto input = engine->ReadPlayableMember(row->scheduleStorageBase + index).voice.Input();
        ASSERT_NE(nullptr, input.facts);
        const auto& voice = *input.facts;
        EXPECT_EQ(properties[index].stableId, voice.soundId);
        EXPECT_EQ(index == 0 ? VN_BUS_MASTER : harkentest::ObjectId(2), voice.outputBusId);
        EXPECT_FLOAT_EQ(index == 0 ? -3.0f : -9.0f, voice.outputBusVolumeDb);
        EXPECT_FLOAT_EQ(index == 0 ? -0.4f : 0.4f, voice.pan);
        EXPECT_FLOAT_EQ(index == 0 ? 0.2f : 0.4f, voice.spread);
        EXPECT_FLOAT_EQ(index == 0 ? 2.0f : 4.0f, voice.attenuationDistanceScaling);
        ASSERT_EQ(1u, input.sends.size());
        EXPECT_EQ(sends[index].targetBusId, input.sends[0].targetBusId);
        EXPECT_FLOAT_EQ(sends[index].sendLevel, input.sends[0].levelDb);
    }
    std::array<bool, 2> observed{};
    for (std::uint32_t block = 0; block < 16 && !(observed[0] && observed[1]); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        for (std::uint32_t index = 0; index < 2; ++index) {
            const auto slot = row->scheduleStorageBase + index;
            const auto* voice = engine->voices.Resolve(engine->ReadPlayableMember(slot).render);
            if (voice == nullptr) continue;
            EXPECT_EQ(engine->registry.Lookup(properties[index].stableId).channels[0], voice->pcm.channels[0]);
            EXPECT_FLOAT_EQ(index == 0 ? 0.2f : 0.4f, voice->width);
            observed[index] = true;
        }
    }
    EXPECT_TRUE(observed[0]);
    EXPECT_TRUE(observed[1]);
}

