TEST(PlayableStart,
     QueueImmediateTransitionFadesEveryCompositeTargetLeaf) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.schedule.placements[1].authoredStart = 0;
    image.schedule.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.schedule.track);
    image.children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, image.schedule.track.rootDefinition.stableId,
        image.schedule.track.scheduleSemanticFingerprint);
    std::swap(image.children[0], image.children[1]);
    image.children[0].stableChildOrdinal = 7;
    image.children[1].stableChildOrdinal = 8;
    for (std::uint32_t index = 0; index < image.children.size(); ++index) {
        image.occurrences[index].stableOccurrenceOrdinal =
            image.children[index].stableChildOrdinal;
        image.occurrences[index].childPlayable =
            image.children[index].playable;
        image.occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(
                image.occurrences[index]);
    }
    image.EnableImmediateTargetTransition(128);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto prepared = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), prepared);
    ASSERT_TRUE(prepared->queueContinuationPrepared);
    ASSERT_EQ(2u, prepared->queueSuccessorScheduleLeafCount);
    ASSERT_TRUE(prepared->queueTransition.Valid());
    harken::TransitionInstanceSnapshot transition{};
    ASSERT_TRUE(engine->transitionInstances.Capture(
        prepared->queueTransition, &transition));
    EXPECT_EQ(harken::TransitionAudibleGateState::Replaceable,
              transition.state);
    harken::ArmGroupSnapshot group{};
    ASSERT_TRUE(engine->armGroups.Capture(
        prepared->queueArmGroup, &group));
    EXPECT_EQ(2u, group.memberCount);
    const harken::TimelineProgramView& successor =
        prepared->queueSuccessorProgramPlane == 0
            ? prepared->runtimeProgram
            : prepared->queueSuccessorRuntimeProgram;
    ASSERT_EQ(4u, successor.payloadCount);
    for (std::uint32_t index = 0; index < 2; ++index) {
        EXPECT_EQ(harken::TimelineEventKind::Start,
                  successor.payloads[2u * index].kind);
        EXPECT_EQ(harken::TimelineEventKind::Envelope,
                  successor.payloads[2u * index + 1u].kind);
        EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeIn,
                  successor.payloads[2u * index + 1u].envelopeDirection);
    }
    ASSERT_NE(nullptr, engine->FindQueueSuccessorMember(*prepared, 0));
    ASSERT_NE(nullptr, engine->FindQueueSuccessorMember(*prepared, 1));
    const std::array<VnVoiceHandle, 2> targets{
        engine->FindQueueSuccessorMember(*prepared, 0)->render,
        engine->FindQueueSuccessorMember(*prepared, 1)->render};

    std::array<bool, 2> fadeObserved{};
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        for (std::uint32_t index = 0; index < targets.size(); ++index) {
            const harken::VoiceRenderContext* target =
                engine->voices.Resolve(targets[index]);
            if (target != nullptr &&
                target->timelineEnvelopes[0].active) {
                EXPECT_FALSE(target->timelineEnvelopes[0].fadeOut);
                fadeObserved[index] = true;
            }
        }
    }
    EXPECT_TRUE(fadeObserved[0]);
    EXPECT_TRUE(fadeObserved[1]);
}

