TEST(PlayableStart, QueueCompositeSuccessorAdvancesOnlyAfterLatestLeaf) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    std::array<harken::ContainerChildProgramViewV2, 3> children{
        image.children[1], image.children[0], image.children[1]};
    std::array<harken::PlayableOccurrencePropertyViewV1, 5> occurrences{};
    for (std::uint32_t index = 0; index < children.size(); ++index) {
        children[index].stableChildOrdinal = 7u + index;
        children[index].authoredStableOrder = index;
        occurrences[index].parentKind = harken::playableproperties::
            ContentPropertyKindV1::Container;
        occurrences[index].parentStableId = harkentest::ObjectId(kContainer);
        occurrences[index].parentProgramSemanticFingerprint =
            image.properties[3].programSemanticFingerprint;
        occurrences[index].stableOccurrenceOrdinal =
            children[index].stableChildOrdinal;
        occurrences[index].childPlayable = children[index].playable;
        occurrences[index].payload = CanonicalPayload();
        occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(
                occurrences[index]);
    }
    occurrences[3] = image.schedule.occurrences[0];
    occurrences[4] = image.schedule.occurrences[1];
    harken::ContainerProgramViewV3 container = image.container;
    container.childCount = children.size();
    container.children = children.data();
    harken::PlayableWorldViewV1 world = image.world;
    world.occurrences = occurrences.data();
    world.occurrenceCount = occurrences.size();
    world.containers = &container;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    bool heardInitial = false;
    bool heardLatestCompositeLeaf = false;
    bool finalStartedAfterLatest = false;
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            heardInitial = heardInitial || output[sample] > 0.0f;
            heardLatestCompositeLeaf =
                heardLatestCompositeLeaf ||
                (heardInitial && output[sample] < 0.0f);
        }
        const auto active = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        const auto* activeInstall = active == engine->playableServices.end()
            ? nullptr : engine->ResolvePlayableServiceVoice(*active);
        if (activeInstall != nullptr &&
            active->queueInstance.Valid() && heardLatestCompositeLeaf &&
            activeInstall->Facts().soundId == kSound) {
            harken::QueueInstanceSnapshot queue{};
            harken::TimelineArmObservation arm{};
            finalStartedAfterLatest = finalStartedAfterLatest ||
                (engine->queueInstances.Capture(
                     active->queueInstance, &queue) &&
                 queue.logicMirror.version == 3u &&
                 queue.logicMirror.currentChildOrdinal == 9u &&
                 engine->timelineArms.Observe(active->arm, &arm) &&
                 arm.startedBlockSequence != 0);
        }
    }
    EXPECT_TRUE(heardInitial);
    EXPECT_TRUE(heardLatestCompositeLeaf);
    EXPECT_TRUE(finalStartedAfterLatest);
}

TEST(PlayableStart,
     QueueTransitionPromotesCompositeSuccessorAndStartsNextContinuation) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision);
    image.schedule.placements[1].authoredStart = 0;
    image.schedule.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.schedule.track);
    image.children[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, image.schedule.track.rootDefinition.stableId,
        image.schedule.track.scheduleSemanticFingerprint);
    image.EnableImmediateTargetTransition(128);
    std::array<harken::ContainerChildProgramViewV2, 3> children{
        image.children[1], image.children[0], image.children[1]};
    std::array<harken::PlayableOccurrencePropertyViewV1, 5> occurrences{};
    for (std::uint32_t index = 0; index < children.size(); ++index) {
        children[index].stableChildOrdinal = 7u + index;
        children[index].authoredStableOrder = index;
        occurrences[index].parentKind = harken::playableproperties::
            ContentPropertyKindV1::Container;
        occurrences[index].parentStableId = harkentest::ObjectId(kContainer);
        occurrences[index].parentProgramSemanticFingerprint =
            image.properties[3].programSemanticFingerprint;
        occurrences[index].stableOccurrenceOrdinal =
            children[index].stableChildOrdinal;
        occurrences[index].childPlayable = children[index].playable;
        occurrences[index].payload = CanonicalPayload();
        occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(
                occurrences[index]);
    }
    occurrences[3] = image.schedule.occurrences[0];
    occurrences[4] = image.schedule.occurrences[1];
    harken::ContainerProgramViewV3 container = image.container;
    container.childCount = children.size();
    container.children = children.data();
    harken::PlayableWorldViewV1 world = image.world;
    world.occurrences = occurrences.data();
    world.occurrenceCount = occurrences.size();
    world.containers = &container;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    bool heardInitial = false;
    bool heardCompositeNegativeLeaf = false;
    bool finalStartedAfterComposite = false;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < 2u * engine->config.blockFrames; ++sample) {
            heardInitial = heardInitial || output[sample] > 0.0f;
            heardCompositeNegativeLeaf =
                heardCompositeNegativeLeaf ||
                (heardInitial && output[sample] < 0.0f);
        }
        const auto active = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        const auto* activeInstall = active == engine->playableServices.end()
            ? nullptr : engine->ResolvePlayableServiceVoice(*active);
        if (activeInstall != nullptr &&
            active->queueInstance.Valid() && heardCompositeNegativeLeaf &&
            activeInstall->Facts().soundId == kSound) {
            harken::QueueInstanceSnapshot queue{};
            harken::TimelineArmObservation arm{};
            finalStartedAfterComposite = finalStartedAfterComposite ||
                (engine->queueInstances.Capture(
                     active->queueInstance, &queue) &&
                 queue.logicMirror.version == 3u &&
                 queue.logicMirror.currentChildOrdinal == 9u &&
                 engine->timelineArms.Observe(active->arm, &arm) &&
                 arm.startedBlockSequence != 0);
        }
    }
    EXPECT_TRUE(heardInitial);
    EXPECT_TRUE(heardCompositeNegativeLeaf);
    EXPECT_TRUE(finalStartedAfterComposite);
}

TEST(PlayableStart,
     VariableControlTransitionStartsEveryCompositeTrackTargetLeaf) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(65536, 0.25f);
    std::vector<float> second(65536, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434D554C544956)).status);
    VariableControlCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetImmediateFades(128, 192);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    const VnVoiceHandle sourceVoice =
        engine->ReadPlayableMember(base).render;
    for (unsigned block = 0; block < 3; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool captureRefused = false;
    for (unsigned block = 0; block < 64 && !captureRefused; ++block) {
        const auto voicesBefore = engine->voices.ActiveCount();
        const auto armsBefore = engine->timelineArms.LiveCount();
        const auto ledgerBefore = engine->ledger.AvailableEntryCount();
        const auto commandsBefore = engine->commands.PublishedHead();
        harken::detail::ArmLogicAllocFaultForTests(
            2, harken::detail::LogicAllocSite::CapturedVoiceInstall);
        const auto updated = Vn_Update();
        captureRefused = harken::detail::g_logicAllocFault.remaining == 0;
        harken::detail::DisarmLogicAllocFaultForTests();
        ASSERT_EQ(VN_OK, updated);
        ASSERT_FALSE(row->variableControlDiscreteRetargetPrepared);
        if (captureRefused) {
            EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
            EXPECT_EQ(armsBefore, engine->timelineArms.LiveCount());
            EXPECT_EQ(ledgerBefore, engine->ledger.AvailableEntryCount());
            EXPECT_EQ(commandsBefore, engine->commands.PublishedHead());
            EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoice));
            EXPECT_FALSE(engine->runtimeRecreateRequired);
        } else {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(captureRefused);
    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    ASSERT_TRUE(row->variableControlDiscreteRetargetReplacement);
    EXPECT_EQ(1u,
              row->variableControlDiscreteRetargetSourceMemberCount);
    EXPECT_EQ(2u,
              row->variableControlDiscreteRetargetTargetMemberCount);
    EXPECT_EQ(3u,
              row->variableControlDiscreteRetargetGroupMemberCount);
    ASSERT_EQ(4u,
              row->variableControlDiscreteRetargetEnteringRuntimeProgram.
                  payloadCount);
    const std::uint64_t decisionFrame =
        row->variableControlDiscreteRetargetFrame;
    const auto* entering =
        row->variableControlDiscreteRetargetEnteringRuntimeProgram.payloads;
    for (std::uint32_t index = 0; index < 2; ++index) {
        const std::uint32_t eventBase = 2u * index;
        EXPECT_EQ(harken::TimelineEventKind::Start,
                  entering[eventBase].kind);
        EXPECT_EQ(harken::TimelineEventKind::Envelope,
                  entering[eventBase + 1u].kind);
        EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeIn,
                  entering[eventBase + 1u].envelopeDirection);
        EXPECT_EQ(decisionFrame,
                  entering[eventBase + 1u].envelopeStartFrame);
        EXPECT_EQ(decisionFrame + 192u,
                  entering[eventBase + 1u].envelopeEndFrame);
        EXPECT_EQ(2u,
                  row->variableControlDiscreteRetargetEnteringRuntimePrograms[
                          index]
                      .payloadCount);
    }
    const auto* exiting =
        row->variableControlDiscreteRetargetRuntimeProgram.payloads;
    ASSERT_EQ(2u,
              row->variableControlDiscreteRetargetRuntimeProgram.payloadCount);
    EXPECT_EQ(harken::TimelineEventKind::Envelope, exiting[0].kind);
    EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeOut,
              exiting[0].envelopeDirection);
    EXPECT_EQ(decisionFrame, exiting[0].envelopeStartFrame);
    EXPECT_EQ(decisionFrame + 128u, exiting[0].envelopeEndFrame);
    EXPECT_EQ(harken::TimelineEventKind::Stop, exiting[1].kind);
    EXPECT_EQ(decisionFrame + 128u, exiting[1].envelopeEndFrame);

    std::array<VnVoiceHandle, 2> targetVoices{};
    for (std::uint32_t index = 0; index < targetVoices.size(); ++index) {
        targetVoices[index] = engine->ReadPlayableMember(
            base + row->variableControlDiscreteTransitionOffset + index).render;
        ASSERT_NE(0u, targetVoices[index]);
        EXPECT_NE(sourceVoice, targetVoices[index]);
        const auto member = base + row->variableControlDiscreteTransitionOffset + index;
        harkentest::ExpectTimelineInstallIdentity(*engine, targetVoices[index],
            row->rootInstance, engine->ReadPlayableMember(member).voice.Facts().target,
            decisionFrame, engine->ReadPlayableMember(member).arm);
    }
    EXPECT_NE(targetVoices[0], targetVoices[1]);
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           decisionFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const harken::VoiceRenderContext* sourceRender =
        engine->voices.Resolve(sourceVoice);
    ASSERT_NE(nullptr, sourceRender);
    EXPECT_TRUE(sourceRender->timelineEnvelopes[1].active);
    EXPECT_TRUE(sourceRender->timelineEnvelopes[1].fadeOut);
    for (VnVoiceHandle targetVoice : targetVoices) {
        const harken::VoiceRenderContext* targetRender =
            engine->voices.Resolve(targetVoice);
        ASSERT_NE(nullptr, targetRender);
        EXPECT_FALSE(targetRender->timelineGated);
        EXPECT_TRUE(targetRender->timelineEnvelopes[0].active);
        EXPECT_FALSE(targetRender->timelineEnvelopes[0].fadeOut);
    }

    bool promoted = false;
    bool bothTargetsAdvanced = false;
    for (std::uint32_t block = 0; block < 32 && !promoted; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const harken::VoiceRenderContext* firstTarget =
            engine->voices.Resolve(targetVoices[0]);
        const harken::VoiceRenderContext* secondTarget =
            engine->voices.Resolve(targetVoices[1]);
        bothTargetsAdvanced = bothTargetsAdvanced ||
            (firstTarget != nullptr && firstTarget->srcCursor > 0.0 &&
             secondTarget != nullptr && secondTarget->srcCursor > 0.0);
        promoted = row->variableControlDiscreteRetargetSourceExited &&
            row->variableControlDiscreteMemberCount == 2u &&
            engine->voices.Resolve(sourceVoice) == nullptr &&
            engine->ReadPlayableMember(CurrentMemberSlot(*engine, base)).render == targetVoices[0] &&
            engine->ReadPlayableMember(CurrentMemberSlot(*engine, base + 1u)).render ==
                targetVoices[1];
    }
    EXPECT_TRUE(bothTargetsAdvanced);
    EXPECT_TRUE(promoted)
        << "prepared=" << row->variableControlDiscreteRetargetPrepared
        << " applied=" << row->variableControlDiscreteRetargetApplied
        << " sourceExited="
        << row->variableControlDiscreteRetargetSourceExited
        << " cleanup="
        << row->variableControlDiscreteRetargetCleanupStarted
        << " members=" << row->variableControlDiscreteMemberCount
        << " sourceAlive="
        << (engine->voices.Resolve(sourceVoice) != nullptr)
        << " current0=" << engine->ReadPlayableMember(base).render
        << " current1=" << engine->ReadPlayableMember(base + 1u).render
        << " target0=" << targetVoices[0]
        << " target1=" << targetVoices[1]
        << " recreate=" << engine->runtimeRecreateRequired;
    for (std::uint32_t block = 0;
         block < 16 && row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_EQ(2u, row->variableControlDiscreteMemberCount);
    EXPECT_NE(nullptr, engine->voices.Resolve(targetVoices[0]));
    EXPECT_NE(nullptr, engine->voices.Resolve(targetVoices[1]));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

