TEST_P(CompositeVariableControlCancellationTest,
       CommittedPendingTransitionCancelsWithoutStartingTargetOrLeaking) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t decisionBaseline = engine->decisions.LiveCount();
    const std::uint32_t groupBaseline = engine->armGroups.LiveCount();
    const std::uint32_t transitionBaseline =
        engine->transitionInstances.LiveCount();
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const harken::WorldGeneration worldBefore =
        engine->variables.CurrentWorldGeneration();
    const harken::TransportEpoch transportBefore =
        engine->transportEpochOwner.Current();
    std::vector<float> first(65536, 0.25f);
    std::vector<float> second(65536, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434D554C545354)).status);
    const harken::WorldGeneration installedWorld =
        engine->variables.CurrentWorldGeneration();
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    harkentest::AdvanceVariableWrite(engine);
    VariableControlCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetImmediateFades(1024, 192);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    bool committedPending = false;
    for (std::uint32_t block = 0; block < 64 && !committedPending; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::DecisionCommittedSnapshot decision{};
        committedPending =
            row->variableControlDiscreteRetargetDecisionCommitted &&
            engine->decisions.CaptureCommitted(
                row->variableControlDiscreteRetargetDecision, &decision) &&
            decision.audioState == harken::AudioGroupState::Pending;
        if (!committedPending) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committedPending);
    ASSERT_EQ(3u,
              row->variableControlDiscreteRetargetGroupMemberCount);
    const harken::TimelineArmToken entering =
        row->variableControlDiscreteRetargetEnteringArm;
    ASSERT_TRUE(entering.Valid());

    PlayableWorldImage replacement(
        engine->registry.Lookup(kSound).contentRevision,
        harken::ContainerModeV1::Random);
    switch (GetParam()) {
    case StopAfterVariableControlSliceClaimContext::Intent::Stop:
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, started.instance, 0));
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement:
        row->variableControlWorldUsesCurrentAuthority = true;
        ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
                  harken::InstallContainerWorldV1(
                      *engine, replacement.world).status);
        break;
    case StopAfterVariableControlSliceClaimContext::Intent::TransportReset:
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
                  harken::BeginRuntimeTransportReset(*engine, 0));
        break;
    }

    bool targetStarted = false;
    bool stale = false;
    bool restored = false;
    bool operationComplete = false;
    for (std::uint32_t block = 0;
         block < 256 && !(stale && restored && operationComplete); ++block) {
        harken::TimelineArmObservation observation{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(entering, &observation) &&
             observation.state == harken::ArmState::Started);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        stale = !engine->playableInstances.Classify(started.instance).live;
        restored = engine->voices.ActiveCount() == voiceBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->decisions.LiveCount() == decisionBaseline &&
            engine->armGroups.LiveCount() == groupBaseline &&
            engine->transitionInstances.LiveCount() == transitionBaseline &&
            engine->playableInstances.LiveCount() == instanceBaseline;
        switch (GetParam()) {
        case StopAfterVariableControlSliceClaimContext::Intent::Stop:
            operationComplete = true;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            WorldReplacement:
            operationComplete =
                harken::InstallContainerWorldV1(
                    *engine, replacement.world).status ==
                harken::WorldInstallStatus::Ok;
            break;
        case StopAfterVariableControlSliceClaimContext::Intent::
            TransportReset:
            operationComplete =
                harken::BeginRuntimeTransportReset(*engine, 0) ==
                harken::RuntimeTransportResetStatus::Complete;
            break;
        }
    }
    EXPECT_FALSE(targetStarted);
    EXPECT_TRUE(stale);
    EXPECT_TRUE(restored);
    EXPECT_TRUE(operationComplete);
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          WorldReplacement) {
        EXPECT_NE(installedWorld,
                  engine->variables.CurrentWorldGeneration());
    }
    if (GetParam() == StopAfterVariableControlSliceClaimContext::Intent::
                          TransportReset) {
        EXPECT_GT(engine->transportEpochOwner.Current(), transportBefore);
    }
    EXPECT_NE(worldBefore, installedWorld);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(
    StopWorldAndReset,
    CompositeVariableControlCancellationTest,
    testing::Values(
        StopAfterVariableControlSliceClaimContext::Intent::Stop,
        StopAfterVariableControlSliceClaimContext::Intent::WorldReplacement,
        StopAfterVariableControlSliceClaimContext::Intent::TransportReset));

TEST(PlayableStart,
     VariableControlNewestValueSupersedesPreparedCompositeTransition) {
    VnConfig config = harkentest::MakeNullConfig(5, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(65536, 0.25f);
    std::vector<float> second(65536, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x56434D554C545350)).status);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    harkentest::AdvanceVariableWrite(engine);
    VariableControlCompositeTrackWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetImmediateFades(1024, 192);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    std::vector<harkentest::monitor::IdentityRecord> initialSelections;
    for (const auto& record : harkentest::monitor::ReadIdentityEvents(capture))
        if (record.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED) initialSelections.push_back(record);
    ASSERT_EQ(2u, initialSelections.size());
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    const std::array<VnVoiceHandle, 2> sourceVoices = {
        engine->ReadPlayableMember(base).render,
        engine->ReadPlayableMember(base + 1u).render};

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 3.0f));
    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    const harken::DecisionToken olderDecision =
        row->variableControlDiscreteRetargetDecision;
    const harken::TimelineArmToken olderEnteringArm =
        row->variableControlDiscreteRetargetEnteringArm;
    const VnVoiceHandle supersededTarget =
        engine->ReadPlayableMember(
            base + row->variableControlDiscreteTransitionOffset).render;
    ASSERT_NE(0u, supersededTarget);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));

    bool targetStarted = false;
    bool settled = false;
    for (std::uint32_t block = 0; block < 128 && !settled; ++block) {
        harken::TimelineArmObservation entering{};
        targetStarted = targetStarted ||
            (engine->timelineArms.Observe(
                 olderEnteringArm, &entering) &&
             entering.state == harken::ArmState::Started);
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        harken::VariableControlInstanceSnapshot side{};
        ASSERT_TRUE(engine->variableControlInstances.Capture(
            row->variableControlInstance, &side));
        settled = !row->variableControlDiscreteRetargetPrepared &&
            side.discrete.state ==
                harken::VariableControlSideState::Committed &&
            row->variableControlDiscreteMemberCount == 2u &&
            row->variableControlDiscreteCurrentChildOrdinal == 9u &&
            engine->voices.Resolve(supersededTarget) == nullptr;
    }
    harken::DecisionCommittedSnapshot staleDecision{};
    EXPECT_FALSE(targetStarted);
    EXPECT_TRUE(settled);
    EXPECT_FALSE(engine->decisions.CaptureCommitted(
        olderDecision, &staleDecision));
    EXPECT_EQ(nullptr, engine->voices.Resolve(supersededTarget));
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[0]));
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[1]));
    for (const auto& record : harkentest::monitor::ReadIdentityEvents(capture))
        EXPECT_NE(VN_MONITOR_FACT_SELECTION_COMMITTED, record.fact.factKind)
            << "A superseded candidate must not become a committed selection";
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

