static void CheckSignalQueueReceiptStop(bool applyBeforeStop) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(96, 0.25f), second(2048, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision, harken::QueueCycleV1::Loop, true,
        harken::AuthoredCompletionClassV1::SignalOnly,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&request.emitter));
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    std::vector<harkentest::monitor::IdentityRecord> records;
    const auto countSelections = [&] {
        return std::count_if(records.begin(), records.end(), [](const auto& record) {
            return record.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED;
        });
    };
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto queue = row->queueInstance;
    const auto checkpointKey = row->queueCheckpointKey;
    for (std::uint32_t block = 0; block < 32 && !row->frontierAcceptedSignal.Valid(); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, records);
        if (!row->frontierAcceptedSignal.Valid()) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(row->frontierAcceptedSignal.Valid());
    EXPECT_EQ(1, countSelections());
    const auto entry = row->frontierEntry;
    const auto arm = row->arm;
    const auto onset = row->startFrame;
    harken::EffectiveQueueState pending{};
    ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
    EXPECT_EQ(1u, pending.version);
    EXPECT_EQ(image.children[0].stableChildOrdinal, pending.currentChildOrdinal);
    if (applyBeforeStop) {
        while (engine->mixer.BlocksRendered() <= onset / 64) {
            ASSERT_EQ(VN_OK, Vn_Update());
            harkentest::monitor::CollectIdentityEvents(capture, records);
            ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
            EXPECT_EQ(1u, pending.version);
            engine->nullBackend.Pump(1);
        }
        harken::TimelineArmObservation observed{};
        ASSERT_TRUE(engine->timelineArms.Observe(arm, &observed));
        EXPECT_EQ(onset / 64 + 1u, observed.startedBlockSequence);
        const auto* activation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready,
            activation->Read(entry, engine->mixer.BlocksRendered(), &receipt));
        EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        ASSERT_TRUE(engine->queueInstances.ResolveEffective(queue, &pending));
        EXPECT_EQ(1u, pending.version);
    }
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, started.instance, 0));
    for (std::uint32_t block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::monitor::CollectIdentityEvents(capture, records);
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    harkentest::monitor::CollectIdentityEvents(capture, records);
    harken::QueueCheckpointImage checkpoint{};
    ASSERT_TRUE(engine->queueCheckpoints.Load(checkpointKey, &checkpoint));
    EXPECT_EQ(applyBeforeStop ? 2u : 1u, checkpoint.effective.version);
    EXPECT_EQ(image.children[applyBeforeStop ? 1u : 0u].stableChildOrdinal,
        checkpoint.effective.currentChildOrdinal);
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    harkentest::monitor::CollectIdentityEvents(capture, records);
    EXPECT_EQ(applyBeforeStop ? 2 : 1, countSelections());
    unsigned successors = 0;
    for (const auto& record : records) {
        if (record.fact.factKind != VN_MONITOR_FACT_SELECTION_COMMITTED ||
            record.header.stableId != kSecondSound) continue;
        ++successors;
        EXPECT_EQ(started.instance, record.fact.root);
        EXPECT_FALSE(harken::monitor::FactHas(record.fact, VN_MONITOR_FACT_FIELD_SELECTION_REQUEST));
    }
    EXPECT_EQ(applyBeforeStop ? 1u : 0u, successors);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
}

TEST(PlayableStart, SignalQueueAcceptedChildDoesNotAdvanceBeforeAudioAndStopReturnsSelection) {
    CheckSignalQueueReceiptStop(false);
}

TEST(PlayableStart, SignalQueueAppliedChildSettlesBeforeStopWithoutInterveningUpdate) {
    CheckSignalQueueReceiptStop(true);
}

TEST(PlayableStart, SequenceQueueMarkerAlignedRequiresKnownCompletion) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage known(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue,
        harken::QueueSpliceV1::MarkerAligned);
    harken::PlayableStartRequest request{};
    request.root = known.Root();
    const harken::PlayableStartResult accepted =
        harken::StartPlayable(*engine, known.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, accepted.status);

    bool heardFirst = false;
    bool heardSecond = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        heardFirst = heardFirst || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample > 0.0f; });
        heardSecond = heardSecond || std::any_of(
            output, output + 2u * engine->config.blockFrames,
            [](float sample) { return sample < 0.0f; });
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecond);

    SequenceQueueWorldImage signal(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::SignalOnly,
        harken::SignalOnlyPolicyV1::StartNextAtEarliestSafeNoOverlap,
        harken::QueueSpliceV1::MarkerAligned);
    request.root = signal.Root();
    const harken::PlayableStartResult refused =
        harken::StartPlayable(*engine, signal.world, request);
    EXPECT_EQ(harken::PlayableStartStatus::CapabilityUnavailable,
              refused.status);
}

TEST(PlayableStart, SequenceQueueTailNeverBecomesCurrentAfterAdvance) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> first(96, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &firstPcm), VN_OK);
    ASSERT_EQ(Vn_RegisterPCM(kSecondSound, &secondPcm), VN_OK);
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue,
        harken::QueueSpliceV1::Butt, true);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    const harken::EnginePlayableServiceRow* row = nullptr;
    bool successorCurrentWhileTailLive = false;
    for (std::uint32_t block = 0; block < 24; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto found = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == started.instance;
            });
        if (found == engine->playableServices.end()) break;
        row = &*found;
        std::uint32_t liveChildren = 0;
        engine->ledger.ForEachPlayableOwnedLive(
            [&](VnVoiceHandle render,
                const harken::VoiceLedger::PlayableParentRef& parent) {
                if (parent.internalToken == started.instance &&
                    engine->voices.Resolve(render) != nullptr) {
                    ++liveChildren;
                }
            });
        successorCurrentWhileTailLive =
            successorCurrentWhileTailLive ||
            (row->leaf.stableId == kSecondSound && liveChildren >= 2u);
    }
    EXPECT_TRUE(successorCurrentWhileTailLive);
}

