TEST(PlayableStart, TimelineInstallIdentityRetainsExactExitAcrossReuseAndQuarantine) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(1, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    PlayableWorldImage image(engine->registry.Lookup(kSound).contentRevision,
                             harken::ContainerModeV1::Random);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    harken::PlayableStartRequest request{};
    request.root = image.SoundRoot();
    const auto first = harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, first.status);
    auto* row = FindPlayableRow(*engine, first.instance);
    ASSERT_NE(nullptr, row);
    harken::EngineTimelineVoiceInstallIdentity original{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(row->renderHandle, &original));
    const auto* initialInstall = engine->ResolvePlayableServiceVoice(*row);
    ASSERT_NE(nullptr, initialInstall);
    harkentest::ExpectTimelineInstallIdentity(*engine, row->renderHandle, row->rootInstance,
        initialInstall->Facts().target, row->startFrame, row->arm);
    EXPECT_FALSE(engine->voices.ReleaseObserved(original.releaseObserver));
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_TRUE(StopUntilStale(*engine, first.instance));
    EXPECT_TRUE(engine->voices.ReleaseObserved(original.releaseObserver));

    const auto second = harken::StartPlayable(*engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, second.status);
    row = FindPlayableRow(*engine, second.instance);
    ASSERT_NE(nullptr, row);
    ASSERT_NE(original.renderHandle, row->renderHandle);
    EXPECT_EQ(static_cast<std::uint32_t>(original.renderHandle),
              static_cast<std::uint32_t>(row->renderHandle));
    harken::EngineTimelineVoiceInstallIdentity current{};
    EXPECT_FALSE(engine->CaptureTimelineVoiceInstallIdentity(original.renderHandle, &current));
    EXPECT_FALSE(engine->ClearTimelineVoiceInstallIdentity(original.renderHandle));
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(row->renderHandle, &current));
    EXPECT_GT(current.releaseObserver.targetSequence, original.releaseObserver.targetSequence);
    EXPECT_FALSE(engine->voices.ReleaseObserved(current.releaseObserver));
    ASSERT_TRUE(PumpUntilAudible(*engine));
    harken::detail::VoicePoolReleaseTestAccess::Quarantine(engine->voices, engine->notifications);
    EXPECT_EQ(nullptr, engine->voices.Resolve(current.renderHandle));
    EXPECT_FALSE(engine->voices.ReleaseObserved(current.releaseObserver));
    harken::EngineTimelineVoiceInstallIdentity quarantined{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(current.renderHandle, &quarantined));
    EXPECT_EQ(current.releaseObserver.targetSequence, quarantined.releaseObserver.targetSequence);
    EXPECT_EQ(current.onsetFrame, quarantined.onsetFrame);
    EXPECT_EQ(current.startArm.generation, quarantined.startArm.generation);
    EXPECT_FALSE(engine->voices.HasFreeSlot());
}

TEST(PlayableStart, QueueSelectionPublishesInitialAndAdoptedSuccessorOnce) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(3, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const std::vector<float> first(96, 0.25f), second(512, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Once, false,
        harken::AuthoredCompletionClassV1::FiniteMediaCandidate,
        harken::SignalOnlyPolicyV1::StopQueue, harken::QueueSpliceV1::Butt);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.playbackRequest = engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, VN_MONITOR_OPERATION_PLAY_PREVIEW);
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    auto records = harkentest::monitor::ReadIdentityEvents(capture);
    std::vector<harkentest::monitor::IdentityRecord> selected, advances;
    const auto collect = [&](const auto& rows) {
        for (const auto& row : rows) {
            if (row.fact.factKind == VN_MONITOR_FACT_SELECTION_COMMITTED) selected.push_back(row);
            if (row.fact.factKind == VN_MONITOR_FACT_QUEUE_ADVANCED) advances.push_back(row);
        }
    };
    collect(records);
    ASSERT_EQ(1u, selected.size());
    EXPECT_EQ(kSound, selected[0].header.stableId);
    EXPECT_EQ(request.playbackRequest.key.sequence, selected[0].fact.selectionRequest.sequence);
    for (unsigned block = 0; block < 96; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        collect(harkentest::monitor::ReadIdentityEvents(capture));
    }
    ASSERT_EQ(2u, selected.size());
    EXPECT_EQ(kSecondSound, selected[1].header.stableId);
    EXPECT_NE(selected[0].fact.logicalVoice, selected[1].fact.logicalVoice);
    EXPECT_EQ(started.instance, selected[1].fact.root);
    EXPECT_EQ(request.playbackRequest.key.sequence, selected[1].fact.playbackRequest.sequence);
    EXPECT_FALSE(harken::monitor::FactHas(selected[1].fact, VN_MONITOR_FACT_FIELD_SELECTION_REQUEST));
    ASSERT_EQ(1u, advances.size());
    EXPECT_EQ(started.instance, advances[0].fact.root);
    EXPECT_EQ(request.playbackRequest.key.sequence, advances[0].fact.playbackRequest.sequence);
    EXPECT_FALSE(harken::monitor::FactHas(advances[0].fact, VN_MONITOR_FACT_FIELD_CONTROL_REQUEST));
    EXPECT_FALSE(harken::monitor::FactHas(advances[0].fact, VN_MONITOR_FACT_FIELD_REASON));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
}

TEST(PlayableStart, TimelineInstallIdentityClearsPrivateVoiceOnCommitRollback) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(1, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    PlayableWorldImage image(engine->registry.Lookup(kSound).contentRevision,
                             harken::ContainerModeV1::Random);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    harken::PlayableStartRequest request{};
    request.root = image.SoundRoot();
    request.playbackRequest = engine->monitorRequests.Begin(
        harken::MonitorRequestOrigin::StudioPreview, VN_MONITOR_OPERATION_PLAY_PREVIEW);
    const auto capture = harkentest::monitor::OpenIdentityEvents();
    const auto published = engine->commands.PublishedHead();
    engine->forceTimelineVoiceCommitRollbackForTest = true;
    const auto refused = harken::StartPlayable(*engine, request);
    EXPECT_NE(harken::PlayableStartStatus::Accepted, refused.status);
    EXPECT_FALSE(engine->forceTimelineVoiceCommitRollbackForTest);
    EXPECT_EQ(published, engine->commands.PublishedHead());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineVoiceInstallIdentities[0].renderHandle);
    // The fault closes Runtime admission, but the released ledger slot is reusable.
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    VnVoiceHandle reused = 0;
    std::uint32_t reusedSlot = 0;
    ASSERT_TRUE(engine->ledger.Acquire(&reused, &reusedSlot));
    const auto failedRows = harkentest::monitor::ReadIdentityEvents(capture);
    std::vector<harkentest::monitor::IdentityRecord> voices;
    for (const auto& row : failedRows)
        if (row.fact.subjectNamespace == VN_MONITOR_SUBJECT_LOGICAL_VOICE) voices.push_back(row);
    ASSERT_EQ(2u, voices.size());
    EXPECT_EQ(VN_MONITOR_FACT_VOICE_LIVE, voices[0].fact.factKind);
    EXPECT_EQ(VN_MONITOR_FACT_VOICE_ENDED, voices[1].fact.factKind);
    EXPECT_FALSE(harken::monitor::FactHas(voices[1].fact, VN_MONITOR_FACT_FIELD_REASON));
    EXPECT_EQ(voices[0].header.instanceHandle, voices[1].header.instanceHandle);
    EXPECT_EQ(voices[0].header.instanceGeneration, voices[1].header.instanceGeneration);
    EXPECT_EQ(voices[0].fact.root, voices[1].fact.root);
    for (const auto& row : voices) {
        EXPECT_EQ(kSound, row.header.stableId);
        EXPECT_EQ(request.playbackRequest.key.sequence, row.fact.playbackRequest.sequence);
        EXPECT_FALSE(harken::monitor::FactHas(row.fact, VN_MONITOR_FACT_FIELD_TERMINAL_KIND));
    }
    EXPECT_EQ(static_cast<std::uint32_t>(voices[0].header.instanceHandle), reusedSlot);
    EXPECT_NE(voices[0].header.instanceHandle, reused);
    engine->ledger.Release(reusedSlot);
    EXPECT_EQ(VN_OK, Vn_MonitorCloseSession(capture));
}

TEST(PlayableStart, LegacyPlayUsesOnlyTheSoundRegistryAtATypedContainerId) {
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());

    PlayableWorldImage image(media.contentRevision,
                             harken::ContainerModeV1::Random);
    image.properties[1].stableId = harkentest::ObjectId(kSound);
    image.properties[1].programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(image.properties[1]);
    image.occurrence.parentStableId = harkentest::ObjectId(kSound);
    image.occurrence.parentProgramSemanticFingerprint =
        image.properties[1].programSemanticFingerprint;
    image.occurrence.occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrence);
    image.container.containerStableId = harkentest::ObjectId(kSound);
    image.container.programSemanticFingerprint =
        image.properties[1].programSemanticFingerprint;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);

    ASSERT_EQ(Vn_UnregisterPCM(kSound), VN_OK);
    const std::uint64_t commandHead = engine->commands.PublishedHead();
    const std::uint32_t freeInstances = engine->playableInstances.FreeCount();
    const std::uint32_t freeDeltas = engine->selectionMemory.FreeDeltaCount();
    VnPlayDesc play = harkentest::MakePlayDesc(kSound);
    VnVoiceHandle voice = 0;
    EXPECT_EQ(harkentest::PlayRaw(&play, &voice), VN_UNKNOWN_ID);
    EXPECT_EQ(voice, 0u);
    EXPECT_EQ(engine->commands.PublishedHead(), commandHead);
    EXPECT_EQ(engine->playableInstances.FreeCount(), freeInstances);
    EXPECT_EQ(engine->selectionMemory.FreeDeltaCount(), freeDeltas);

    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    ASSERT_EQ(harkentest::PlayRaw(&play, &voice), VN_OK);
    EXPECT_NE(voice, 0u);
    EXPECT_EQ(engine->playableInstances.FreeCount(), freeInstances);
    EXPECT_EQ(engine->selectionMemory.FreeDeltaCount(), freeDeltas);
    VnSnapshot snapshot{};
    snapshot.structSize = sizeof(snapshot);
    ASSERT_EQ(Vn_CaptureSnapshot(&snapshot), VN_OK);
    EXPECT_EQ(snapshot.containerHighWater, 0u);
    EXPECT_EQ(snapshot.containerChildHighWater, 0u);
    EXPECT_EQ(snapshot.containerCursorHighWater, 0u);
    EXPECT_EQ(snapshot.containerResolutionFailCount, 0u);
    EXPECT_EQ(snapshot.noContainerCount, 0u);
}

TEST(PlayableStart, QueryTracksPreparingActiveAndExactRootIdentity) {
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(session.InitResult(), VN_OK);
    harken::Engine* engine = session.Engine();
    ASSERT_NE(engine, nullptr);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(Vn_RegisterPCM(kSound, &pcm), VN_OK);
    const harken::PCMView media = engine->registry.Lookup(kSound);
    ASSERT_TRUE(media.Valid());
    PlayableWorldImage image(media.contentRevision,
                             harken::ContainerModeV1::Random);
    ASSERT_EQ(harken::InstallContainerWorldV1(*engine, image.world).status,
              harken::WorldInstallStatus::Ok);

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    request.callerSeed = 91;
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, request);
    ASSERT_EQ(started.status, harken::PlayableStartStatus::Accepted);

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::QueryPlayable(*engine, started.instance, &state),
              harken::PlayableControlStatus::Ok);
    EXPECT_EQ(state.kind, harken::PlayableKindV1::Container);
    EXPECT_EQ(state.lifecycle, harken::PlayableControlLifecycle::Preparing);
    EXPECT_EQ(state.reason, harken::PlayableControlReason::None);
    EXPECT_EQ(state.stableId, kContainer);
    EXPECT_EQ(state.worldGeneration,
              engine->variables.CurrentWorldGeneration());
    EXPECT_EQ(state.acceptedLogicTicket, started.ticket);
    EXPECT_EQ(state.lastAppliedBlockSequence, 0u);
    EXPECT_EQ(state.childLiveCount, 0u);
    EXPECT_EQ(state.childAudibleRetiringCount, 0u);
    EXPECT_EQ(state.pendingFutureCount, 1u);

    bool active = false;
    for (std::uint32_t block = 0; block < 16 && !active; ++block) {
        ASSERT_EQ(Vn_Update(), VN_OK);
        engine->nullBackend.Pump(1);
        ASSERT_EQ(Vn_Update(), VN_OK);
        ASSERT_EQ(harken::QueryPlayable(*engine, started.instance, &state),
                  harken::PlayableControlStatus::Ok);
        active = state.lifecycle == harken::PlayableControlLifecycle::Active;
    }
    ASSERT_TRUE(active);
    EXPECT_EQ(state.reason, harken::PlayableControlReason::None);
    EXPECT_NE(state.lastAppliedBlockSequence, 0u);
    EXPECT_EQ(state.childLiveCount, 1u);
    EXPECT_EQ(state.childAudibleRetiringCount, 0u);
    EXPECT_EQ(state.pendingFutureCount, 0u);
}

TEST(PlayableStart,
     VariableControlQueryCountsEachInitialStartOccurrenceExactly) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643515545525931)).status);
    VariableControlMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.cells[1].lower = 0.0f;
    image.cells[1].upper = 4.0f;
    image.container.maxActiveRows = 2;

    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(2u, row->variableControlContinuousMemberCount);

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(0u, state.childLiveCount);
    EXPECT_EQ(0u, state.childAudibleRetiringCount);
    EXPECT_EQ(2u, state.pendingFutureCount);

    const std::size_t base = row->scheduleStorageBase +
        row->variableControlContinuousMemberOffset;
    const auto startFrame = row->startFrame;
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_EQ(VN_OK, Vn_Update());
    for (std::uint32_t index = 0; index < 2; ++index) {
        std::size_t slot = 0;
        ASSERT_TRUE(engine->ResolvePlayableMemberSlot(base + index, &slot));
        harken::TimelineArmObservation observed{};
        ASSERT_TRUE(engine->timelineArms.Observe(engine->ReadPlayableMember(slot).arm, &observed));
        EXPECT_EQ(startFrame / config.blockFrames + 1u, observed.startedBlockSequence);
    }

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(2u, state.childLiveCount);
    EXPECT_EQ(0u, state.childAudibleRetiringCount);
    EXPECT_EQ(0u, state.pendingFutureCount);
}

void ExpectQueryReplacementRetiresAndStops(harken::Engine& engine,
    harken::PlayableInstanceHandle root, harken::TimelineArmToken exitingArm,
    harken::TimelineArmToken enteringArm, std::uint64_t exitFrame, std::uint32_t blockFrames) {
    const auto renderFor = [](harken::TimelineArmToken arm) {
        return (static_cast<std::uint64_t>(arm.renderGeneration) << 32) | arm.renderSlot;
    };
    const auto oldRender = renderFor(exitingArm);
    const auto newRender = renderFor(enteringArm);
    const auto* exiting = engine.voices.Resolve(oldRender);
    ASSERT_NE(nullptr, exiting);
    ASSERT_NE(nullptr, engine.voices.Resolve(newRender));
    const auto sourceToken = exiting->sourceTerminalToken;
    const auto* source = engine.sourceTerminals.Resolve(sourceToken);
    ASSERT_NE(nullptr, source);
    ASSERT_EQ(oldRender, source->render);
    const auto release = source->release;
    bool terminalSeen = false;
    harken::SourceTerminalPayload terminal{};
    while (engine.mixer.BlocksRendered() <= exitFrame / blockFrames + 1u) {
        engine.nullBackend.Pump(1);
        terminalSeen = engine.sourceTerminals.Capture(sourceToken,
            engine.mixer.BlocksRendered(), &terminal) || terminalSeen;
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(terminalSeen);
    EXPECT_NE(harken::SourceTerminalKind::None, terminal.kind);
    EXPECT_GE(terminal.frame, exitFrame);
    EXPECT_TRUE(engine.voices.ReleaseObserved(release));
    EXPECT_EQ(nullptr, engine.voices.Resolve(oldRender));
    ASSERT_NE(nullptr, engine.voices.Resolve(newRender));
    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::QueryPlayable(engine, root, &state));
    EXPECT_EQ(1u, state.childLiveCount);
    EXPECT_EQ(0u, state.childAudibleRetiringCount);
    EXPECT_EQ(0u, state.pendingFutureCount);
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(engine, root, 0));
    for (std::uint32_t block = 0; block < 48; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(harken::PlayableControlStatus::StaleHandle, harken::QueryPlayable(engine, root, &state));
    EXPECT_EQ(nullptr, engine.voices.Resolve(newRender));
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine.timelineArms.LiveCount());
    EXPECT_EQ(0u, engine.decisions.LiveCount());
    EXPECT_EQ(0u, engine.armGroups.LiveCount());
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(PlayableStart,
     VariableControlQueryTracksDiscreteReplacementOccurrencesExactly) {
    VnConfig config = harkentest::MakeNullConfig(3, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);

    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Step, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harkentest::InstallDefinitionsWorld(
                  engine, &variable, 1,
                  UINT64_C(0x5643515545525932)).status);
    VariableControlDiscreteMembershipWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.SetImmediateFades(256, 192);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const std::size_t base = row->scheduleStorageBase;
    const harken::TimelineArmToken exitingArm =
        engine->ReadPlayableMember(base).arm;
    harken::TimelineArmObservation exitingInitial{};
    ASSERT_TRUE(engine->timelineArms.Observe(exitingArm, &exitingInitial));

    harken::PlayableControlState state{};
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(exitingInitial.startedBlockSequence != 0 ? 1u : 0u,
              state.childLiveCount);
    EXPECT_EQ(0u, state.childAudibleRetiringCount);
    EXPECT_EQ(exitingInitial.startedBlockSequence != 0 ? 0u : 1u,
              state.pendingFutureCount);

    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(41), 7.0f));
    bool prepared = false;
    for (std::uint32_t block = 0; block < 32 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        prepared = row->variableControlDiscreteRetargetPrepared;
        if (!prepared) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(prepared);
    const harken::TimelineArmToken enteringArm =
        row->variableControlDiscreteRetargetEnteringArm;
    ASSERT_TRUE(enteringArm.Valid());
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(exitingInitial.startedBlockSequence != 0 ? 1u : 0u,
              state.childLiveCount);
    EXPECT_EQ(0u, state.childAudibleRetiringCount);
    EXPECT_EQ(exitingInitial.startedBlockSequence != 0 ? 1u : 2u,
              state.pendingFutureCount);

    const auto targetFrame = row->variableControlDiscreteRetargetFrame;
    const auto exitFrame = row->variableControlDiscreteRetargetEndFrame;
    ASSERT_GT(exitFrame / config.blockFrames, targetFrame / config.blockFrames);
    while (engine->mixer.BlocksRendered() <= targetFrame / config.blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    harken::TimelineArmObservation entered{};
    ASSERT_TRUE(engine->timelineArms.Observe(enteringArm, &entered));
    EXPECT_EQ(targetFrame / config.blockFrames + 1u, entered.startedBlockSequence);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::QueryPlayable(*engine, started.instance, &state));
    EXPECT_EQ(2u, state.childLiveCount + state.childAudibleRetiringCount);
    EXPECT_EQ(0u, state.pendingFutureCount);

    ExpectQueryReplacementRetiresAndStops(*engine, started.instance,
        exitingArm, enteringArm, exitFrame, config.blockFrames);
}

