TEST(PlayableStart, SequenceLoopSelectionUsesActualFutureOnsetForReset) {
    auto config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(128, 0.25f), second(64, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildPlayableWorldImage image(engine.registry.Lookup(kSound).contentRevision,
        engine.registry.Lookup(kSecondSound).contentRevision, harken::ContainerModeV1::Sequence);
    image.SetContainerLoopCount(2);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    auto* row = FindPlayableRow(engine, started.instance);
    ASSERT_NE(nullptr, row);
    const auto firstLeaf = row->activeLeafInstance;
    bool firstHeard = false;
    for (std::uint32_t block = 0; block < 32 && !firstHeard; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        const auto* output = engine.nullBackend.LastBlock();
        firstHeard = std::any_of(output, output + 128,
            [](float sample) { return sample > 0.1f; });
    }
    ASSERT_TRUE(firstHeard);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(1);
    const auto nowFrame = engine.mixer.BlocksRendered() * 64;
    const auto expectedFrame = std::max(nowFrame +
        std::max<std::uint32_t>(1, engine.timelinePool.PublishLeadQuanta()) * 64,
        engine.timelinePool.PublishCutoffFrame());
    harken::SelectionMemoryKeyV1 key{};
    key.world = row->Invocation().worldGeneration;
    key.containerStableId = image.container.containerStableId;
    key.programSemanticFingerprint = image.container.programSemanticFingerprint;
    key.memoryScope = image.container.memoryScope;
    key.emitterSlot = UINT32_MAX;
    harken::LogicCommitSequence resetTicket = 0;
    ASSERT_EQ(harken::LogicCommitCoordinator::IssueStatus::Issued,
        engine.logicCommits.TryIssue(&resetTicket));
    harken::PreparedSelectionResetV1 reset;
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok,
        engine.selectionMemory.PrepareReset(key, resetTicket, 0, &reset, expectedFrame));
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok,
        engine.selectionMemory.CommitPreparedReset(&reset, resetTicket));
    EXPECT_EQ(0u, engine.selectionMemory.Snapshot(key).resetEpoch);
    ASSERT_EQ(VN_OK, Vn_Update());
    row = FindPlayableRow(engine, started.instance);
    ASSERT_NE(nullptr, row);
    ASSERT_NE(firstLeaf, row->activeLeafInstance);
    EXPECT_EQ(kSound, row->leaf.stableId);
    EXPECT_EQ(expectedFrame, row->startFrame);
    EXPECT_EQ(expectedFrame, row->schedule.entryAnchorFrame);
    EXPECT_GT(row->event.logicCommitSequence, resetTicket);
    const auto successorArm = row->arm;
    bool secondHeard = false;
    for (std::uint32_t block = 0; block < 16 && !secondHeard; ++block) {
        engine.nullBackend.Pump(1);
        const auto* output = engine.nullBackend.LastBlock();
        secondHeard = std::any_of(output, output + 128,
            [](float sample) { return sample > 0.1f; });
        if (!secondHeard) ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(secondHeard);
    harken::TimelineArmObservation observation{};
    ASSERT_TRUE(engine.timelineArms.Observe(successorArm, &observation));
    EXPECT_EQ(expectedFrame / 64 + 1, observation.startedBlockSequence);
    ASSERT_TRUE(StopUntilStale(engine, started.instance, true));
}

TEST(PlayableStart, SequenceLoopMarkerReselectsAfterResetBeforeBoundary) {
    auto config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(128, 0.25f);
    std::vector<float> second(64, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));

    SequenceQueueCompositeTrackWorldImage image(
        engine.registry.Lookup(kSound).contentRevision,
        engine.registry.Lookup(kSecondSound).contentRevision);
    ConfigureSequenceLoopSoundThenZeroWorkTrack(image);
    const std::uint32_t selectionFreeBaseline =
        engine.selectionMemory.FreeDeltaCount();
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);

    bool firstHeard = false;
    for (std::uint32_t block = 0; block < 32 && !firstHeard; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        const auto* output = engine.nullBackend.LastBlock();
        firstHeard = std::any_of(output, output + 128,
            [](float sample) { return sample > 0.1f; });
    }
    ASSERT_TRUE(firstHeard);
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(1);

    auto* row = FindPlayableRow(engine, started.instance);
    ASSERT_NE(nullptr, row);
    harken::SelectionMemoryKeyV1 key{};
    key.world = row->Invocation().worldGeneration;
    key.containerStableId = image.container.containerStableId;
    key.programSemanticFingerprint = image.container.programSemanticFingerprint;
    key.memoryScope = image.container.memoryScope;
    key.emitterSlot = UINT32_MAX;
    const std::uint64_t nowFrame =
        engine.mixer.BlocksRendered() * engine.config.blockFrames;
    const std::uint64_t continuationFrame = std::max(
        nowFrame + std::max<std::uint32_t>(
                       1u, engine.timelinePool.PublishLeadQuanta()) *
                       engine.config.blockFrames,
        engine.timelinePool.PublishCutoffFrame());
    const std::uint64_t markerBoundary = continuationFrame + 960u;
    const std::uint64_t resetFrame = continuationFrame + 64u;
    ASSERT_LT(continuationFrame, resetFrame);
    ASSERT_LT(resetFrame, markerBoundary);
    harken::LogicCommitSequence resetTicket = 0;
    ASSERT_EQ(harken::LogicCommitCoordinator::IssueStatus::Issued,
              engine.logicCommits.TryIssue(&resetTicket));
    harken::PreparedSelectionResetV1 reset;
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok,
              engine.selectionMemory.PrepareReset(
                  key, resetTicket, 0, &reset, resetFrame));
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok,
              engine.selectionMemory.CommitPreparedReset(
                  &reset, resetTicket));

    ASSERT_EQ(VN_OK, Vn_Update());
    row = FindPlayableRow(engine, started.instance);
    ASSERT_NE(nullptr, row);
    EXPECT_FALSE(row->zeroWorkMarker);
    EXPECT_EQ(kSound, row->leaf.stableId);
    EXPECT_EQ(markerBoundary, row->startFrame);
    EXPECT_EQ(markerBoundary, row->schedule.entryAnchorFrame);
    EXPECT_EQ(1u, row->containerLoopIteration);
    EXPECT_GT(row->event.logicCommitSequence, resetTicket);
    harken::ContainerPlaybackRow playback{};
    ASSERT_TRUE(engine.containerPlayback.Capture(
        started.instance, &playback));
    EXPECT_EQ(1u, playback.completedSelections);

    harken::PlayableControlState state{};
    bool heardReselectedSound = false;
    bool stale = false;
    for (std::uint32_t block = 0; block < 32 && !stale; ++block) {
        engine.nullBackend.Pump(1);
        const auto* output = engine.nullBackend.LastBlock();
        heardReselectedSound = heardReselectedSound || std::any_of(
            output, output + 128,
            [](float sample) { return sample > 0.1f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto status = harken::QueryPlayable(
            engine, started.instance, &state);
        stale = status == harken::PlayableControlStatus::StaleHandle ||
                status == harken::PlayableControlStatus::InvalidHandle;
        if (!stale) {
            ASSERT_EQ(harken::PlayableControlStatus::Ok, status);
            EXPECT_NE(harken::PlayableControlReason::StartRefused,
                      state.reason);
        }
    }
    EXPECT_TRUE(heardReselectedSound);
    EXPECT_TRUE(stale);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
    EXPECT_EQ(selectionFreeBaseline,
              engine.selectionMemory.FreeDeltaCount());
}

TEST(PlayableStart, SequenceLoopSuccessorRefusalFailsWithoutRetry) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const std::uint32_t instanceBaseline =
        engine->playableInstances.LiveCount();
    const std::uint32_t containerBaseline =
        engine->containerPlayback.LiveCount();
    const std::uint32_t armBaseline = engine->timelineArms.LiveCount();
    const std::uint32_t voiceBaseline = engine->voices.ActiveCount();
    const std::uint32_t selectionFreeBaseline =
        engine->selectionMemory.FreeDeltaCount();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(64, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildPlayableWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::ContainerModeV1::Sequence);
    image.SetContainerLoopCount(2);
    harken::PlayableWorldViewV1 frozenWorld{};
    frozenWorld.generation = 1;
    frozenWorld.identity = image.world.identity;
    frozenWorld.properties = image.world.playableProperties;
    frozenWorld.propertyCount = image.world.playablePropertyCount;
    frozenWorld.occurrences = image.world.playableOccurrences;
    frozenWorld.occurrenceCount = image.world.playableOccurrenceCount;
    frozenWorld.containers = image.world.containers;
    frozenWorld.containerCount = image.world.containerCount;
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const harken::PlayableStartResult started =
        harken::StartPlayable(*engine, frozenWorld, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const harken::EnginePlayableServiceRow* row =
        FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, row);
    harken::ContainerPlaybackRow initialPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(started.instance, &initialPlayback));
    const harken::TimelineArmToken firstArm = row->arm;
    const harken::PlayableInstanceHandle firstLeaf = row->activeLeafInstance;
    const std::uint64_t firstFrame = row->startFrame;
    const std::uint32_t completedBefore = initialPlayback.completedSelections;
    const std::uint32_t iterationBefore = row->containerLoopIteration;
    ASSERT_TRUE(firstArm.Valid());
    ASSERT_NE(0u, firstLeaf);

    engine->timelinePhysicalAdmissionFault =
        harken::TimelinePhysicalAdmissionFault::DirectVirtual;
    bool refusalObserved = false;
    harken::PlayableControlState state{};
    for (std::uint32_t block = 0; block < 64 && !refusalObserved; ++block) {
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        refusalObserved =
            harken::QueryPlayable(*engine, started.instance, &state) ==
                harken::PlayableControlStatus::Ok &&
            state.lifecycle ==
                harken::PlayableControlLifecycle::FailingSourceActive &&
            state.reason == harken::PlayableControlReason::StartRefused;
    }
    ASSERT_TRUE(refusalObserved);
    row = FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, row);
    EXPECT_EQ(firstArm.slot, row->arm.slot);
    EXPECT_EQ(firstArm.generation, row->arm.generation);
    EXPECT_EQ(firstArm.renderSlot, row->arm.renderSlot);
    EXPECT_EQ(firstArm.renderGeneration, row->arm.renderGeneration);
    EXPECT_EQ(firstLeaf, row->activeLeafInstance);
    EXPECT_EQ(firstFrame, row->startFrame);
    EXPECT_EQ(iterationBefore, row->containerLoopIteration);
    EXPECT_EQ(0u, engine->playableInstances.NextSibling(firstLeaf));
    harken::ContainerPlaybackRow refusedParent{};
    ASSERT_TRUE(engine->containerPlayback.Capture(
        started.instance, &refusedParent));
    EXPECT_EQ(0u, refusedParent.activeChild);
    EXPECT_EQ(completedBefore + 1u, refusedParent.completedSelections);

    engine->timelinePhysicalAdmissionFault =
        harken::TimelinePhysicalAdmissionFault::None;
    bool stale = false;
    bool unexpectedSuccessor = false;
    for (std::uint32_t block = 0; block < 96 && !stale; ++block) {
        if (engine->playableInstances.Classify(firstLeaf).live) {
            unexpectedSuccessor = unexpectedSuccessor ||
                engine->playableInstances.NextSibling(firstLeaf) != 0u;
        }
        ASSERT_TRUE(PumpBlocks(*engine, 1));
        const harken::PlayableControlStatus query =
            harken::QueryPlayable(*engine, started.instance, &state);
        if (query == harken::PlayableControlStatus::Ok) {
            EXPECT_NE(harken::PlayableControlLifecycle::Active,
                      state.lifecycle);
            EXPECT_EQ(harken::PlayableControlReason::StartRefused,
                      state.reason);
        }
        stale = query == harken::PlayableControlStatus::StaleHandle ||
            query == harken::PlayableControlStatus::InvalidHandle;
    }
    EXPECT_FALSE(unexpectedSuccessor);
    EXPECT_TRUE(stale);
    ASSERT_TRUE(PumpBlocks(*engine, 8));
    EXPECT_EQ(instanceBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

void ConfigureOrdinaryCompositeLoop(
    SequenceQueueCompositeTrackWorldImage& image, std::uint32_t loopCount) {
    image.container.mode = harken::ContainerModeV1::Sequence;
    image.container.childCount = 1;
    image.world.identity.capabilityMask =
        harken::kWorldCapabilityPlayableProperties | harken::kWorldCapabilitySequence;
    const auto loopIndex = static_cast<std::uint32_t>(
        harken::playableproperties::PlayablePropertyIdV1::LoopCount) - 1u;
    image.properties[3].payload.presentMask |= UINT64_C(1) << loopIndex;
    image.properties[3].payload.values[loopIndex].bits = loopCount;
    image.properties[3].programSemanticFingerprint =
        harken::ComputePlayablePropertyFingerprintV1(image.properties[3]);
    image.container.programSemanticFingerprint = image.properties[3].programSemanticFingerprint;
    for (std::uint32_t index = 0; index < 2; ++index) {
        image.occurrences[index].parentProgramSemanticFingerprint = image.container.programSemanticFingerprint;
        image.occurrences[index].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[index]);
    }
}

void ExpectSequenceLoopPostFailureRetention(bool composite, bool stopWhileRetained = false) {
    auto config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(64, 0.25f), second(64, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildPlayableWorldImage image(engine.registry.Lookup(kSound).contentRevision,
        engine.registry.Lookup(kSecondSound).contentRevision, harken::ContainerModeV1::Sequence);
    image.SetContainerLoopCount(2);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    SequenceQueueCompositeTrackWorldImage compositeImage(
        engine.registry.Lookup(kSound).contentRevision,
        engine.registry.Lookup(kSecondSound).contentRevision);
    ConfigureOrdinaryCompositeLoop(compositeImage, 2);
    harken::PlayableStartRequest request{};
    request.root = composite ? compositeImage.Root() : image.Root();
    const auto started = composite
        ? harken::StartPlayable(engine, compositeImage.world, request)
        : harken::StartPlayable(engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    engine.forceContainerLoopPostFailureForTest = true;
    engine.forceActionTimelineVoiceOwnerRollbackFailureForTest = !composite;
    engine.forceTimelineVoiceCommitRollbackUnbindFailureForTest = composite;
    bool refusalObserved = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        const auto commandHead = engine.commands.PublishedHead();
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine.forceContainerLoopPostFailureForTest) {
            refusalObserved = true;
            EXPECT_FALSE(engine.forceActionTimelineVoiceOwnerRollbackFailureForTest);
            EXPECT_FALSE(engine.forceTimelineVoiceCommitRollbackUnbindFailureForTest);
            EXPECT_EQ(commandHead, engine.commands.PublishedHead());
            const auto retained = std::find_if(engine.actionPlayScratch.begin(),
                engine.actionPlayScratch.end(), [](const auto& scratch) {
                    return scratch.continuationExecution && scratch.storage.phase ==
                        harken::EngineFrontierAttemptPhase::CancelPending;
                });
            ASSERT_NE(engine.actionPlayScratch.end(), retained);
            EXPECT_TRUE(retained->playableTreeExecutor.Committed());
            EXPECT_FALSE(retained->storage.ownerLedger.Empty());
            const auto originalService = retained->continuationService;
            const auto originalPartition = retained->continuationPartition;
            ASSERT_TRUE(originalService.Valid());
            EXPECT_NE(nullptr, engine.ResolvePlayableService(originalService));
            EXPECT_TRUE(engine.playablePartitions.Owns(originalPartition, originalService.token));
            EXPECT_NE(0u, retained->continuationOrder.executeFrame);
            EXPECT_EQ(engine.timelinePool.Epoch(), retained->continuationTransportEpoch);
            if (composite) {
                EXPECT_GT(engine.timelineOccurrences.OccupiedCount(), 0u);
                EXPECT_TRUE(retained->queueCurrentCompositeOwner.Valid());
                ASSERT_NE(nullptr, retained->frontierProgramBank);
                EXPECT_TRUE(retained->frontierProgramBank->occupied);
                EXPECT_FALSE(retained->frontierProgramBank->published);
                EXPECT_EQ(2u, retained->frontierProgramBank->programCount);
            }
            const auto generation = retained->storage.generation;
            if (stopWhileRetained) {
                ASSERT_EQ(harken::PlayableControlStatus::Ok,
                    harken::StopPlayable(engine, started.instance, 0));
                for (std::uint32_t block = 0; block < 3; ++block) {
                    engine.forceActionTimelineVoiceOwnerRollbackFailureForTest = true;
                    ASSERT_EQ(VN_OK, Vn_Update());
                    EXPECT_EQ(generation, retained->storage.generation);
                    EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending,
                        retained->storage.phase);
                    EXPECT_TRUE(engine.playablePartitions.Owns(originalPartition, originalService.token));
                    EXPECT_NE(nullptr, engine.ResolvePlayableService(originalService));
                    engine.nullBackend.Pump(1);
                }
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(generation, retained->storage.generation);
            EXPECT_EQ(harken::EngineFrontierAttemptPhase::Free, retained->storage.phase);
            EXPECT_TRUE(retained->storage.ownerLedger.Empty());
            EXPECT_EQ(nullptr, retained->frontierProgramBank);
            break;
        }
        engine.nullBackend.Pump(1);
    }
    EXPECT_TRUE(refusalObserved);
    ASSERT_TRUE(StopUntilStale(engine, started.instance, true));
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
}

TEST(PlayableStart, SequenceLoopPostFailureRetainsAttemptUntilVoiceRollbackSucceeds) {
    ExpectSequenceLoopPostFailureRetention(false);
}

