TEST(PlayableStart,
     RandomQueueSpecifiedTwoPlaysFourSoundsOnEveryStart) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first = MakeOnsetPcm(0.25f);
    std::vector<float> second = MakeOnsetPcm(-0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    TwoChildRandomQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision, 2);
    const auto install = PlayableWorldInstall(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, install).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    int wrapSameChildAttempts = 0;
    constexpr int kAttempts = 16;
    for (int attempt = 0; attempt < kAttempts; ++attempt) {
        const std::string before = OccupancyDump(*engine);
        EXPECT_TRUE(PlayableRowsFree(*engine))
            << "attempt=" << attempt << before;
        EXPECT_FALSE(engine->runtimeRecreateRequired)
            << "attempt=" << attempt << before;
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        request.emitter = emitter;
        request.callerSeed = 77;
        const harken::PlayableStartResult started =
            harken::StartPlayable(*engine, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status)
            << "attempt=" << attempt << before
            << " recreate=" << engine->runtimeRecreateRequired;
        const QueueOnsetPlayback played = PlayQueueUntilStale(
            *engine, started.instance, &image.container, 4, false);
        if (played.wrapSameChild) {
            ++wrapSameChildAttempts;
        }
        EXPECT_EQ(4u, played.heard.size())
            << "attempt=" << attempt
            << " heard=" << HeardMarks(played.heard)
            << " expected=" << HeardMarks(played.expected)
            << " wrapSameChild=" << played.wrapSameChild
            << " recreate=" << engine->runtimeRecreateRequired
            << " rowsFree=" << PlayableRowsFree(*engine)
            << " before" << before
            << " atStart{" << played.atStart << "}"
            << " atWrap{" << played.atWrap << "}"
            << " atEnd{" << played.atEnd << "}";
        EXPECT_EQ(played.expected, played.heard)
            << "attempt=" << attempt
            << " heard=" << HeardMarks(played.heard)
            << " expected=" << HeardMarks(played.expected)
            << " wrapSameChild=" << played.wrapSameChild
            << " atStart{" << played.atStart << "}"
            << " atEnd{" << played.atEnd << "}";
        ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance))
            << "attempt=" << attempt << OccupancyDump(*engine);
        EXPECT_TRUE(PlayableRowsFree(*engine))
            << "attempt=" << attempt << OccupancyDump(*engine);
    }
    ::testing::Test::RecordProperty(
        "wrapSameChildAttempts", wrapSameChildAttempts);
    ::testing::Test::RecordProperty("startAttempts", kAttempts);
    EXPECT_GE(wrapSameChildAttempts, 3)
        << "specified two must exercise at least three cross-cycle "
           "same-child selections across "
        << kAttempts << " starts";
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PlayableStart,
     SequenceQueueSpecifiedTwoPlaysFourSoundsOnEveryStart) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    SequenceQueueWorldImage image(
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        harken::QueueCycleV1::Loop);
    image.container.queueCycleCount = 2;
    const auto install = PlayableWorldInstall(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, install).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    for (int attempt = 0; attempt < 4; ++attempt) {
        const std::string before = OccupancyDump(*engine);
        EXPECT_TRUE(PlayableRowsFree(*engine))
            << "attempt=" << attempt << before;
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        request.emitter = emitter;
        request.callerSeed = 77;
        const harken::PlayableStartResult started =
            harken::StartPlayable(*engine, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status)
            << "attempt=" << attempt << before;
        std::vector<int> heard;
        for (std::uint32_t block = 0; block < 256; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const float* output = engine->nullBackend.LastBlock();
            int sign = 0;
            for (std::uint32_t frame = 0; frame < engine->config.blockFrames;
                 ++frame) {
                const float value = output[2u * frame];
                if (value > 0.1f) sign = 1;
                if (value < -0.1f) sign = -1;
            }
            if (sign != 0 && (heard.empty() || heard.back() != sign)) {
                heard.push_back(sign);
            }
            harken::PlayableControlState state{};
            const harken::PlayableControlStatus query =
                harken::QueryPlayable(*engine, started.instance, &state);
            if ((query == harken::PlayableControlStatus::StaleHandle ||
                 query == harken::PlayableControlStatus::InvalidHandle) &&
                heard.size() >= 4) {
                break;
            }
        }
        EXPECT_EQ(4u, heard.size())
            << "attempt=" << attempt
            << " heard=" << heard.size()
            << OccupancyDump(*engine);
        harken::PlayableControlState state{};
        harken::PlayableControlStatus query =
            harken::QueryPlayable(*engine, started.instance, &state);
        for (std::uint32_t block = 0; block < 64; ++block) {
            if (query == harken::PlayableControlStatus::StaleHandle ||
                query == harken::PlayableControlStatus::InvalidHandle) {
                break;
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            query = harken::QueryPlayable(*engine, started.instance, &state);
        }
        ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance));
        EXPECT_TRUE(PlayableRowsFree(*engine))
            << "attempt=" << attempt << OccupancyDump(*engine);
    }
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

void ExpectRandomQueueOnceTwoSounds(
    harken::Engine& engine, TwoChildRandomQueueWorldImage& image,
    VnEmitterHandle emitter, bool samePcm, int attempts) {
    for (int attempt = 0; attempt < attempts; ++attempt) {
        const std::string before = OccupancyDump(engine);
        EXPECT_TRUE(PlayableRowsFree(engine)) << "attempt=" << attempt << before;
        EXPECT_FALSE(engine.runtimeRecreateRequired)
            << "attempt=" << attempt << before;
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        request.emitter = emitter;
        request.callerSeed = 77;
        const harken::PlayableStartResult started =
            harken::StartPlayable(engine, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status)
            << "attempt=" << attempt << before
            << " recreate=" << engine.runtimeRecreateRequired;
        std::vector<int> heard;
        std::string atFirst;
        bool inCycleSameKey = false;
        for (std::uint32_t block = 0; block < 256; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine.nullBackend.Pump(1);
            PushHeardSign(heard, LastBlockSign(engine));
            if (heard.size() == 1 && atFirst.empty()) {
                atFirst = WrapProbeDump(
                    engine, started.instance, image.container, heard);
                const harken::EnginePlayableServiceRow* row =
                    FindPlayableRow(engine, started.instance);
                inCycleSameKey = row != nullptr && row->queueSameProgramKey;
            }
            harken::PlayableControlState state{};
            const harken::PlayableControlStatus query =
                harken::QueryPlayable(engine, started.instance, &state);
            if ((query == harken::PlayableControlStatus::StaleHandle ||
                 query == harken::PlayableControlStatus::InvalidHandle) &&
                (samePcm ? heard.size() >= 1 : heard.size() >= 2)) {
                break;
            }
        }
        const std::string atEnd =
            WrapProbeDump(engine, started.instance, image.container, heard);
        if (samePcm) {
            EXPECT_TRUE(inCycleSameKey)
                << "attempt=" << attempt
                << " same-PCM Off must keep in-cycle same-key continuation"
                << " atFirst{" << atFirst << "} atEnd{" << atEnd << "}";
            EXPECT_EQ(1u, heard.size())
                << "attempt=" << attempt
                << " heard=" << heard.size()
                << " signs=" << HeardSigns(heard)
                << " atFirst{" << atFirst << "} atEnd{" << atEnd << "}";
        } else {
            EXPECT_EQ(2u, heard.size())
                << "attempt=" << attempt
                << " heard=" << heard.size()
                << " signs=" << HeardSigns(heard)
                << " atFirst{" << atFirst << "} atEnd{" << atEnd << "}";
        }
        ASSERT_TRUE(WaitUntilReclaimed(engine, started.instance))
            << "attempt=" << attempt << OccupancyDump(engine)
            << " atEnd{" << atEnd << "}";
        EXPECT_FALSE(engine.runtimeRecreateRequired)
            << "attempt=" << attempt << OccupancyDump(engine);
        EXPECT_TRUE(PlayableRowsFree(engine))
            << "attempt=" << attempt << OccupancyDump(engine);
    }
}

