struct IdentitySwitchHeard {
    std::vector<int> heard;
    bool wrapSameChild = false;
    std::string atSecond;
    std::string atEnd;
};

IdentitySwitchHeard PlayIdentityUntilStale(
    harken::Engine& engine, harken::PlayableInstanceHandle instance,
    const harken::ContainerProgramViewV3* randomProgram,
    std::uint32_t minHeard) {
    IdentitySwitchHeard result;
    for (std::uint32_t block = 0; block < 256; ++block) {
        EXPECT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        PushHeardSign(result.heard, LastBlockSign(engine));
        if (result.heard.size() == 2 && result.atSecond.empty()) {
            if (randomProgram != nullptr) {
                result.wrapSameChild = RandomQueueWrapsSameChild(
                    engine, instance, *randomProgram);
            }
            result.atSecond =
                randomProgram == nullptr
                    ? OccupancyDump(engine)
                    : WrapProbeDump(
                          engine, instance, *randomProgram, result.heard);
        }
        harken::PlayableControlState state{};
        const harken::PlayableControlStatus query =
            harken::QueryPlayable(engine, instance, &state);
        const std::uint32_t needed =
            result.wrapSameChild ? std::min(minHeard, 3u) : minHeard;
        if ((query == harken::PlayableControlStatus::StaleHandle ||
             query == harken::PlayableControlStatus::InvalidHandle) &&
            result.heard.size() >= needed) {
            break;
        }
    }
    result.atEnd =
        randomProgram == nullptr
            ? OccupancyDump(engine)
            : WrapProbeDump(engine, instance, *randomProgram, result.heard);
    return result;
}

harken::PlayableStartResult StartIdentityContainer(VnEmitterHandle emitter) {
    return harken::StartCurrentPlayableByIdentity(
        harken::PlayableKindV1::Container, kContainer, emitter);
}

TEST(PlayableStart,
     SequenceToRandomQueueSpecifiedTwoKeepsFourSounds) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first = MakeOnsetPcm(0.25f);
    std::vector<float> second = MakeOnsetPcm(-0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const std::array<std::uint64_t, 3> revisions = {
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        0};
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    int wrapSameChildAttempts = 0;
    constexpr int kAttempts = 8;

    auto playSequenceThenRandomQueue = [&](bool stopAtMid, int attempt) {
        harken::PlayableRefV1 sequenceRoot{};
        ASSERT_TRUE(InstallHandoffWorld(
            *engine, revisions, HandoffKind::Sequence, 2, &sequenceRoot));
        const harken::PlayableStartResult sequence =
            StartIdentityContainer(emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, sequence.status)
            << "attempt=" << attempt << OccupancyDump(*engine);
        std::vector<int> sequenceHeard;
        const std::uint32_t sequenceTarget = stopAtMid ? 1u : 2u;
        for (std::uint32_t block = 0; block < 256; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            PushHeardSign(sequenceHeard, LastBlockSign(*engine));
            harken::PlayableControlState state{};
            const harken::PlayableControlStatus query =
                harken::QueryPlayable(*engine, sequence.instance, &state);
            if (stopAtMid && sequenceHeard.size() >= sequenceTarget) {
                break;
            }
            if (!stopAtMid &&
                (query == harken::PlayableControlStatus::StaleHandle ||
                 query == harken::PlayableControlStatus::InvalidHandle) &&
                sequenceHeard.size() >= sequenceTarget) {
                break;
            }
        }
        ASSERT_TRUE(StopUntilStale(*engine, sequence.instance))
            << "attempt=" << attempt << OccupancyDump(*engine);
        DrainSilentBlocks(*engine, 8);

        TwoChildRandomQueueWorldImage image(
            revisions[0], revisions[1], 2);
        const auto install = PlayableWorldInstall(image.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, install).status);
        const harken::PlayableStartResult started =
            StartIdentityContainer(emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status)
            << "attempt=" << attempt << OccupancyDump(*engine);
        const QueueOnsetPlayback played = PlayQueueUntilStale(
            *engine, started.instance, &image.container, 4, false);
        if (played.wrapSameChild) {
            ++wrapSameChildAttempts;
        }
        EXPECT_EQ(4u, played.heard.size())
            << "attempt=" << attempt
            << " stopAtMid=" << stopAtMid
            << " heard=" << HeardMarks(played.heard)
            << " expected=" << HeardMarks(played.expected)
            << " wrapSameChild=" << played.wrapSameChild
            << " atStart{" << played.atStart << "}"
            << " atWrap{" << played.atWrap << "}"
            << " atEnd{" << played.atEnd << "}";
        EXPECT_EQ(played.expected, played.heard)
            << "attempt=" << attempt
            << " stopAtMid=" << stopAtMid
            << " heard=" << HeardMarks(played.heard)
            << " expected=" << HeardMarks(played.expected)
            << " wrapSameChild=" << played.wrapSameChild
            << " atStart{" << played.atStart << "}"
            << " atEnd{" << played.atEnd << "}";
        ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance));
        EXPECT_TRUE(PlayableRowsFree(*engine)) << OccupancyDump(*engine);
    };

    for (int attempt = 0; attempt < kAttempts; ++attempt) {
        playSequenceThenRandomQueue(attempt % 2 == 0, attempt);
    }
    ::testing::Test::RecordProperty(
        "handoffWrapSameChildAttempts", wrapSameChildAttempts);
    ::testing::Test::RecordProperty("handoffStartAttempts", kAttempts);
    EXPECT_GE(wrapSameChildAttempts, 2)
        << "Sequence to specified Random_Queue must exercise at least two "
           "cross-cycle same-child selections across "
        << kAttempts << " starts";
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PlayableStart,
     SequenceToSequenceQueueSpecifiedTwoKeepsFourSounds) {
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &secondPcm));
    const std::array<std::uint64_t, 3> revisions = {
        engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision,
        0};
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    auto playSequenceThenSequenceQueue = [&](bool stopAtMid) {
        harken::PlayableRefV1 sequenceRoot{};
        ASSERT_TRUE(InstallHandoffWorld(
            *engine, revisions, HandoffKind::Sequence, 2, &sequenceRoot));
        const harken::PlayableStartResult sequence =
            StartIdentityContainer(emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, sequence.status)
            << OccupancyDump(*engine);
        std::vector<int> sequenceHeard;
        const std::uint32_t sequenceTarget = stopAtMid ? 1u : 2u;
        for (std::uint32_t block = 0; block < 256; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            PushHeardSign(sequenceHeard, LastBlockSign(*engine));
            harken::PlayableControlState state{};
            const harken::PlayableControlStatus query =
                harken::QueryPlayable(*engine, sequence.instance, &state);
            if (stopAtMid && sequenceHeard.size() >= sequenceTarget) {
                break;
            }
            if (!stopAtMid &&
                (query == harken::PlayableControlStatus::StaleHandle ||
                 query == harken::PlayableControlStatus::InvalidHandle) &&
                sequenceHeard.size() >= sequenceTarget) {
                break;
            }
        }
        const int residue = sequenceHeard.empty() ? 0 : sequenceHeard.back();
        ASSERT_TRUE(StopUntilStale(*engine, sequence.instance))
            << OccupancyDump(*engine);
        DrainSilentBlocks(*engine, 8);

        harken::PlayableRefV1 queueRoot{};
        ASSERT_TRUE(InstallHandoffWorld(
            *engine, revisions, HandoffKind::SequenceQueue, 2, &queueRoot));
        const harken::PlayableStartResult started =
            StartIdentityContainer(emitter);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status)
            << OccupancyDump(*engine);
        const IdentitySwitchHeard played =
            PlayIdentityUntilStale(*engine, started.instance, nullptr, 4);
        const std::vector<int> roster = RosterHeard(played.heard, residue);
        EXPECT_EQ(4u, roster.size())
            << "stopAtMid=" << stopAtMid
            << " heard=" << HeardSigns(played.heard)
            << " roster=" << HeardSigns(roster)
            << " atEnd{" << played.atEnd << "}";
        ASSERT_TRUE(WaitUntilReclaimed(*engine, started.instance));
        EXPECT_TRUE(PlayableRowsFree(*engine)) << OccupancyDump(*engine);
    };

    playSequenceThenSequenceQueue(true);
    playSequenceThenSequenceQueue(false);
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PlayableStart, VariableControlLongChildrenAllowOverlappingTriggersPastTimelineHorizon) {
    for (unsigned variation = 0; variation < 4; ++variation) {
        const bool continuous = (variation & 1u) != 0;
        const std::int64_t offset = (variation & 2u) != 0 ? 512 : 0;
        SCOPED_TRACE(continuous);
        SCOPED_TRACE(offset);
        harkentest::EngineSession session(harkentest::MakeNullConfig(64, 256, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> samples(48000, 0.02f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
        const harken::VariableDefinitionV1 variable = {
            harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
        VariableControlWorldImage image(engine->registry.Lookup(kSound).contentRevision,
            engine->variables.CurrentWorldGeneration(), continuous, continuous);
        image.child.timingHint.kind = harken::ChildTimingHintKindV2::InlineSound;
        image.child.timingHint.payload.inlineSound.startOffset = {
            harken::AuthoredTimeDomainV1::SourceFrames, offset, 1};
        image.child.timingHint.payload.inlineSound.duration = {
            harken::AuthoredTimeDomainV1::NaturalMediaEnd, 0, 1};
        if (continuous) {
            image.container.discreteAxisCount = image.container.discreteRowCount = 0;
            image.container.discreteAxes = nullptr;
            image.container.discreteRows = nullptr;
        }
        harken::PlayableStartRequest request{};
        request.root = image.Root();
        std::array<harken::PlayableInstanceHandle, 12> instances{};
        VnVoiceHandle previousRender = 0;
        for (std::uint32_t trigger = 0; trigger < instances.size(); ++trigger) {
            SCOPED_TRACE(trigger);
            const std::uint64_t target = static_cast<std::uint64_t>(trigger) * 670 * 48 / 256;
            while (engine->mixer.BlocksRendered() < target) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
            }
            const auto result = harken::StartPlayable(*engine, image.world, request);
            ASSERT_EQ(harken::PlayableStartStatus::Accepted, result.status);
            instances[trigger] = result.instance;
            const auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
                [&](const auto& candidate) { return candidate.rootInstance == result.instance; });
            ASSERT_NE(engine->playableServices.end(), row);
            const auto render = row->renderHandle;
            std::size_t slot = 0;
            ASSERT_TRUE(engine->ResolvePlayableMemberSlot(row->scheduleStorageBase +
                (continuous ? row->variableControlContinuousMemberOffset : 0u), &slot));
            const auto expectedStart = engine->ReadPlayableMember(slot).startFrame / 256 + 1;
            const auto before = engine->mixer.BlocksRendered();
            for (unsigned block = 0; block < 12; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_GT(engine->mixer.BlocksRendered(), before);
            EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
                engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()), 0.001f);
            ASSERT_NE(nullptr, engine->voices.Resolve(render));
            EXPECT_FALSE(engine->voices.Resolve(render)->timelineGated);
            EXPECT_EQ(expectedStart, engine->ReadPlayableMember(slot).completion.sourceStartedBlockSequence);
            if (previousRender != 0) EXPECT_NE(nullptr, engine->voices.Resolve(previousRender));
            previousRender = render;
            harken::PlayableControlState state{};
            ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::QueryPlayable(*engine, result.instance, &state));
            EXPECT_EQ(harken::PlayableControlLifecycle::Active, state.lifecycle);
            EXPECT_EQ(1u, state.childLiveCount);
            EXPECT_EQ(0u, state.pendingFutureCount);
            EXPECT_FALSE(engine->runtimeRecreateRequired);
        }
        for (unsigned block = 0; block < 224; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        for (const auto instance : instances) ASSERT_TRUE(StopUntilStale(*engine, instance));
        EXPECT_EQ(0u, engine->playableInstances.LiveCount());
        EXPECT_EQ(0u, engine->timelineArms.LiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
}

TEST(PlayableStart, VariableControlTriggersNaturallyDrainBeyondAuditionLimit) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(64, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4800, 0.02f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
    VariableControlMembershipWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.children[0].stableChildOrdinal = 0;
    image.rows[0].childStableOrdinal = 0;
    image.occurrences[0].stableOccurrenceOrdinal = 0;
    image.occurrences[0].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    for (unsigned trigger = 0; trigger < 66; ++trigger) {
        SCOPED_TRACE(trigger);
        const auto started = harken::StartPlayable(*engine, image.world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        ASSERT_TRUE(PumpUntilAudible(*engine));
        for (unsigned block = 0; block < 96; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(0u, engine->voices.ActiveCount());
        ASSERT_FALSE(engine->playableInstances.Classify(started.instance).live);
        ASSERT_EQ(0u, engine->playableInstances.LiveCount());
        ASSERT_EQ(0u, engine->timelineArms.LiveCount());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 7.0f));
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(0u, engine->voices.ActiveCount());
    }
    ASSERT_EQ(harken::PlayableStartStatus::Accepted,
        harken::StartPlayable(*engine, image.world, request).status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
}

