TEST(PlayableStart, BlendChangesWeightsWithoutReplacingMembersAndThenCompletes) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(48000, 0.1f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
    VariableControlMembershipWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    image.children[0].stableChildOrdinal = 0;
    image.rows[0].childStableOrdinal = 0;
    image.occurrences[0].stableOccurrenceOrdinal = 0;
    image.occurrences[0].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    const auto root = engine->playableInstances.Classify(started.instance);
    const auto leaf = root.firstChild;
    ASSERT_NE(0u, leaf);
    const auto* service = FindPlayableRow(*engine, started.instance);
    ASSERT_NE(nullptr, service);
    ASSERT_EQ(2u, service->variableControlChildWeightCount);
    const auto pump = [&]() {
        for (unsigned block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            ASSERT_FALSE(engine->runtimeRecreateRequired);
        }
    };
    EXPECT_EQ(0u, engine->variableControlRetargetPrograms.ConstructedCount());
    ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 7.0f));
    engine->nativeBackingAllocationFailureCountdownForTest = 0;
    for (unsigned block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    engine->nativeBackingAllocationFailureCountdownForTest = -1;
    EXPECT_EQ(0u, service->variableControlRetargetMembers.capacity());
    EXPECT_FALSE(service->variableControlRetargetPrepared);
    EXPECT_FLOAT_EQ(1.0f, service->variableControlChildWeights[0].current.endWeight);
    EXPECT_FLOAT_EQ(0.0f, service->variableControlChildWeights[1].current.endWeight);
    engine->variableControlRetargetPrograms.SetCommitPageLimitForTests(0);
    ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 7.0f));
    for (unsigned block = 0; block < 4; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->variableControlRetargetPrograms.ConstructedCount());
    EXPECT_EQ(0u, service->variableControlRetargetMembers.capacity());
    EXPECT_TRUE(engine->playableInstances.Classify(leaf).live);
    EXPECT_EQ(2u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_FLOAT_EQ(1.0f, service->variableControlChildWeights[0].current.endWeight);
    EXPECT_FLOAT_EQ(0.0f, service->variableControlChildWeights[1].current.endWeight);
    engine->variableControlRetargetPrograms.SetCommitPageLimitForTests(SIZE_MAX);
    pump();
    EXPECT_FLOAT_EQ(0.0f, service->variableControlChildWeights[0].current.endWeight);
    EXPECT_FLOAT_EQ(1.0f, service->variableControlChildWeights[1].current.endWeight);
    ASSERT_TRUE(engine->playableInstances.Classify(leaf).live);
    EXPECT_EQ(leaf, engine->playableInstances.Classify(started.instance).firstChild);
    EXPECT_EQ(2u, engine->voices.ActiveCount());
    EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
        engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()), 0.001f);
    const auto controlRecords = engine->variableControlRetargetPrograms.ConstructedCount();
    EXPECT_NE(0u, controlRecords);
    engine->variableControlRetargetPrograms.SetCommitPageLimitForTests(0);
    ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 3.0f));
    pump();
    EXPECT_EQ(controlRecords, engine->variableControlRetargetPrograms.ConstructedCount());
    EXPECT_FLOAT_EQ(1.0f, service->variableControlChildWeights[0].current.endWeight);
    EXPECT_FLOAT_EQ(0.0f, service->variableControlChildWeights[1].current.endWeight);
    ASSERT_TRUE(engine->playableInstances.Classify(leaf).live);
    EXPECT_EQ(leaf, engine->playableInstances.Classify(started.instance).firstChild);
    EXPECT_EQ(2u, engine->voices.ActiveCount());
    EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
        engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()), 0.001f);
    for (unsigned block = 0; block < 220; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, VariableControlOverlappingTriggersRetireWithoutStop) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(16, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4800, 0.05f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
    VariableControlMembershipWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    for (unsigned trigger = 0; trigger < 70; ++trigger) {
        SCOPED_TRACE(trigger);
        const auto started = harken::StartPlayable(*engine, image.world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
        if (trigger == 0) ASSERT_TRUE(PumpUntilAudible(*engine));
        for (unsigned block = 0; block < 4; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        if (trigger > 1) EXPECT_GT(engine->voices.ActiveCount(), 1u);
        EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
            engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()), 0.001f);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
}

TEST(PlayableStart, VariableControlKeepsAuthoredTimelineDurationDuringSilence) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(512, 0.1f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSecondSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
    VariableControlLogicalTracksWorldImage image(engine->registry.Lookup(kSound).contentRevision,
        engine->registry.Lookup(kSecondSound).contentRevision, engine->variables.CurrentWorldGeneration());
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, image.world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto service = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) { return row.ownerInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), service);
    const auto end = service->startFrame + 96000u;
    for (unsigned block = 0; block < 200; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    while ((engine->mixer.BlocksRendered() + 1u) * 256u < end) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_TRUE(engine->playableInstances.Classify(started.instance).live);
        ASSERT_EQ(0u, engine->voices.ActiveCount());
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    for (unsigned block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

static void ExpectVariableControlNestedCompletion(harken::ContainerModeV1 outerMode,
    harken::ContainerModeV1 innerMode, bool loopingChild = false, bool checkQueueWeight = false, bool checkRefusal = false, std::uint32_t preparationAdvance = 0) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4800, 0.1f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const harken::VariableDefinitionV1 variable = {
        harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, &variable, 1).status);
    NestedSequenceWorldImage image(engine->registry.Lookup(kSound).contentRevision);
    harken::GridAxisV1 axis{0, 0, variable.variableId};
    harken::ContinuousGridCellV1 cell{};
    cell.kind = harken::ContinuousCellKindV1::Interval;
    cell.lower = 0.0f;
    cell.upper = 4.0f;
    cell.lowerInclusive = cell.upperInclusive = 1;
    harken::CurveV1 weightCurve{};
    if (checkQueueWeight) {
        weightCurve.curveLocalId = 1;
        weightCurve.curve.pointCount = 2;
        weightCurve.curve.points[0] = {0.0f, 0.0f};
        weightCurve.curve.points[1] = {8.0f, 1.0f};
        cell.upper = 8.0f;
        cell.leftCurveLocalId = 1;
    }
    std::array<harken::ContinuousGridRowViewV1, 2> grids{};
    for (unsigned index = 0; index < 2; ++index) {
        auto& program = image.containers[index];
        program.mode = index == 0 ? innerMode : outerMode;
        program.queueCycle = harken::QueueCycleV1::Once;
        auto& grid = grids[index];
        grid.stableRowOrdinal = 1;
        grid.childStableOrdinal = program.children[0].stableChildOrdinal;
        grid.cellCount = 1;
        grid.cells = &cell;
        if (program.mode == harken::ContainerModeV1::VariableControl) {
            program.memoryScope = harken::MemoryScopeV1::Emitter;
            program.continuousAxisCount = 1;
            program.continuousAxes = &axis;
            program.continuousRowCount = 1;
            program.continuousRows = &grid;
            program.evaluationPeriodFrames = 64;
            program.envelopeFrames = 128;
            program.maxActiveRows = 1;
            program.maxLiveRows = 2;
            if (checkQueueWeight) {
                program.curves = &weightCurve;
                program.curveCount = 1;
            }
        }
    }
    if (loopingChild) {
        const auto loopIndex = static_cast<std::uint32_t>(harken::playableproperties::PlayablePropertyIdV1::LoopCount) - 1u;
        image.properties[0].payload.presentMask |= UINT64_C(1) << loopIndex;
        image.properties[0].payload.values[loopIndex].bits = 0;
        image.properties[0].programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(image.properties[0]);
        image.nestedChildren[0].playable.expectedProgramSemanticFingerprint = image.properties[0].programSemanticFingerprint;
        image.occurrences[0].childPlayable = image.nestedChildren[0].playable;
        image.occurrences[0].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    }
    image.nestedChildren[0].frequencyWeight = innerMode == harken::ContainerModeV1::Random ? 1 : 0;
    image.rootChildren[0].frequencyWeight = outerMode == harken::ContainerModeV1::Random ? 1 : 0;
    if (checkQueueWeight) {
        image.containers[0].queueCycle = harken::QueueCycleV1::Loop;
        image.containers[0].queueCycleCount = 2;
    }
    harken::PlayableWorldViewV1 world{};
    world.generation = engine->variables.CurrentWorldGeneration();
    world.identity = image.world.identity;
    world.identity.capabilityMask |= harken::kWorldCapabilityVariableControl |
        harken::kWorldCapabilityVariableDefinitions | harken::kWorldCapabilitySequenceQueue |
        harken::kWorldCapabilityRandomDraw;
    world.properties = image.properties.data();
    world.propertyCount = image.properties.size();
    world.occurrences = image.occurrences.data();
    world.occurrenceCount = image.occurrences.size();
    world.containers = image.containers.data();
    world.containerCount = image.containers.size();
    if (checkQueueWeight) {
        auto install = PlayableWorldInstall(world);
        install.variables = &variable;
        install.variableCount = 1;
        install.identity.capabilityMask = harken::kWorldCapabilityPlayableProperties |
            harken::kWorldCapabilityVariableDefinitions | harken::kWorldCapabilityVariableControl |
            harken::kWorldCapabilitySequenceQueue;
        install.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(install);
        ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, install).status);
        world.generation = engine->variables.CurrentWorldGeneration();
    }
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    if (checkRefusal) {
        harken::CommandRecord filler{};
        filler.opcode = harken::kOpcodeStop;
        filler.payload.stop.handle = UINT64_MAX;
        while (engine->commands.FreeSlots() != 0) {
            ASSERT_TRUE(engine->commands.TryPush(filler));
        }
        const auto refused = harken::StartPlayable(*engine, world, request);
        ASSERT_EQ(harken::PlayableStartStatus::Backpressure, refused.status);
        ASSERT_EQ(0u, refused.instance);
        ASSERT_EQ(0u, engine->voices.ActiveCount());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    const bool checkClockAdvance = preparationAdvance != 0;
    std::pair<std::uint64_t, std::uint32_t> clockAdvance{0, preparationAdvance};
    auto& expectedStartFrame = clockAdvance.first;
    if (checkClockAdvance) {
        harken::ScheduledTransactionPool::Config pool{};
        pool.quantumFrames = engine->config.blockFrames;
        pool.publishLeadQuanta = engine->config.publishLeadQuanta;
        pool.scheduleHorizonFrames = (pool.publishLeadQuanta + 1u) * pool.quantumFrames;
        pool.maxTransactionSpanFrames = pool.scheduleHorizonFrames;
        pool.maxScheduledTransactions = engine->config.maxScheduledTransactions;
        pool.maxIngressTransactionsPerQuantum = engine->config.maxIngressTransactionsPerQuantum;
        pool.maxFrameBatchesPerQuantum = engine->config.maxFrameBatchesPerQuantum;
        pool.maxEventsPerQuantum = engine->config.maxEventsPerQuantum;
        pool.maxTransactionEvents = engine->config.maxTransactionEvents;
        pool.maxCurrentSlicesPerQuantum = engine->config.maxEventsPerQuantum;
        pool.maxPlan03GroupHeadersPerPage = engine->config.maxPlan03GroupHeadersPerPage;
        pool.maxArmsPerGroup = engine->config.maxArmsPerGroup;
        ASSERT_TRUE(engine->timelinePool.Reset(pool, 0, engine->transportEpochOwner.Current()));
        engine->selectionInputContextForTest = &clockAdvance;
        engine->selectionInputHookForTest = [](harken::Engine& current,
                const harken::SelectionPlayRequestV1&, void* context) {
            current.selectionInputHookForTest = nullptr;
            const auto quantum = current.config.blockFrames;
            const auto lead = current.timelinePool.PublishLeadQuanta();
            auto& advance = *static_cast<std::pair<std::uint64_t, std::uint32_t>*>(context);
            auto& admitted = advance.first;
            admitted = std::max(current.timelinePool.PublishCutoffFrame(),
                (current.mixer.BlocksRendered() + lead) * quantum);
            ASSERT_LT(admitted, current.timelinePool.WindowEndFrame());
            current.nullBackend.Pump(advance.second);
            if (advance.second == 1) ASSERT_LT(current.mixer.BlocksRendered() * quantum, admitted);
            else ASSERT_GE(current.mixer.BlocksRendered() * quantum, admitted);
            ASSERT_GE((current.mixer.BlocksRendered() + lead) * quantum,
                current.timelinePool.WindowEndFrame());
        };
    }
    const auto started = harken::StartPlayable(*engine, world, request);
    engine->selectionInputHookForTest = nullptr;
    engine->selectionInputContextForTest = nullptr;
    if (preparationAdvance > 1) {
        ASSERT_NE(0u, expectedStartFrame);
        ASSERT_TRUE(started.status == harken::PlayableStartStatus::Accepted ||
            started.status == harken::PlayableStartStatus::Backpressure);
        for (unsigned block = 0; block < 96; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            for (unsigned sample = 0; sample < engine->config.blockFrames * engine->nullBackend.Channels(); ++sample)
                EXPECT_FLOAT_EQ(0.0f, output[sample]);
        }
        EXPECT_EQ(0u, engine->playableInstances.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_EQ(0u, engine->timelineArms.LiveCount());
        EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        return;
    }

    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    if (checkClockAdvance) {
        ASSERT_NE(0u, expectedStartFrame);
        const auto* row = FindPlayableRow(*engine, started.instance);
        ASSERT_NE(nullptr, row);
        EXPECT_EQ(expectedStartFrame, row->startFrame);
        EXPECT_EQ(expectedStartFrame / engine->config.blockFrames + 1u,
            engine->mixer.BlocksRendered());
        engine->selectionInputContextForTest = nullptr;
    }

    if (checkQueueWeight) {
        const auto queue = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
            [](const auto& row) { return row.phase != harken::EnginePlayableStartPhase::Free && row.queueMode; });
        ASSERT_NE(engine->playableServices.end(), queue);
        const auto firstRender = queue->renderHandle;
        ASSERT_NE(0u, firstRender);
        ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 1.0f));
        bool successorStarted = false;
        for (unsigned block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            ASSERT_FALSE(engine->runtimeRecreateRequired);
            if (queue->renderHandle == firstRender || queue->renderHandle == 0 ||
                engine->voices.Resolve(queue->renderHandle) == nullptr ||
                engine->mixer.BlocksRendered() * 256 < queue->startFrame + 3 * 256) continue;
            successorStarted = true;
            EXPECT_NEAR(harkentest::Peak(engine->nullBackend.LastBlock(), 512), 0.0125f, 0.001f);
            break;
        }
        ASSERT_TRUE(successorStarted);
        const auto secondRender = queue->renderHandle;
        const auto controller = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
            [&](const auto& row) { return row.rootInstance == started.instance && row.variableControlInstance.Valid(); });
        ASSERT_NE(engine->playableServices.end(), controller);
        EXPECT_EQ(harken::PlayableControlLifecycle::Active, controller->controlLifecycle);
        ASSERT_EQ(VN_OK, Vn_SetValue(variable.variableId, 3.0f));
        for (unsigned block = 0; block < 16; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const auto* voice = engine->voices.Resolve(secondRender);
            ASSERT_NE(nullptr, voice);
            if (voice->variableWeightControlCount == 1 &&
                voice->variableWeightControls[0].segment.endWeight == 0.375f &&
                engine->mixer.BlocksRendered() * 256 >= voice->variableWeightControls[0].segment.endFrame) break;
        }
        EXPECT_EQ(secondRender, queue->renderHandle);
        EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(), 512), 0.001f)
            << "lifecycle=" << static_cast<int>(controller->controlLifecycle)
            << " members=" << controller->variableControlContinuousMemberCount
            << " retarget=" << controller->variableControlRetargetPrepared
            << " applied=" << controller->variableControlRetargetApplied
            << " committed=" << controller->variableControlRetargetDecisionCommitted
            << " targetFrame=" << controller->variableControlRetargetFrame
            << " renderedFrame=" << engine->mixer.BlocksRendered() * 256;
        const auto* voice = engine->voices.Resolve(secondRender);
        ASSERT_NE(nullptr, voice);
        ASSERT_EQ(1u, voice->variableWeightControlCount);
        EXPECT_FLOAT_EQ(0.375f, voice->variableWeightControls[0].segment.endWeight);
    }
    for (unsigned block = 0; block < 160; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_FALSE(engine->runtimeRecreateRequired) << block;
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    if (loopingChild) {
        EXPECT_TRUE(engine->playableInstances.Classify(started.instance).live);
        const harken::MonitorControlCause stop{engine->monitorRequests.Begin(
            harken::MonitorRequestOrigin::StudioPreview, 4)};
        ASSERT_EQ(harken::PlayableControlStatus::Ok,
                  harken::StopPlayable(*engine, started.instance, 0, stop));
        engine->playableInstances.VisitPublishedSubtree(started.instance, [&](auto handle) {
            harken::MonitorControlCause captured{};
            EXPECT_TRUE(engine->playableInstances.CaptureControlCause(handle, &captured));
            EXPECT_EQ(stop.request.key, captured.request.key);
        });
        ASSERT_TRUE(StopUntilStale(*engine, started.instance));
        for (unsigned block = 0; block < 64 && engine->variableControlInstances.LiveCount() != 0; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
    }
    if (!loopingChild && engine->playableInstances.Classify(started.instance).live) {
        for (const auto& service : engine->playableServices) {
            if (service.phase == harken::EnginePlayableStartPhase::Free) continue;
            ADD_FAILURE() << "service=" << service.identity.slot << " root=" << service.rootInstance
                << " phase=" << static_cast<int>(service.phase)
                << " lifecycle=" << static_cast<int>(service.controlLifecycle)
                << " retiring=" << service.partitionRetiring << " queueEnd=" << service.queueNaturalEnd;
        }
    }
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(PlayableStart, VariableControlWaitsForRandomSequenceQueueAndFiniteChild) {
    for (const auto mode : {harken::ContainerModeV1::Random, harken::ContainerModeV1::Sequence,
            harken::ContainerModeV1::SequenceQueue, harken::ContainerModeV1::VariableControl}) {
        SCOPED_TRACE(static_cast<int>(mode));
        ExpectVariableControlNestedCompletion(harken::ContainerModeV1::VariableControl, mode);
    }
}

TEST(PlayableStart, VariableControlPreservesLoopingChild) {
    ExpectVariableControlNestedCompletion(harken::ContainerModeV1::VariableControl,
        harken::ContainerModeV1::VariableControl, true);
}

TEST(PlayableStart, BlendPendingParentWeightUpdatesExistingNestedMembers) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto decisionsBefore = engine->decisions.LiveCount();
    const auto groupsBefore = engine->armGroups.LiveCount();
    std::vector<float> samples(65536, 0.1f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(kSound, &pcm));
    const std::array<harken::VariableDefinitionV1, 2> variables{{
        {harkentest::ObjectId(41), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f},
        {harkentest::ObjectId(42), harken::VariableKindV1::Smooth, 0.0f, 8.0f, 3.0f}}};
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harkentest::InstallDefinitionsWorld(engine, variables.data(), variables.size()).status);
    NestedSequenceWorldImage image(engine->registry.Lookup(kSound).contentRevision);
    std::array<harken::ContainerChildProgramViewV2, 2> children{{image.nestedChildren[0], image.nestedChildren[0]}};
    children[1].stableChildOrdinal = 12;
    std::array<harken::PlayableOccurrencePropertyViewV1, 3> occurrences{{
        image.occurrences[0], image.occurrences[1], image.occurrences[0]}};
    occurrences[2].stableOccurrenceOrdinal = 12;
    occurrences[2].occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrences[2]);
    std::array<harken::GridAxisV1, 2> axes{{{0, 0, variables[1].variableId}, {0, 0, variables[0].variableId}}};
    std::array<harken::ContinuousGridCellV1, 2> cells{};
    for (unsigned i = 0; i < cells.size(); ++i) {
        cells[i].kind = harken::ContinuousCellKindV1::Interval;
        cells[i].lower = i == 0 ? 0.0f : 5.0f;
        cells[i].upper = i == 0 ? 4.0f : 8.0f;
        cells[i].lowerInclusive = cells[i].upperInclusive = 1;
    }
    std::array<harken::ContinuousGridRowViewV1, 3> grids{};
    for (unsigned i = 0; i < grids.size(); ++i) {
        grids[i].stableRowOrdinal = i + 1;
        grids[i].childStableOrdinal = i == 2 ? 21 : 11 + i;
        grids[i].cellCount = 1;
        grids[i].cells = &cells[i == 1 ? 1 : 0];
    }
    harken::CurveV1 weightCurve{};
    weightCurve.curveLocalId = 1;
    weightCurve.curve.pointCount = 2;
    weightCurve.curve.points[0] = {0.0f, 0.0f};
    weightCurve.curve.points[1] = {8.0f, 1.0f};
    auto parentCell = cells[0];
    parentCell.upper = 8.0f;
    parentCell.leftCurveLocalId = 1;
    grids[2].cells = &parentCell;
    image.containers[1].curves = &weightCurve;
    image.containers[1].curveCount = 1;
    for (unsigned i = 0; i < image.containers.size(); ++i) {
        auto& program = image.containers[i];
        program.mode = harken::ContainerModeV1::VariableControl;
        program.memoryScope = harken::MemoryScopeV1::Emitter;
        program.continuousAxisCount = 1;
        program.continuousAxes = &axes[i];
        program.continuousRowCount = i == 0 ? 2 : 1;
        program.continuousRows = &grids[i == 0 ? 0 : 2];
        program.evaluationPeriodFrames = 64;
        program.envelopeFrames = 128;
        program.maxActiveRows = program.continuousRowCount;
        program.maxLiveRows = 2;
    }
    image.containers[0].children = children.data();
    image.containers[0].childCount = children.size();
    harken::PlayableWorldViewV1 world{};
    world.generation = engine->variables.CurrentWorldGeneration();
    world.identity = image.world.identity;
    world.identity.capabilityMask |= harken::kWorldCapabilityVariableControl | harken::kWorldCapabilityVariableDefinitions;
    world.properties = image.properties.data();
    world.propertyCount = image.properties.size();
    world.occurrences = occurrences.data();
    world.occurrenceCount = occurrences.size();
    world.containers = image.containers.data();
    world.containerCount = image.containers.size();
    harken::PlayableStartRequest request{};
    request.root = image.Root();
    const auto started = harken::StartPlayable(*engine, world, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_TRUE(PumpUntilAudible(*engine));
    auto parent = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) { return row.ownerInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), parent);
    auto child = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) { return row.parentService.Valid() &&
            engine->ResolvePlayableService(row.parentService) == &*parent && row.variableControlInstance.Valid(); });
    ASSERT_NE(engine->playableServices.end(), child);
    std::array<VnVoiceHandle, 2> initialRenders{};
    ASSERT_EQ(2u, child->variableControlContinuousMemberCount);
    for (unsigned index = 0; index < initialRenders.size(); ++index) {
        std::size_t slot = 0;
        ASSERT_TRUE(engine->ResolvePlayableMemberSlot(child->scheduleStorageBase +
            child->variableControlContinuousMemberOffset + index, &slot));
        initialRenders[index] = engine->ReadPlayableMember(slot).render;
    }
    const auto nextEvaluation = child->variableControlNextEvaluationFrame;
    // Hold only the child's evaluation clock so the real parent decision can commit first.
    child->variableControlNextEvaluationFrame = UINT64_MAX;
    ASSERT_EQ(VN_OK, Vn_SetValue(variables[1].variableId, 7.0f));
    ASSERT_EQ(VN_OK, Vn_SetValue(variables[0].variableId, 1.0f));
    harken::DecisionCommittedSnapshot pending{};
    bool committed = false;
    for (unsigned block = 0; block < 64 && !committed; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        committed = parent->variableControlRetargetPrepared && parent->variableControlRetargetDecisionCommitted &&
            !parent->variableControlRetargetApplied &&
            engine->decisions.CaptureCommitted(parent->variableControlRetargetDecision, &pending) &&
            pending.audioState == harken::AudioGroupState::Pending;
        if (!committed) engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(committed);
    ASSERT_FALSE(child->variableControlRetargetPrepared);
    ASSERT_FALSE(parent->variableControlRetargetMembers.empty());
    const auto expected = parent->variableControlRetargetMembers[0].pendingWeight;
    ASSERT_FLOAT_EQ(0.125f, expected.endWeight);
    const std::array<VnObjectId, 2> ids{{variables[0].variableId, variables[1].variableId}};
    std::array<float, 2> values{};
    harken::BankVersionToken bank{};
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(0, ids.data(), ids.size(), values.data(), &bank));
    ASSERT_FLOAT_EQ(1.0f, values[0]);
    ASSERT_FLOAT_EQ(7.0f, values[1]);
    ASSERT_LT(engine->mixer.BlocksRendered() * 256, parent->variableControlRetargetFrame);
    child->variableControlNextEvaluationFrame = nextEvaluation;
    for (unsigned block = 0; block < 24; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_FALSE(engine->runtimeRecreateRequired);
    }
    const harken::VariableWeightControlIdentity parentOwner{parent->ownerInstance, parent->ownerEpoch, 1};
    for (const auto render : initialRenders) {
        const auto* voice = engine->voices.Resolve(render);
        ASSERT_NE(nullptr, voice);
        const auto* binding = std::find_if(voice->variableWeightControls.data(),
            voice->variableWeightControls.data() + voice->variableWeightControlCount,
            [&](const auto& value) { return value.owner == parentOwner; });
        ASSERT_NE(voice->variableWeightControls.data() + voice->variableWeightControlCount, binding);
        EXPECT_FLOAT_EQ(expected.endWeight, binding->segment.endWeight);
        EXPECT_EQ(expected.segmentGeneration, binding->segment.segmentGeneration);
        EXPECT_EQ(expected.decision.slot, binding->segment.decision.slot);
        EXPECT_EQ(expected.decision.generation, binding->segment.decision.generation);
    }
    EXPECT_NEAR(harkentest::Peak(engine->nullBackend.LastBlock(), 512), 0.0125f, 0.001f);
    ASSERT_EQ(VN_OK, Vn_SetValue(variables[0].variableId, 3.0f));
    for (unsigned block = 0; block < 24; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (const auto render : initialRenders) ASSERT_NE(nullptr, engine->voices.Resolve(render));
    EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(), 512), 0.001f);
    ASSERT_TRUE(StopUntilStale(*engine, started.instance));
    for (unsigned block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(groupsBefore, engine->armGroups.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

